INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(4501, 126, 'What does the acronym HTML stand for?', 'HyperText Markup Language', 'HyperText Transfer Protocol', 'HighText Machine Language', 'Hyperlink and Text Markup Language', 'A', 'HTML stands for HyperText Markup Language, the standard markup language used to structure content on the web.', 'BEGINNER', 1, 'MCQ', 1),
(4502, 126, 'Which tag is used to create a paragraph in HTML?', '<h1>', '<p>', '<a>', '<div>', 'B', 'The <p> element defines a paragraph, and browsers display its content as a block with spacing around it.', 'BEGINNER', 1, 'MCQ', 1),
(4503, 126, 'Which tag renders the largest heading on a page?', '<h6>', '<h3>', '<h1>', '<head>', 'C', 'The <h1> element is the top-level heading and is rendered with the largest font size of all heading levels.', 'BEGINNER', 1, 'MCQ', 1),
(4504, 126, 'Which attribute of an <a> tag specifies the destination URL of a link?', 'src', 'href', 'url', 'link', 'D', 'The href attribute holds the URL that a hyperlink points to, and clicking the link navigates to that address.', 'BEGINNER', 1, 'MCQ', 1),
(4505, 126, 'What is the effect of the <br> tag?', 'it inserts a single line break', 'it creates a bold line', 'it starts a new paragraph', 'it adds a horizontal rule', 'A', 'The <br> element inserts a single line break without starting a new block-level element.', 'BEGINNER', 1, 'MCQ', 1),
(4506, 126, 'Which tag defines an unordered list in HTML?', '<ol>', '<ul>', '<li>', '<list>', 'B', 'The <ul> element defines an unordered list, which browsers typically display with bullet points.', 'BEGINNER', 1, 'MCQ', 1),
(4507, 126, 'Which tag embeds an image in an HTML document?', '<image>', '<pic>', '<img>', '<photo>', 'C', 'The <img> element embeds an image using its src attribute and is a void element with no closing tag.', 'BEGINNER', 1, 'MCQ', 1),
(4508, 126, 'Which tag defines the title of the document shown in the browser tab?', '<head>', '<meta>', '<title>', '<body>', 'D', 'The <title> element, placed inside the head, supplies the text shown on the browser tab and in search results.', 'BEGINNER', 1, 'MCQ', 1),
(4509, 126, 'Which declaration must appear as the very first line of an HTML5 document?', '<!DOCTYPE html>', '<!DOCTYPE HTML5>', '<html lang=''en''>', '<meta charset=''utf-8''>', 'A', 'The <!DOCTYPE html> declaration tells the browser to render the page in standards mode using HTML5.', 'BEGINNER', 1, 'MCQ', 1),
(4510, 126, 'Which attribute of the <html> tag declares the primary language of the page?', 'lang', 'code', 'locale', 'charset', 'B', 'The lang attribute on the <html> element declares the document''s primary language, helping screen readers and search engines.', 'BEGINNER', 1, 'MCQ', 1),
(4511, 126, 'What is the difference between an HTML element and an attribute?', 'an attribute is a keyword written inside the start tag that configures the element', 'an attribute is another name for the element content', 'an element can never have attributes', 'an attribute is a closing tag', 'A', 'Attributes are name-value pairs written inside the start tag that configure how the element behaves.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4512, 126, 'Which element is the most appropriate container for a block of navigation links?', '<footer>', '<nav>', '<aside>', '<section>', 'B', 'The <nav> element semantically marks a section of the page intended for navigation links.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4513, 126, 'Which element is used for the main content that is unique to a single page?', '<div>', '<content>', '<main>', '<body>', 'C', 'The <main> element contains the dominant unique content of a page and should appear only once per document.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4514, 126, 'Which of the following shows correctly nested HTML?', '<ul><li>Item</ul></li>', '<ul></ul><li>Item</li>', '<li><ul></ul></li>', '<ul><li>Item</li></ul>', 'D', 'The <li> element must be closed before its parent <ul> closes, so the last option is the only valid nesting.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4515, 126, 'Why are semantic elements such as <header> and <article> preferred over generic <div> tags?', 'they make pages load faster', 'they reduce file size', 'they give structure meaning to browsers, screen readers and search engines', 'they automatically add styling', 'C', 'Semantic elements describe their role in the document, improving accessibility and search engine understanding.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4516, 126, 'Which tag marks text that carries strong importance?', '<b>', '<strong>', '<em>', '<i>', 'B', 'The <strong> element indicates strong importance and, unlike <b>, carries semantic meaning.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4517, 126, 'Which attribute of <img> supplies text that is shown when the image cannot load?', 'src', 'title', 'alt', 'href', 'C', 'The alt attribute provides fallback descriptive text and is important for accessibility when an image fails to load.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4518, 126, 'How do you write a comment in HTML?', '// comment', '/* comment */', '# comment', '<!-- comment -->', 'D', 'HTML comments begin with <!-- and end with -->, and their content is ignored by the browser.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4519, 126, 'How do you make an image act as a clickable link?', 'wrap the <img> inside an <a> element', 'add an href attribute to the <img>', 'use the <link> element', 'set the onclick attribute to a URL', 'A', 'Nesting an <img> inside an <a> element makes the image navigate to the link''s href when clicked.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4520, 126, 'Which attribute of a <meta> tag declares the character encoding of the document?', 'encoding', 'charset', 'code', 'utf', 'B', 'The charset attribute on a <meta> tag declares the character encoding, commonly utf-8, used by the document.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4521, 126, 'Why is associating every form control with a <label> considered best practice?', 'it improves accessibility and gives users a larger click target for the control', 'it forces the form to use HTTPS', 'it prevents duplicate form submissions', 'it automatically encrypts the submitted data', 'A', 'Explicit label associations help screen readers announce each field and enlarge the clickable area of the control.', 'ADVANCED', 3, 'MCQ', 1),
(4522, 126, 'Which attribute tells the browser to defer loading of an image until it is near the viewport?', 'preload', 'loading=''lazy''', 'defer', 'async', 'B', 'The loading=''lazy'' attribute lets the browser postpone fetching an image until it approaches the visible area, saving bandwidth.', 'ADVANCED', 3, 'MCQ', 1),
(4523, 126, 'A purely decorative image that adds no information is being added to a page. What is the best practice for its alt attribute?', 'repeat the page title in alt', 'describe the colors in alt', 'leave alt out or set alt='''' so screen readers skip it', 'add the file name as alt text', 'C', 'Decorative images should have empty alt text so assistive technology ignores them rather than announcing meaningless content.', 'ADVANCED', 3, 'MCQ', 1),
(4524, 126, 'Which <meta> tag is essential for pages that must render correctly on mobile devices?', '<meta name=''mobile'' content=''on''>', '<meta name=''layout'' content=''responsive''>', '<meta name=''screen'' content=''auto''>', '<meta name=''viewport'' content=''width=device-width, initial-scale=1''>', 'D', 'The viewport meta tag controls how the page scales on mobile so it does not render as a shrunken desktop layout.', 'ADVANCED', 3, 'MCQ', 1),
(4525, 126, 'An external stylesheet in the <head> blocks the first paint of a page. What is the recommended way to load a small set of critical styles?', 'inline the critical CSS and defer the full stylesheet', 'remove all CSS from the page', 'use a table for layout', 'load the stylesheet with a JavaScript timer', 'A', 'Inlining critical CSS lets the browser paint immediately while the full stylesheet loads asynchronously, improving perceived performance.', 'ADVANCED', 3, 'MCQ', 1),
(4526, 126, 'A search icon button contains only an SVG with no visible text. Which attribute best gives it an accessible name?', 'aria-label', 'aria-hidden', 'role=''button''', 'tabindex=''0''', 'B', 'The aria-label attribute provides an accessible name for elements whose visible content is only an icon or image.', 'ADVANCED', 3, 'MCQ', 1),
(4527, 126, 'Which resource hint should be used when you know a hero image is needed immediately on page load?', 'preconnect', 'dns-prefetch', 'preload', 'prefetch', 'C', 'The preload hint tells the browser to fetch a resource that is certain to be needed soon, such as a hero image.', 'ADVANCED', 3, 'MCQ', 1),
(4528, 126, 'Which element provides a descriptive title for a data table that is read aloud by screen readers?', '<title>', '<summary>', '<header>', '<caption>', 'D', 'The <caption> element supplies a descriptive title for a table that assistive technology announces to users.', 'ADVANCED', 3, 'MCQ', 1),
(4529, 126, 'Which meta tag is used by search engines to display a summary snippet under the page title in results?', 'description', 'keywords', 'author', 'robots', 'A', 'The meta description tag provides a short summary that search engines often show as the snippet under the title.', 'ADVANCED', 3, 'MCQ', 1),
(4530, 126, 'Which element in the <head> registers the small icon displayed next to the page title in the browser tab?', '<img>', '<link rel=''icon''>', '<icon>', '<favicon>', 'B', 'A <link> element with rel=''icon'' points to the favicon image shown in the browser tab and bookmarks.', 'ADVANCED', 3, 'MCQ', 1),
(4531, 127, 'Which tag creates an HTML form?', '<form>', '<input>', '<fieldset>', '<submit>', 'A', 'The <form> element wraps the form controls and carries the action and method for submitting data.', 'BEGINNER', 1, 'MCQ', 1),
(4532, 127, 'Which input type creates a single-line text field?', 'textarea', 'text', 'select', 'button', 'B', 'The input type text renders a single-line text box where users can type a short value.', 'BEGINNER', 1, 'MCQ', 1),
(4533, 127, 'Which input type renders a button that submits the form?', 'reset', 'button', 'submit', 'click', 'C', 'An input of type submit sends the form data to the server using the form''s action and method.', 'BEGINNER', 1, 'MCQ', 1),
(4534, 127, 'Which attribute of a form control gives it the name that is sent to the server?', 'id', 'value', 'class', 'name', 'D', 'The name attribute identifies the field in the submitted data, so the server receives name=value pairs.', 'BEGINNER', 1, 'MCQ', 1),
(4535, 127, 'Which element lets the user choose an option from a drop-down list?', '<select>', '<list>', '<option>', '<dropdown>', 'A', 'The <select> element renders a drop-down list, with each choice defined by a nested <option> element.', 'BEGINNER', 1, 'MCQ', 1),
(4536, 127, 'Which element defines a multi-line text input area?', '<textbox>', '<textarea>', '<multiline>', '<input type=''area''>', 'B', 'The <textarea> element renders a multi-line text area that accepts longer free-form input.', 'BEGINNER', 1, 'MCQ', 1),
(4537, 127, 'Which input type allows the user to select exactly one value from a set of choices?', 'checkbox', 'radio', 'select', 'range', 'C', 'Radio buttons let a user pick one value from a group because all radios sharing a name behave as a single choice.', 'BEGINNER', 1, 'MCQ', 1),
(4538, 127, 'Which attribute of the <form> element specifies where the submitted data is sent?', 'method', 'action', 'target', 'name', 'D', 'The action attribute holds the URL to which the form data is submitted when the form is sent.', 'BEGINNER', 1, 'MCQ', 1),
(4539, 127, 'Which input type is used to collect email addresses and provides built-in format validation?', 'email', 'text', 'string', 'mail', 'A', 'The email input type validates that the typed value has the shape of an email address before submission.', 'BEGINNER', 1, 'MCQ', 1),
(4540, 127, 'Which attribute of a checkbox sets the value that is sent when the box is checked?', 'value', 'name', 'checked', 'data', 'B', 'The value attribute defines the data submitted for a checked box, and the name identifies it in the payload.', 'BEGINNER', 1, 'MCQ', 1),
(4541, 127, 'What is the main difference between the GET and POST methods of a form?', 'GET appends data to the URL while POST sends it in the request body', 'GET is always faster than POST', 'POST cannot send form data', 'GET encrypts all submitted data', 'A', 'GET places submitted data in the URL query string, while POST carries it in the request body, so GET is inappropriate for sensitive data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4542, 127, 'Which attribute prevents a user from editing the value of an input field?', 'disabled', 'readonly', 'locked', 'static', 'B', 'The readonly attribute keeps the field displayable and submittable while preventing the user from changing its value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4543, 127, 'Which attribute makes a form control mandatory so the form cannot be submitted without it?', 'required', 'mandatory', 'validate', 'need', 'C', 'The required attribute marks a control as mandatory, and the browser blocks submission until it is filled.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4544, 127, 'Which element visually groups related form controls with a surrounding box and a caption?', '<legend>', '<fieldset>', '<group>', '<section>', 'D', 'The <fieldset> element draws a box around related controls, and a <legend> supplies its caption.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4545, 127, 'Which input type renders a numeric field with spinner arrows and restricts values to numbers?', 'number', 'range', 'digit', 'numeric', 'A', 'The number input type provides a numeric field with stepper controls and rejects non-numeric input.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4546, 127, 'Which input type validates that the value entered is a well-formed URL?', 'link', 'url', 'web', 'address', 'B', 'The url input type applies format validation to ensure the value is a valid absolute or relative URL.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4547, 127, 'Which element provides the caption for a group defined inside a <fieldset>?', '<label>', '<title>', '<legend>', '<summary>', 'C', 'The <legend> element supplies the caption that describes the purpose of the group inside a fieldset.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4548, 127, 'How do you make one option the default selection in a drop-down list?', 'add the selected attribute to that <option>', 'put it first in the list', 'add the active attribute to it', 'set the form''s default attribute', 'A', 'Adding the selected attribute to an <option> makes it the preselected value when the page loads.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4549, 127, 'Which attribute makes a checkbox appear already ticked when the page loads?', 'selected', 'ticked', 'checked', 'enabled', 'C', 'The checked attribute pre-toggles a checkbox or radio so it appears selected on page load.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4550, 127, 'What is the purpose of the placeholder attribute on an input field?', 'it shows hint text inside the field before the user types', 'it stores the final value', 'it prevents the field from being empty', 'it labels the field for screen readers', 'B', 'The placeholder attribute displays hint text inside the field that disappears once the user starts typing.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4551, 127, 'Which practice is most important for protecting a server-side form handler from cross-site scripting (XSS)?', 'escape or sanitize all user input before rendering it back', 'use POST instead of GET', 'add a captcha to every form', 'disable HTML in text areas', 'A', 'Escaping or sanitizing untrusted input before it is rendered prevents malicious script from executing in users'' browsers.', 'ADVANCED', 3, 'MCQ', 1),
(4552, 127, 'Why should the autocomplete attribute be set to off for a form that collects credit card data?', 'it prevents the browser from saving sensitive values for later autofill', 'it makes the form submit faster', 'it is required by the HTML spec', 'it disables the submit button', 'B', 'Setting autocomplete to off stops the browser from offering to store sensitive values, reducing the risk of exposing them.', 'ADVANCED', 3, 'MCQ', 1),
(4553, 127, 'When validating a file upload input, which checks are most important in a production system?', 'validate the file type, size and contents on the server', 'only check the file extension', 'rely solely on the input''s accept attribute', 'allow any file but rename it', 'C', 'Client-side accept hints can be bypassed, so the server must validate type, size and content before accepting a file.', 'ADVANCED', 3, 'MCQ', 1),
(4554, 127, 'What is a CSRF token and why is it included in a form?', 'a unique token verified by the server to confirm the request came from the real user', 'a token that encrypts the form data', 'a token that speeds up form submission', 'a token that stores the user''s password', 'D', 'A CSRF token is a server-generated secret embedded in the form that validates the request origin, blocking cross-site request forgery.', 'ADVANCED', 3, 'MCQ', 1),
(4555, 127, 'Which approach is best for showing a form validation error to an assistive technology user?', 'link the error text to the field with aria-describedby and set aria-invalid', 'change only the text color of the field', 'use an alert() dialog', 'hide the error text entirely', 'A', 'Associating error text with the field using aria-describedby and aria-invalid lets screen readers announce the problem reliably.', 'ADVANCED', 3, 'MCQ', 1),
(4556, 127, 'A search box sits outside the <form> element. Which attribute connects it to that form?', 'the form attribute on the input set to the form''s id', 'the name attribute on the input', 'the action attribute on the input', 'the target attribute on the form', 'B', 'The form attribute on an input, set to the id of a form, associates the control with a form it is not nested inside.', 'ADVANCED', 3, 'MCQ', 1),
(4557, 127, 'Why do production search boxes use debouncing when triggering a search as the user types?', 'it limits network requests until the user pauses, reducing server load', 'it makes the request smaller', 'it forces the user to press Enter', 'it disables autocomplete', 'C', 'Debouncing waits until the user stops typing briefly before sending a request, cutting down on wasteful network calls.', 'ADVANCED', 3, 'MCQ', 1),
(4558, 127, 'Which combination best protects a password field in a login form?', 'type=''password'' plus a minimum length enforced on the server', 'type=''text'' with a visible toggle', 'type=''password'' with no validation', 'storing the password in the URL', 'A', 'A password input hides the typed value, and server-side length and strength checks secure it beyond the visible masking.', 'ADVANCED', 3, 'MCQ', 1),
(4559, 127, 'When is the enctype=''multipart/form-data'' attribute required on a form?', 'when the form uploads one or more files', 'when the form sends only text', 'when using the GET method', 'when the form has no action', 'D', 'Multipart encoding is required when a form contains file inputs, because files cannot be sent in ordinary URL encoding.', 'ADVANCED', 3, 'MCQ', 1),
(4560, 127, 'What does the novalidate attribute on a <form> do?', 'it disables all built-in client-side validation for the form', 'it removes the required attributes', 'it disables the submit button', 'it skips sending the data', 'A', 'The novalidate attribute turns off the browser''s built-in constraint validation so the page controls validation itself.', 'ADVANCED', 3, 'MCQ', 1),
(4561, 128, 'What does the acronym CSS stand for?', 'Cascading Style Sheets', 'Computer Style Syntax', 'Creative Style Sheets', 'Cascading Sheet System', 'A', 'CSS stands for Cascading Style Sheets, the language used to describe the presentation of HTML documents.', 'BEGINNER', 1, 'MCQ', 1),
(4562, 128, 'Which element links an external stylesheet to an HTML document?', '<style>', '<link rel=''stylesheet''>', '<css>', '<script>', 'B', 'A <link> element with rel=''stylesheet'' connects the document to an external CSS file.', 'BEGINNER', 1, 'MCQ', 1),
(4563, 128, 'Which CSS property changes the color of text?', 'text-color', 'font-color', 'color', 'background', 'C', 'The color property sets the foreground color of text in an element.', 'BEGINNER', 1, 'MCQ', 1),
(4564, 128, 'Which CSS property changes the background color of an element?', 'background-color', 'backcolor', 'bgcolor', 'fill', 'A', 'The background-color property paints the area behind the content of an element with the chosen color.', 'BEGINNER', 1, 'MCQ', 1),
(4565, 128, 'How do you apply a style to every <p> element on the page?', '#p { }', '.p { }', 'p { }', 'paragraph { }', 'C', 'Writing a type selector with the tag name p applies the rules to every paragraph element.', 'BEGINNER', 1, 'MCQ', 1),
(4566, 128, 'Which selector targets an element by its id attribute?', '#id', '.id', '*id', '@id', 'B', 'A selector starting with a hash symbol matches the element whose id equals that value.', 'BEGINNER', 1, 'MCQ', 1),
(4567, 128, 'Which selector targets an element by its class attribute?', '#class', '.class', '%class', '&class', 'C', 'A selector starting with a dot matches every element that has the given class.', 'BEGINNER', 1, 'MCQ', 1),
(4568, 128, 'Which CSS property sets the font family used for text?', 'font-style', 'font-weight', 'text-font', 'font-family', 'D', 'The font-family property lists the typefaces used for the text, such as Arial or serif.', 'BEGINNER', 1, 'MCQ', 1),
(4569, 128, 'How do you write a comment in CSS?', '/* comment */', '// comment', '<!-- comment -->', '# comment', 'A', 'CSS comments are enclosed between /* and */ and are ignored by the browser.', 'BEGINNER', 1, 'MCQ', 1),
(4570, 128, 'Which CSS property controls the size of text?', 'text-size', 'font-height', 'font-size', 'text-height', 'B', 'The font-size property sets the height of the font, controlling how large the text appears.', 'BEGINNER', 1, 'MCQ', 1),
(4571, 128, 'In the cascade, which selector generally has higher specificity?', 'a type selector', 'a class selector', 'a universal selector', 'a list item selector', 'B', 'Class selectors carry higher specificity than type selectors, so class rules override conflicting type rules.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4572, 128, 'When should an id selector be used in CSS?', 'only once per page for a unique element, such as a page header', 'for every element that repeats', 'never, ids are invalid', 'whenever styling is needed', 'A', 'Because ids must be unique, an id selector should target a single one-of-a-kind element rather than reusable patterns.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4573, 128, 'What does the selector div p match?', 'a p element that is a descendant of a div', 'a p element directly inside a div', 'a div directly inside a p', 'both div and p elements', 'B', 'A space between selectors is a descendant combinator, matching p elements nested at any depth inside a div.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4574, 128, 'Which pseudo-class applies styles when the mouse hovers over an element?', ':active', ':focus', ':hover', ':visited', 'C', 'The :hover pseudo-class matches an element while the pointer is positioned over it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4575, 128, 'Which of these is a valid hex color value?', '#gg1234', '#123456', '#12345', '#12', 'B', 'Hex colors have exactly six hexadecimal digits, and #123456 is a valid six-digit hex color.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4576, 128, 'What effect does the !important declaration have on a CSS rule?', 'it raises the rule''s priority above normal source-order and specificity decisions', 'it makes the rule load faster', 'it is ignored by all browsers', 'it deletes the rule', 'A', 'The !important declaration overrides normal cascade ordering, although overusing it makes styles harder to maintain.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4577, 128, 'What does the selector div > p match?', 'a p that is a direct child of a div', 'any p inside a div', 'a div inside a p', 'a p or a div on the page', 'C', 'The greater-than sign is the child combinator, matching only p elements whose direct parent is a div.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4578, 128, 'How do you apply the same rule to several selectors at once?', 'separate them with commas', 'separate them with spaces', 'nest them in braces', 'repeat the rule multiple times', 'A', 'Comma-separating selectors such as h1, h2 { } applies the same declaration block to all of them.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4579, 128, 'Which rule would win when both a type selector and a class selector target the same element?', 'the type selector always wins', 'the class selector wins due to higher specificity', 'the last one in the file wins', 'the rule with more declarations wins', 'B', 'A class selector has higher specificity than a type selector, so its declarations take precedence regardless of order.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4580, 128, 'Which selector matches an <input> whose type attribute equals text?', 'input[type=''text'']', 'input.text', 'input#text', 'input::text', 'A', 'An attribute selector inside brackets matches elements whose attribute exactly equals the given value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4581, 128, 'You cannot override an unwanted style from a third-party library because of specificity. What is the cleanest remedy?', 'add a more specific selector of your own instead of resorting to !important', 'add !important to a random rule', 'remove the library', 'use inline styles everywhere', 'A', 'Raising specificity with a deliberate selector keeps the cascade maintainable, whereas !important compounds future conflicts.', 'ADVANCED', 3, 'MCQ', 1),
(4582, 128, 'Given li:nth-child(3), which list item is selected?', 'the first item', 'the third item', 'the last item', 'every third item', 'B', 'nth-child(3) matches the element that is the third child of its parent.', 'ADVANCED', 3, 'MCQ', 1),
(4583, 128, 'Why are CSS custom properties, such as --brand-color, recommended for large design systems?', 'they centralize values so a theme can change in one place', 'they are faster than plain colors', 'they replace all of CSS', 'they are required by the HTML spec', 'C', 'Custom properties store values once so changing the theme or brand requires editing only the variable definition.', 'ADVANCED', 3, 'MCQ', 1),
(4584, 128, 'An inline style on an element conflicts with a stylesheet rule. Which declaration wins?', 'the stylesheet rule always wins', 'the inline style wins because it has higher specificity', 'the browser decides randomly', 'neither applies', 'B', 'Inline styles have higher specificity than any selector in the stylesheet, so they override those declarations.', 'ADVANCED', 3, 'MCQ', 1),
(4585, 128, 'How does a browser style an element that has no rule matching it at all?', 'it uses its default user-agent stylesheet', 'it leaves the element unstyled', 'it applies the parent''s styles', 'it removes the element', 'A', 'When no author rule matches, the browser''s user-agent stylesheet supplies the default rendering.', 'ADVANCED', 3, 'MCQ', 1),
(4586, 128, 'For the rule div p { color: red; } and div p { color: blue; }, which color applies and why?', 'blue, because both have equal specificity and blue comes later in source order', 'red, because it appears first', 'both colors apply', 'neither applies', 'A', 'With identical specificity, the cascade falls back to source order and the later blue declaration wins.', 'ADVANCED', 3, 'MCQ', 1),
(4587, 128, 'What is the difference between the :is() and :where() pseudo-classes?', ':is() adds the specificity of its most specific argument, while :where() always has zero specificity', ':where() is faster than :is()', ':is() only works on classes', ':where() cannot accept lists', 'C', 'Both match any selector in the list, but :where() contributes zero specificity, which is useful for baseline resets.', 'ADVANCED', 3, 'MCQ', 1),
(4588, 128, 'Which properties are inherited by child elements by default?', 'font-family and color are inherited, but margin and padding are not', 'margin and padding are inherited', 'background-color is inherited', 'all properties are inherited', 'A', 'Text-related properties like font-family and color inherit, while box properties like margin and padding do not.', 'ADVANCED', 3, 'MCQ', 1),
(4589, 128, 'Inlining the critical CSS of a page is a technique used primarily to improve what?', 'the first paint of the page so it renders before the full stylesheet loads', 'search engine rankings', 'the accuracy of the color palette', 'server security', 'B', 'Critical CSS inlining lets the browser style above-the-fold content immediately, speeding up the first render.', 'ADVANCED', 3, 'MCQ', 1),
(4590, 128, 'Consider var(--spacing, 8px). What happens if --spacing is not defined?', 'the fallback value 8px is used', 'the declaration is ignored', 'the browser throws an error', 'the value becomes auto', 'A', 'The second argument of var() is a fallback that is used whenever the custom property is undefined or invalid.', 'ADVANCED', 3, 'MCQ', 1),
(4591, 129, 'What is the default display value of a <div> element?', 'inline', 'block', 'flex', 'none', 'B', 'A div is a block-level element, so it takes the full width available and starts on a new line.', 'BEGINNER', 1, 'MCQ', 1),
(4592, 129, 'What is the default display value of a <span> element?', 'block', 'inline', 'flex', 'grid', 'B', 'A span is an inline element, so it flows with surrounding text and only takes as much width as needed.', 'BEGINNER', 1, 'MCQ', 1),
(4593, 129, 'Which property turns an element into a flex container?', 'position: flex', 'display: flex', 'flex: true', 'layout: flex', 'B', 'Setting display to flex makes an element a flex container so its children become flex items.', 'BEGINNER', 1, 'MCQ', 1),
(4594, 129, 'Which property sets the direction of the main axis in a flex container?', 'flex-flow', 'flex-direction', 'align-main', 'flex-orient', 'B', 'The flex-direction property sets the main axis, choosing between row and column and their reverses.', 'BEGINNER', 1, 'MCQ', 1),
(4595, 129, 'Which property aligns flex items along the main axis?', 'justify-content', 'align-items', 'text-align', 'flex-align', 'A', 'justify-content controls the distribution of items along the main axis of the flex container.', 'BEGINNER', 1, 'MCQ', 1),
(4596, 129, 'Which property aligns flex items along the cross axis?', 'justify-content', 'align-items', 'cross-align', 'vertical-align', 'B', 'align-items positions flex items along the cross axis, which is perpendicular to the main axis.', 'BEGINNER', 1, 'MCQ', 1),
(4597, 129, 'What is the effect of the CSS float property on an element?', 'it makes the element expand to fill the parent', 'it pulls the element to the left or right so text flows around it', 'it centers the element', 'it hides the element', 'C', 'Floating an element moves it left or right within its container while surrounding content flows beside it.', 'BEGINNER', 1, 'MCQ', 1),
(4598, 129, 'Which property sets the horizontal width of an element?', 'height', 'width', 'size', 'extent', 'D', 'The width property defines the horizontal size of an element''s content box.', 'BEGINNER', 1, 'MCQ', 1),
(4599, 129, 'How do you horizontally center a block element of fixed width inside its parent?', 'set margin-left and margin-right to auto', 'use text-align: center', 'use justify-content: center', 'set position: center', 'A', 'Auto left and right margins evenly split the remaining space so a fixed-width block centers horizontally.', 'BEGINNER', 1, 'MCQ', 1),
(4600, 129, 'Which property adds space between an element''s content and its border?', 'margin', 'padding', 'border-spacing', 'inset', 'B', 'The padding property creates space between the content and the inner edge of the border.', 'BEGINNER', 1, 'MCQ', 1),
(4601, 129, 'What does flex-grow: 1 on a flex item allow it to do?', 'shrink below its content size', 'grow to fill any extra space in the container', 'stay at its base width', 'move to the next line', 'B', 'flex-grow distributes leftover space, so an item with flex-grow: 1 grows to consume available room.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4602, 129, 'What is the difference between align-items and align-content?', 'align-content distributes whole lines of flex items, while align-items aligns items within a single line', 'align-items works on the main axis', 'align-content only works with block layout', 'they are identical', 'A', 'align-items aligns each item across the cross axis, whereas align-content only affects multi-line containers by spacing the lines.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4603, 129, 'What does the order property do in a flex container?', 'it changes the visual order of a flex item', 'it sets the stacking order of z-index', 'it sorts the content alphabetically', 'it reorders the HTML', 'B', 'The order property repositions a flex item in the visual sequence without changing the document order.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4604, 129, 'Which property adds space between flex items without adding margin to the edges of the container?', 'spacing', 'gap', 'offset', 'distance', 'C', 'The gap property sets uniform spacing between flex items while leaving the outer edges of the container untouched.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4605, 129, 'What happens when flex-wrap: wrap is set on a container that is too narrow for all items?', 'the items overflow the container', 'the items shrink to fit one line', 'items wrap onto additional lines', 'the container widens automatically', 'C', 'With flex-wrap set to wrap, flex items flow onto new lines when they no longer fit on the current one.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4606, 129, 'What does align-self: center do on a single flex item?', 'it centers the item along the cross axis, overriding align-items for that item', 'it centers the whole container', 'it centers the item on the main axis', 'it ignores the flex layout', 'A', 'align-self overrides the container''s align-items value for that one item, centering it along the cross axis.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4607, 129, 'What is the standard way to center a child both horizontally and vertically with flexbox?', 'set justify-content: center and align-items: center on the parent', 'set margin: auto on the parent', 'use text-align: center only', 'use position: fixed', 'A', 'Centering both alignments requires the parent to center along both axes using justify-content and align-items.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4608, 129, 'What does the shorthand flex: 1 1 0% mean for a flex item?', 'flex-grow is 1, flex-shrink is 1 and flex-basis is 0', 'flex-grow is 0, flex-shrink is 1 and flex-basis is 1', 'the item never grows', 'the item has no width', 'B', 'The shorthand lists grow, shrink and basis in order, so flex: 1 1 0% sets each of those three values.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4609, 129, 'What is the difference between margin and padding in the box model?', 'margin is space outside the border and padding is space inside the border', 'margin is space inside and padding is outside', 'margin is vertical and padding is horizontal', 'they are the same thing', 'A', 'Margin separates the element from outside content, while padding adds space inside the element between content and border.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4610, 129, 'What is the effect of box-sizing: border-box on an element?', 'the width includes padding and border instead of adding to them', 'the width excludes the border', 'padding is ignored', 'the height becomes fixed', 'C', 'With border-box, the specified width already includes padding and border, which simplifies sizing calculations.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4611, 129, 'You need a full-height sticky header, a footer, and a content area that grows. Which flex pattern solves this best?', 'make the body a column flex container and let the content flex-grow', 'float the content below the header', 'use absolute positioning for everything', 'set fixed heights on all sections', 'A', 'A column flex container whose content has flex-grow fills leftover space while keeping header and footer in place.', 'ADVANCED', 3, 'MCQ', 1),
(4612, 129, 'When is CSS Grid a better choice than Flexbox?', 'when the layout is two-dimensional with rows and columns', 'when arranging a single row of items', 'when centering one item', 'when laying out inline text', 'B', 'Grid excels at two-dimensional layouts that control both rows and columns, whereas flexbox handles one axis well.', 'ADVANCED', 3, 'MCQ', 1),
(4613, 129, 'A flex item refuses to shrink below its content and overflows. Which property fixes this?', 'min-width: 0 on the flex item', 'max-height: 100% on the container', 'flex-grow: 0', 'overflow: visible on the parent', 'C', 'Flex items default to a min-width of auto, and setting min-width to 0 lets the item shrink below its content size.', 'ADVANCED', 3, 'MCQ', 1),
(4614, 129, 'What is the difference between position: fixed and position: sticky?', 'sticky stays in flow and only becomes fixed after reaching a scroll threshold', 'fixed stays inside the parent box', 'sticky ignores scrolling', 'they are identical', 'A', 'Sticky elements remain in normal flow until the scroll reaches the defined offset, after which they behave like fixed.', 'ADVANCED', 3, 'MCQ', 1),
(4615, 129, 'Why do flex items sometimes overlap or clip content when the container has a fixed height?', 'because align-items defaults to stretch but items can overflow if content is too tall', 'because margin is never included', 'because flex-shrink always shrinks to zero', 'because the height property is invalid', 'D', 'Stretch alignment combined with a fixed container height can cause items to overflow when their content exceeds the space.', 'ADVANCED', 3, 'MCQ', 1),
(4616, 129, 'Which approach builds a responsive navigation bar whose links wrap to new rows on small screens?', 'a flex container with flex-wrap: wrap and a gap', 'a table layout', 'a fixed-width div', 'inline styles on every link', 'A', 'Wrapping plus a gap lets the nav links reflow onto new lines naturally as the viewport narrows.', 'ADVANCED', 3, 'MCQ', 1),
(4617, 129, 'What does margin-left: auto do to a flex item inside a row-direction container?', 'it pushes the item to the far right by absorbing the free space', 'it centers the item', 'it removes the item''s margin', 'it makes the item grow', 'C', 'An auto margin absorbs all free space on that side, pushing the item flush against the opposite edge.', 'ADVANCED', 3, 'MCQ', 1),
(4618, 129, 'A flex item''s content is too wide and forces the container to scroll horizontally. What fixes the overflow?', 'set min-width: 0 on the flex item so it can shrink', 'set width to 100vw', 'remove the container''s height', 'add a larger margin', 'A', 'Giving the item min-width: 0 removes the automatic content minimum so it can shrink to fit the container.', 'ADVANCED', 3, 'MCQ', 1),
(4619, 129, 'Why is the gap property preferred over margins for spacing flex items?', 'it avoids uneven outer spacing and double margins between adjacent items', 'it is faster to write with fewer characters', 'it works with inline elements', 'it is required by all browsers', 'B', 'Gap applies spacing only between items, avoiding the edge gaps and doubled margins that come from adding margins manually.', 'ADVANCED', 3, 'MCQ', 1),
(4620, 129, 'What is the auto minimum size of a flex item and how does it affect layout?', 'it is the item''s min-content size, which prevents shrinking smaller than the content unless overridden', 'it is always zero', 'it is the parent''s width', 'it is the maximum size', 'A', 'By default a flex item cannot shrink below its content''s minimum size, which must be overridden with min-width to allow smaller sizes.', 'ADVANCED', 3, 'MCQ', 1),
(4621, 130, 'What does responsive web design mean?', 'designing pages that adapt their layout to different screen sizes and devices', 'making pages faster', 'using only mobile phones', 'using the same font everywhere', 'A', 'Responsive design uses fluid layouts and media queries so a page renders well across desktops, tablets and phones.', 'BEGINNER', 1, 'MCQ', 1),
(4622, 130, 'Which tag is required for a page to scale correctly on mobile screens?', '<meta name=''viewport'' content=''width=device-width, initial-scale=1''>', '<link rel=''responsive''>', '<style>', '<script>', 'A', 'The viewport meta tag controls the visible area width so mobile browsers do not shrink the whole page.', 'BEGINNER', 1, 'MCQ', 1),
(4623, 130, 'Which CSS unit is relative to the width of the viewport?', 'rem', 'em', 'vw', 'px', 'C', 'One vw equals one percent of the viewport width, so text sized in vw scales with the screen width.', 'BEGINNER', 1, 'MCQ', 1),
(4624, 130, 'Which media query feature checks the width of the viewport to apply breakpoints?', 'max-width', 'max-height', 'screen-size', 'device-pixel', 'A', 'The max-width feature inside a media query applies the styles only when the viewport is at most that width.', 'BEGINNER', 1, 'MCQ', 1),
(4625, 130, 'Which CSS unit is relative to the root element''s font size?', 'em', 'rem', 'vh', 'cm', 'B', 'One rem equals the font size of the html root element, making it predictable regardless of nesting.', 'BEGINNER', 1, 'MCQ', 1),
(4626, 130, 'Which property smoothly animates a change of style over a duration?', 'animation', 'transition', 'transform', 'transition-delay', 'B', 'The transition property animates a change from one computed style to another over the given duration.', 'BEGINNER', 1, 'MCQ', 1),
(4627, 130, 'Which at-rule is used to define keyframe animation steps?', '@media', '@import', '@keyframes', '@font-face', 'C', 'The @keyframes rule defines the intermediate steps that an animation moves through.', 'BEGINNER', 1, 'MCQ', 1),
(4628, 130, 'Which property sets how long a transition takes to complete?', 'transition-delay', 'transition-timing', 'transition-duration', 'transition-count', 'C', 'The transition-duration property specifies how many seconds or milliseconds the transition lasts.', 'BEGINNER', 1, 'MCQ', 1),
(4629, 130, 'Which CSS unit is relative to the parent element''s font size?', 'rem', 'vw', 'em', 'vh', 'C', 'One em equals the font size of the parent element, so em values scale with inherited text size.', 'BEGINNER', 1, 'MCQ', 1),
(4630, 130, 'Which property sets the delay before a transition starts?', 'transition-delay', 'transition-duration', 'transition-speed', 'transition-pause', 'B', 'The transition-delay property inserts a wait before the transition begins to animate.', 'BEGINNER', 1, 'MCQ', 1),
(4631, 130, 'Which of the following is a valid media query?', '@media (max-width: 600px) { }', '@media max-width 600px { }', '@media screen 600 { }', '@query (max-width: 600px) { }', 'A', 'A media query is written with the @media at-rule followed by a parenthesized feature such as max-width.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4632, 130, 'What is the difference between @media (max-width: 600px) and @media (min-width: 600px)?', 'max-width applies below 600px while min-width applies at and above 600px', 'they are identical', 'min-width applies below 600px', 'max-width applies at all sizes', 'B', 'A max-width query targets viewports up to a limit, while a min-width query targets viewports from that limit upward.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4633, 130, 'What does the mobile-first design approach mean?', 'write base styles for small screens, then add min-width media queries to enhance larger screens', 'design only for phones', 'use the largest font sizes', 'ignore media queries', 'A', 'Mobile-first starts with the mobile layout as the default and progressively enhances it as the screen grows.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4634, 130, 'What is the difference between a transition and an animation?', 'animations run without user interaction and can loop, while transitions require a state change', 'transitions can loop', 'animations cannot run automatically', 'they are the same', 'A', 'Transitions react to style changes, whereas animations play automatically and can repeat without any trigger.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4635, 130, 'Which CSS unit is relative to the height of the viewport?', 'vh', 'vw', 'vmin', 'rem', 'A', 'One vh equals one percent of the viewport height, letting elements size relative to the visible screen.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4636, 130, 'What is a breakpoint in responsive design?', 'a viewport width where the layout changes to suit the available space', 'a point where the page crashes', 'a line in the CSS file', 'the border of an element', 'A', 'A breakpoint is the width at which a media query kicks in to rearrange the layout for the current screen size.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4637, 130, 'What does the cubic-bezier() function control in a transition?', 'the timing and easing of the animation over its duration', 'the final color', 'the number of repeats', 'the duration in seconds', 'C', 'cubic-bezier() defines an easing curve that controls how the animation accelerates and decelerates.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4638, 130, 'Which property makes an animation repeat a set number of times?', 'animation-repeat', 'animation-count', 'animation-iteration-count', 'animation-loop', 'C', 'The animation-iteration-count property sets how many times the animation runs before stopping.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4639, 130, 'Which property tilts an element by a number of degrees?', 'transform: rotate(45deg)', 'position: rotate(45deg)', 'rotate: 45deg', 'angle: 45deg', 'A', 'The transform property with the rotate function turns an element by the specified angle.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4640, 130, 'What is the purpose of the prefers-reduced-motion media query?', 'it detects users who prefer fewer animations so they can be disabled', 'it disables all CSS', 'it makes animations faster', 'it detects high-end phones', 'D', 'prefers-reduced-motion lets developers disable or tone down animations for users who opt out of motion.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4641, 130, 'Which technique reflows a component''s layout based on its own container size instead of the viewport?', 'container queries', 'media queries', 'flexbox', 'absolute positioning', 'A', 'Container queries let a component respond to the size of its own container, making it reusable in varied contexts.', 'ADVANCED', 3, 'MCQ', 1),
(4642, 130, 'Which attribute on an <img> provides a list of image sources for different screen widths?', 'srcset', 'src', 'sizes', 'media', 'B', 'The srcset attribute lists multiple images with widths so the browser picks the best one for the viewport.', 'ADVANCED', 3, 'MCQ', 1),
(4643, 130, 'Why is animating transform or opacity more performant than animating width or margin?', 'transform and opacity can be handled on the compositor without triggering layout reflow', 'width animations use less memory', 'opacity uses no CPU', 'transform is never repainted', 'C', 'Animations of transform and opacity avoid layout and paint work, so the compositor can run them on the GPU.', 'ADVANCED', 3, 'MCQ', 1),
(4644, 130, 'Which CSS function creates fluid typography that scales smoothly between a minimum and maximum size?', 'clamp()', 'calc()', 'min()', 'max()', 'D', 'clamp(MIN, VAL, MAX) clamps the value between bounds, producing text that scales with the viewport.', 'ADVANCED', 3, 'MCQ', 1),
(4645, 130, 'When implementing an accessible carousel, what should be done for users who prefer reduced motion?', 'pause or disable the auto-advancing animation when prefers-reduced-motion matches', 'force the animation to play faster', 'remove the navigation buttons', 'ignore the setting', 'A', 'Respecting prefers-reduced-motion prevents vestibular problems by stopping auto-play for users who disable motion.', 'ADVANCED', 3, 'MCQ', 1),
(4646, 130, 'What is the purpose of the will-change property in CSS?', 'it hints which properties will change so the browser can optimize rendering', 'it permanently disables layout', 'it locks the element''s position', 'it speeds up network requests', 'B', 'The will-change property warns the browser about upcoming changes so it can prepare compositing optimizations.', 'ADVANCED', 3, 'MCQ', 1),
(4647, 130, 'Why should font sizes be based on rem and fluid units rather than only fixed pixels?', 'rem and fluid units scale with user settings and viewport, improving readability and accessibility', 'px units are slower', 'pixels are not supported', 'fluid units cannot be read', 'A', 'Root-relative and fluid units respect user preferences and screen size, keeping text legible and accessible.', 'ADVANCED', 3, 'MCQ', 1),
(4648, 130, 'Which pattern keeps a header visible while scrolling but hides it entirely when scrolling down?', 'a sticky header combined with media queries that adjust its size or visibility', 'a fixed header that never moves', 'an absolute header', 'a table header', 'C', 'Combining sticky positioning with scroll-driven classes and media queries creates the common collapsing-header effect.', 'ADVANCED', 3, 'MCQ', 1),
(4649, 130, 'For art direction, where different crops of an image are needed, which element should be used?', 'the <picture> element with multiple <source> elements', 'a single <img> with one src', 'a CSS background image', 'a <video> element', 'A', 'The <picture> element lets different <source> elements supply differently cropped images for different conditions.', 'ADVANCED', 3, 'MCQ', 1),
(4650, 130, 'Which property determines whether an animation holds its final keyframe state after it finishes?', 'animation-fill-mode', 'animation-play-state', 'animation-direction', 'animation-timing', 'D', 'The animation-fill-mode property keeps the animated element at its end state when set to forwards.', 'ADVANCED', 3, 'MCQ', 1),
(4651, 131, 'Which object represents the HTML document loaded in the browser and is the entry point to the DOM?', 'window', 'document', 'navigator', 'location', 'B', 'The document object is the root of the DOM and gives access to all elements of the page.', 'BEGINNER', 1, 'MCQ', 1),
(4652, 131, 'Which method returns the first element that matches a CSS selector in the document?', 'getElementByTag', 'querySelectorAll', 'querySelector', 'getElementsByClassName', 'C', 'querySelector returns the first matching element for the given CSS selector.', 'BEGINNER', 1, 'MCQ', 1),
(4653, 131, 'Which property lets you change the text content of an element?', 'textContent', 'innerHTML', 'value', 'style', 'A', 'textContent reads and writes the text inside an element without parsing HTML markup.', 'BEGINNER', 1, 'MCQ', 1),
(4654, 131, 'Which method creates a new HTML element such as a div in the DOM?', 'createElement', 'appendChild', 'createNode', 'newElement', 'D', 'document.createElement returns a new element node that is not yet attached to the page.', 'BEGINNER', 1, 'MCQ', 1),
(4655, 131, 'What does the property nodeName return for a p element?', 'p', 'P', 'paragraph', 'element', 'B', 'nodeName returns the tag name in uppercase, so a paragraph element reports P.', 'BEGINNER', 1, 'MCQ', 1),
(4656, 131, 'Which method adds an event listener to an element?', 'addEventListener', 'onEvent', 'listen', 'attach', 'C', 'addEventListener registers a handler function to be invoked when the given event fires.', 'BEGINNER', 1, 'MCQ', 1),
(4657, 131, 'What does the DOM stand for?', 'Document Object Model', 'Data Object Management', 'Document Oriented Module', 'Dynamic Output Mechanism', 'A', 'The Document Object Model is the browser''s tree representation of the HTML document.', 'BEGINNER', 1, 'MCQ', 1),
(4658, 131, 'Which property of the event object identifies the element on which the event was fired?', 'target', 'source', 'element', 'node', 'B', 'The target property of an event points to the element that triggered the event.', 'BEGINNER', 1, 'MCQ', 1),
(4659, 131, 'Which method removes an element from the DOM?', 'remove()', 'delete()', 'hide()', 'detach()', 'C', 'Calling remove() on an element detaches it from its parent in the DOM.', 'BEGINNER', 1, 'MCQ', 1),
(4660, 131, 'How do you select an element by its unique id in plain JavaScript?', 'getElementById', 'getElementsById', 'querySelectorAll(''#id'')', 'findById', 'D', 'document.getElementById returns the single element bearing the matching id attribute.', 'BEGINNER', 1, 'MCQ', 1),
(4661, 131, 'Which property returns a live collection of all child elements of a node?', 'children', 'childNodes', 'descendants', 'childList', 'A', 'children returns only element children, unlike childNodes which also includes text and comment nodes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4662, 131, 'What is the difference between innerHTML and textContent when reading an element?', 'both return the same value', 'innerHTML returns markup while textContent returns plain text', 'textContent includes comments', 'innerHTML returns only text', 'B', 'innerHTML exposes the raw HTML markup inside the element while textContent returns only the visible text.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4663, 131, 'Which attribute method should be preferred to set the class of an element without wiping out other classes?', 'setAttribute(''class'', value)', 'className = value', 'classList.add(value)', 'style.classList', 'C', 'classList.add adds a single class while preserving existing classes on the element.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4664, 131, 'Consider a button inside a div. Clicking the button triggers the button handler then the div handler. What is this behavior called?', 'bubbling', 'capturing', 'propagation stop', 'delegation', 'A', 'In event bubbling the event travels from the target up through its ancestors after being handled.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4665, 131, 'Which event is fired when the page and all its resources have finished loading?', 'DOMContentLoaded', 'load', 'ready', 'render', 'B', 'The load event fires after the document and all external resources have fully loaded.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4666, 131, 'Given <ul id=''list''></ul>, which code appends a new <li> with the text Item?', 'const li = document.createElement(''li''); li.textContent = ''Item''; list.appendChild(li);', 'list.innerHTML = ''<li>Item</li>'';', 'list.add(''<li>Item</li>'');', 'document.append(list, ''Item'');', 'A', 'Building the element with createElement and textContent then appending it avoids repeated innerHTML parsing.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4667, 131, 'Which method stops the event from reaching handlers on parent elements?', 'stopPropagation()', 'preventDefault()', 'stopImmediatePropagation() only', 'return false', 'C', 'stopPropagation prevents the event from continuing to bubble up to ancestor elements.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4668, 131, 'What does event.preventDefault() do?', 'stops the event from bubbling', 'cancels the browser default action', 'removes the element', 'pauses event listeners', 'D', 'preventDefault cancels the browser''s default action, such as navigating when a link is clicked.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4669, 131, 'Which approach is most efficient when adding event handlers to 100 list items?', 'attach a listener to each item', 'use one listener on the parent container and inspect event.target', 'use inline onclick attributes', 'attach a window listener per item', 'A', 'Event delegation attaches a single listener to a common ancestor, reducing listener count.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4670, 131, 'After moving an element with appendChild from one parent to another, what happens to the original location?', 'the element exists in both places', 'the element is removed from the original location', 'a copy is made', 'the original location keeps a clone', 'B', 'appendChild moves an existing node, so the element appears only in the new parent location.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4671, 131, 'You build a large table by setting innerHTML repeatedly in a loop. Which is the best performance fix?', 'use createDocumentFragment and append once', 'call innerHTML more often', 'use document.write', 'increase the loop delay', 'A', 'Building nodes in a DocumentFragment and appending it once causes a single reflow instead of many.', 'ADVANCED', 3, 'MCQ', 1),
(4672, 131, 'Which technique reduces layout thrashing when reading and then writing element sizes in a loop?', 'batch reads before writes or use requestAnimationFrame', 'read and write on every iteration', 'use innerHTML instead', 'disable CSS transitions', 'B', 'Batching reads and writes minimizes forced synchronous reflows, which cause layout thrashing.', 'ADVANCED', 3, 'MCQ', 1),
(4673, 131, 'A click handler on the document must know whether a link was clicked and ignore clicks elsewhere. What is the cleanest check?', 'compare event.target with the link node using closest', 'check event.button', 'compare event.currentTarget', 'test event.keyCode', 'C', 'event.target.closest(''a'') reveals whether the click originated inside a link, including nested children.', 'ADVANCED', 3, 'MCQ', 1),
(4674, 131, 'Why is using MutationObserver preferable to polling with setInterval for detecting DOM changes?', 'it is synchronous and blocks the UI', 'it fires callbacks asynchronously only when changes occur, avoiding constant work', 'it requires no callbacks', 'it is deprecated', 'A', 'MutationObserver delivers a batch of changes asynchronously, so no work happens when the DOM is idle.', 'ADVANCED', 3, 'MCQ', 1),
(4675, 131, 'Which approach best preserves accessibility when toggling the visibility of a dialog?', 'toggle display via style plus manage aria-hidden and focus', 'set textContent to empty', 'remove the dialog node entirely', 'use opacity only', 'B', 'Managing ARIA state and focus keeps screen readers and keyboard users aware of the dialog''s visibility.', 'ADVANCED', 3, 'MCQ', 1),
(4676, 131, 'Shadow DOM is most useful for which goal?', 'encapsulating styles and markup so page CSS cannot interfere', 'increasing event bubbling', 'replacing the document root', 'making all selectors global', 'C', 'Shadow DOM scopes styles and markup to a component, preventing leaks from global styles.', 'ADVANCED', 3, 'MCQ', 1),
(4677, 131, 'While adding many classes, which call avoids unnecessary style recalculations?', 'element.classList.add(''a'', ''b'', ''c'') in one call', 'three separate classList.add calls', 'writing className repeatedly', 'adding classes with style.setProperty', 'A', 'classList accepts multiple tokens in one call, so the style is recalculated once.', 'ADVANCED', 3, 'MCQ', 1),
(4678, 131, 'A page has an input that must trigger a search request only after the user stops typing. Which technique is appropriate?', 'debounce the input event with a timeout', 'fire a request on every keystroke', 'use blur only', 'poll the value', 'B', 'Debouncing delays the handler until typing pauses, so requests are not fired on every keystroke.', 'ADVANCED', 3, 'MCQ', 1),
(4679, 131, 'Why does removing and recreating a large subtree via innerHTML often beat updating it node by node?', 'the browser can parse the HTML once and avoid many individual updates', 'innerHTML is always faster than any update', 'it preserves event listeners', 'it never causes reflows', 'C', 'Replacing the subtree parses markup once, whereas per-node updates trigger many incremental reflows.', 'ADVANCED', 3, 'MCQ', 1),
(4680, 131, 'Which toolset is recommended for debugging DOM state in modern browsers?', 'the browser DevTools Elements and Console panels', 'console.log with JSON.stringify', 'alert dialogs', 'view-source of the page', 'D', 'DevTools lets you inspect, edit and watch the live DOM, far more powerful than printing snapshots.', 'ADVANCED', 3, 'MCQ', 1),
(4681, 132, 'What is React primarily used for?', 'building user interfaces with components', 'styling web pages', 'database management', 'server configuration', 'A', 'React is a JavaScript library for composing user interfaces from reusable components.', 'BEGINNER', 1, 'MCQ', 1),
(4682, 132, 'Which command creates a new React application with create-react-app?', 'npx create-react-app my-app', 'npm init react', 'react new my-app', 'npm start my-app', 'B', 'npx create-react-app my-app scaffolds a complete React project in the my-app folder.', 'BEGINNER', 1, 'MCQ', 1),
(4683, 132, 'What file extension do React components typically use when written with JSX?', '.jsx', '.html', '.css', '.json', 'C', 'JSX components live in .jsx files, although .js files are also commonly used.', 'BEGINNER', 1, 'MCQ', 1),
(4684, 132, 'Which syntax allows JavaScript expressions inside JSX?', '{{ }}', '${ }', '{ }', '<% %>', 'D', 'Wrapping an expression in a single pair of braces evaluates it inside JSX markup.', 'BEGINNER', 1, 'MCQ', 1),
(4685, 132, 'Which function is the entry point that mounts the app into the DOM in React 18?', 'ReactDOM.createRoot(root).render(<App />)', 'React.render(<App />)', 'ReactDOM.render(<App />, root)', 'mount(<App />)', 'A', 'React 18 uses createRoot followed by render to attach the component tree to the DOM node.', 'BEGINNER', 1, 'MCQ', 1),
(4686, 132, 'What is JSX?', 'a syntax extension that looks like HTML but compiles to JavaScript', 'a new HTML version', 'a CSS framework', 'a database query language', 'B', 'JSX is a syntax extension that is transpiled into React.createElement calls.', 'BEGINNER', 1, 'MCQ', 1),
(4687, 132, 'Which keyword is used to import a component from another file?', 'import', 'require', 'include', 'use', 'C', 'ES modules use the import statement to bring in named or default exports.', 'BEGINNER', 1, 'MCQ', 1),
(4688, 132, 'In JSX, how do you write an HTML comment?', '/* comment */ in the markup', '<!-- comment -->', '// comment', 'comments are not allowed in JSX', 'D', 'HTML-style comments are not valid JSX; JavaScript comments inside braces must be used instead.', 'BEGINNER', 1, 'MCQ', 1),
(4689, 132, 'Which rule about JSX classes is correct?', 'you must use className instead of class', 'class is fine in JSX', 'use classname', 'classes are not supported', 'A', 'class is a reserved word in JavaScript, so JSX uses className for the CSS class attribute.', 'BEGINNER', 1, 'MCQ', 1),
(4690, 132, 'How is a component named Greeting rendered in JSX?', '<Greeting />', '<greeting>', '<greeting />', '<Greeting></greeting> only', 'B', 'A component is rendered with a capitalised tag, so <Greeting /> creates that component.', 'BEGINNER', 1, 'MCQ', 1),
(4691, 132, 'What does the expression 2 + 2 produce when written as {2 + 2} inside JSX?', '4', '22', '2 + 2', 'an error', 'C', 'Braces evaluate the JavaScript expression, so the rendered output is the number 4.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4692, 132, 'What does React render for a component function that returns several sibling elements without a wrapper?', 'all siblings render directly', 'it throws an error without a single parent element', 'only the first renders', 'the last sibling renders', 'D', 'A component must return a single root element, so siblings need a wrapper or fragment.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4693, 132, 'Which syntax renders the array [''a'', ''b'', ''c''] as three list items?', 'items.map(item => <li key={item}>{item}</li>)', 'items.forEach(item => <li>{item}</li>)', '<li>{items}</li>', 'items.join(''<li>'')', 'A', 'map transforms each item into a li element, and a key helps React track the items.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4694, 132, 'What is the purpose of the key prop on list items?', 'it gives each element a stable identity for efficient updates', 'it styles the item', 'it orders the list alphabetically', 'it prevents rendering', 'B', 'Keys let React match items across renders so it can update the DOM efficiently.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4695, 132, 'Why must custom components have names starting with a capital letter?', 'React treats lowercase tags as HTML elements', 'it is a performance optimisation', 'the linter requires it', 'it enables hot reload', 'C', 'Lowercase names are treated as native DOM tags, so capital letters distinguish components.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4696, 132, 'What does conditional rendering with {condition && <p>Hi</p>} show when condition is false?', 'nothing', 'false', 'null', 'an error', 'A', 'The logical AND short-circuits and renders nothing when the left operand is falsy.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4697, 132, 'Which approach correctly renders either Yes or No based on a boolean prop?', '{flag ? ''Yes'' : ''No''}', '{if (flag) ''Yes'' else ''No''}', '<div if={flag}>Yes</div>', '{flag || ''No''}', 'B', 'The ternary operator picks one of the two expressions to render based on the flag value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4698, 132, 'Which tool detects common mistakes and keeps the JSX style consistent?', 'ESLint', 'npm', 'webpack', 'Babel', 'C', 'ESLint analyses the code and flags errors and stylistic issues during development.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4699, 132, 'What does a StrictMode component do in a development build?', 'enables additional checks and warnings about unsafe practices', 'speeds up production', 'disables all hooks', 'removes console logs', 'D', 'StrictMode double-invokes functions in development to surface bugs such as impure render logic.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4700, 132, 'Which statement correctly describes what Babel does in a React project?', 'it transpiles JSX and modern JavaScript into browser-compatible code', 'it bundles CSS', 'it runs the dev server', 'it minifies images', 'A', 'Babel transforms JSX and newer JS syntax into forms supported by older browsers.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4701, 132, 'When a component renders the same output for the same props and state, what is the benefit of wrapping it in memo?', 'React skips re-rendering it when its props have not changed', 'it compiles to native code', 'it forces re-renders', 'it makes props immutable', 'B', 'memo performs a shallow prop comparison and skips the render when nothing changed.', 'ADVANCED', 3, 'MCQ', 1),
(4702, 132, 'Which pattern is the recommended way to handle a component that renders conditionally but must keep its state when toggled away?', 'keep it mounted and toggle visibility with CSS or a display flag', 'conditionally unmount it', 'reset its state', 'duplicate the component', 'A', 'Keeping the component mounted preserves its state; unmounting destroys it.', 'ADVANCED', 3, 'MCQ', 1),
(4703, 132, 'What is the danger of using an array index as a key when list items are reordered?', 'React may mismatch elements and preserve the wrong state', 'it slows rendering', 'it causes a syntax error', 'the keys become strings', 'C', 'Index keys tie identity to position, so reordering can cause React to reuse the wrong component state.', 'ADVANCED', 3, 'MCQ', 1),
(4704, 132, 'Why are pure components recommended in React?', 'a pure render makes output predictable and enables optimisations like memo', 'pure components run faster natively', 'they can use class syntax only', 'they never re-render', 'A', 'Pure functions give the same output for the same inputs, which makes rendering and optimisation reliable.', 'ADVANCED', 3, 'MCQ', 1),
(4705, 132, 'Which approach is best for rendering a large list that only part is visible?', 'use windowing or virtualisation so only visible rows render', 'render all rows at once', 'split the list into many small components', 'use innerHTML', 'B', 'Virtualisation renders only the visible rows, drastically reducing DOM nodes for huge lists.', 'ADVANCED', 3, 'MCQ', 1),
(4706, 132, 'A component must avoid re-running an expensive computation on every render even when the input has not changed. Which hook is appropriate?', 'useMemo', 'useEffect', 'useRef', 'useState', 'C', 'useMemo caches the result of the computation until its dependencies change.', 'ADVANCED', 3, 'MCQ', 1),
(4707, 132, 'Why should side effects such as network requests not run directly inside the render body?', 'rendering should be pure and side effects belong in effects or event handlers', 'side effects are forbidden by JSX', 'they always crash', 'they break the bundler', 'D', 'Putting side effects in render makes output unpredictable and causes duplicates in strict mode.', 'ADVANCED', 3, 'MCQ', 1),
(4708, 132, 'Which factor most commonly causes an unexpected re-render of many unrelated components in a large app?', 'passing new object or function references on every parent render', 'using inline styles', 'having too many files', 'using keys on every element', 'A', 'New references to props each render defeat memo comparison and cascade re-renders to children.', 'ADVANCED', 3, 'MCQ', 1),
(4709, 132, 'What is the main advantage of co-locating a component''s styles, logic and markup in one folder?', 'related code stays together, making the component self-contained and easier to maintain', 'it reduces bundle size automatically', 'it enables server-side rendering', 'it disables CSS', 'B', 'Co-location groups everything a component needs in one place, improving maintainability.', 'ADVANCED', 3, 'MCQ', 1),
(4710, 132, 'Which statement best describes reconciliation in React?', 'React diffing old and new trees to apply the minimal DOM updates', 'converting JSX to HTML', 'compressing the bundle', 'persisting state to storage', 'A', 'Reconciliation is React''s algorithm for computing the minimal set of DOM changes between renders.', 'ADVANCED', 3, 'MCQ', 1),
(4711, 133, 'What is a React component?', 'a reusable piece of UI defined as a function or class', 'a CSS class', 'an HTML file', 'a database table', 'A', 'A component is a reusable, isolated building block that renders part of the interface.', 'BEGINNER', 1, 'MCQ', 1),
(4712, 133, 'What do we call the data passed from a parent component to a child component?', 'props', 'state', 'hooks', 'stores', 'B', 'Props are the read-only values a parent passes down to a child component.', 'BEGINNER', 1, 'MCQ', 1),
(4713, 133, 'How does a function component receive its props?', 'as an argument to the function', 'from the DOM', 'through global variables', 'from the file system', 'C', 'The function receives a single props object as its first parameter.', 'BEGINNER', 1, 'MCQ', 1),
(4714, 133, 'Can a child component modify the props it receives?', 'no, props are read-only', 'yes, by reassignment', 'only inside event handlers', 'yes, with useState', 'D', 'Props are immutable, so a component must treat them as read-only input.', 'BEGINNER', 1, 'MCQ', 1),
(4715, 133, 'Which syntax destructures the name prop in a function signature?', 'function Greeting({ name })', 'function Greeting(props.name)', 'function Greeting(props => name)', 'function Greeting(): name', 'A', 'Destructuring the props object in the signature pulls name out directly.', 'BEGINNER', 1, 'MCQ', 1),
(4716, 133, 'What is the children prop used for?', 'accessing the elements nested inside a component', 'counting children elements', 'styling the component', 'naming the component', 'B', 'children holds whatever content is placed between a component''s opening and closing tags.', 'BEGINNER', 1, 'MCQ', 1),
(4717, 133, 'Which code renders the prop title inside a p element?', '<p>{title}</p>', '<p>title</p>', '<p>props.title</p>', '<p>{this.title}</p>', 'C', 'Wrapping the title variable in braces inserts its value into the JSX paragraph.', 'BEGINNER', 1, 'MCQ', 1),
(4718, 133, 'What type of value can be passed as a prop?', 'any JavaScript value, including objects and functions', 'only strings', 'only numbers', 'only elements', 'D', 'Props can carry any value, from primitives to objects, arrays and functions.', 'BEGINNER', 1, 'MCQ', 1),
(4719, 133, 'Which pattern allows a child to pass information up to a parent?', 'the parent passes a callback function that the child invokes', 'the child edits its props', 'the child uses window.postMessage', 'the child re-renders the parent', 'A', 'Parent-provided callbacks let children report events upward without mutating props.', 'BEGINNER', 1, 'MCQ', 1),
(4720, 133, 'What does propTypes help a developer check?', 'that props match expected types', 'that props are immutable', 'that components render', 'that props are styled', 'B', 'propTypes validates the type of each prop, catching mistakes during development.', 'BEGINNER', 1, 'MCQ', 1),
(4721, 133, 'What happens when a parent passes a new object literal to a child on every render?', 'the child sees a new reference each time, which can break memo comparisons', 'the object is frozen', 'nothing changes', 'the child crashes', 'A', 'A fresh object literal creates a new reference, so shallow equality checks fail each render.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4722, 133, 'Given function Welcome({ name }) { return <h1>{name}</h1>; }, what renders for <Welcome name=''Ada'' />?', 'an h1 containing Ada', 'Welcome', 'an error', 'an empty h1', 'B', 'The name prop is passed in and the component renders an h1 with its value Ada.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4723, 133, 'Which snippet forwards all props of parent to child?', '<Child {...props} />', '<Child props />', '<Child {...this} />', '<Child children={props} />', 'C', 'Spreading props with {...props} forwards every prop to the Child component.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4724, 133, 'How do you set a default value for the color prop in a function component?', 'use defaultProps or destructure with a default in the parameter list', 'set it in state', 'use a global variable', 'assign it in render', 'D', 'Destructuring defaults such as ({ color = ''blue'' }) apply when no color prop is given.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4725, 133, 'What is a controlled component?', 'an input whose value is driven by React state', 'an input without an onChange', 'a component that never re-renders', 'a component with no props', 'A', 'A controlled input gets its value from state and updates state through onChange.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4726, 133, 'Which statement about prop drilling is correct?', 'it is passing props through many intermediate components that do not need them', 'it is a React error', 'it is passing props directly to the DOM', 'it is storing props on the window', 'B', 'Prop drilling describes threading data through layers of components just to reach a deep consumer.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4727, 133, 'Given <Card><h1>Hello</h1></Card>, what does {children} render inside Card?', 'the h1 element Hello', 'an empty box', 'Card', 'an array', 'C', 'The children prop holds the h1 element passed between the tags, so it renders Hello.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4728, 133, 'Which best describes a composable component design?', 'building larger features by combining small, focused components', 'putting all logic in one file', 'using only class components', 'avoiding props entirely', 'D', 'Composition assembles small focused components into larger ones, improving reuse and clarity.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4729, 133, 'Why does changing a parent prop trigger a re-render of the child?', 'React re-renders children when their props change', 'the child changes its own props', 'the DOM forces it', 'the child subscribes to the parent', 'A', 'When the parent re-renders with new props, React re-renders the child to reflect the new values.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4730, 133, 'What does the spread operator do when passing props as {...person}?', 'passes each property of person as a separate prop', 'deep copies person', 'freezes person', 'deletes person', 'B', 'Spreading an object sends every property as an individual prop to the child.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4731, 133, 'A deeply nested component needs the same data many levels below. Which pattern best avoids prop drilling?', 'use context or a state management library', 'pass props through every level', 'store data on the DOM', 'duplicate data in each component', 'A', 'Context lets a component supply data that any descendant can consume without prop drilling.', 'ADVANCED', 3, 'MCQ', 1),
(4732, 133, 'When a memoized child always receives a new inline arrow function, what is the practical result?', 'the memo check fails each render and the child still re-renders', 'the child never re-renders', 'the function is cached automatically', 'the app crashes', 'B', 'A new function reference on every render defeats memo''s shallow comparison.', 'ADVANCED', 3, 'MCQ', 1),
(4733, 133, 'Which approach is most appropriate for passing a callback that must always see fresh state?', 'use useCallback with the right dependencies, or the functional update form', 'define the function inline', 'use a global variable', 'disable the linter', 'C', 'useCallback with correct dependencies keeps the callback stable while staying in sync with state.', 'ADVANCED', 3, 'MCQ', 1),
(4734, 133, 'Why is it a code smell for a child to reach directly into the DOM to change text written by props?', 'the child should derive its UI from props instead of mutating the DOM', 'the DOM is read-only', 'it makes the app slower', 'it only works in production', 'A', 'Direct DOM mutation bypasses React''s model, so the UI can drift out of sync with props.', 'ADVANCED', 3, 'MCQ', 1),
(4735, 133, 'Which pattern best describes a compound component such as <Select.Option>?', 'a parent component exposing sub-components that share implicit context', 'a component with many props', 'a component that uses innerHTML', 'a native HTML select', 'D', 'Compound components pair a parent with sub-components that communicate through shared context.', 'ADVANCED', 3, 'MCQ', 1),
(4736, 133, 'To reuse layout that wraps different content across pages, which component pattern is ideal?', 'a layout component that accepts children and renders them inside shared markup', 'a HOC that clones every element', 'duplicating the layout per page', 'a render-less component', 'A', 'A layout component receives children and wraps them with shared chrome such as headers and footers.', 'ADVANCED', 3, 'MCQ', 1),
(4737, 133, 'What is a high-order component (HOC)?', 'a function that takes a component and returns a new enhanced component', 'a component higher in the tree', 'a component with many hooks', 'an element that overlays the page', 'B', 'An HOC is a function that wraps a component to add props or behaviour without changing its internals.', 'ADVANCED', 3, 'MCQ', 1),
(4738, 133, 'When is the children-as-a-function (render prop) pattern valuable?', 'when a component must expose internal data so callers can decide how to render it', 'when props are strings', 'when the component has no state', 'when using class syntax', 'A', 'Render props let the parent control the markup while the component controls the data.', 'ADVANCED', 3, 'MCQ', 1),
(4739, 133, 'Why should props always be considered public API of a component?', 'changing their meaning breaks every place that uses the component', 'props are stored in the database', 'props are hard to read', 'props are automatically deleted', 'C', 'Consumers depend on the props contract, so changing semantics or names can break callers.', 'ADVANCED', 3, 'MCQ', 1),
(4740, 133, 'Which solution best shares an authenticated user object with the whole app without prop drilling?', 'an AuthProvider that supplies the user via context', 'passing user through every component', 'a global window.user', 'saving user in localStorage and reading everywhere', 'B', 'A context provider gives the user to all descendants cleanly and re-renders them when it changes.', 'ADVANCED', 3, 'MCQ', 1),
(4741, 134, 'Which hook adds local state to a function component?', 'useState', 'useEffect', 'useRef', 'useMemo', 'A', 'useState returns a state value and a setter function to update it.', 'BEGINNER', 1, 'MCQ', 1),
(4742, 134, 'What does the useState hook return?', 'an array with the current value and a function to update it', 'an object with the value only', 'the DOM node', 'a promise', 'B', 'useState returns a pair: the current state value and an updater function.', 'BEGINNER', 1, 'MCQ', 1),
(4743, 134, 'How do you update a piece of state named count that was created with const [count, setCount] = useState(0)?', 'setCount(5)', 'count = 5', 'count += 1', 'this.count = 5', 'C', 'The updater setCount(5) schedules the state change and triggers a re-render.', 'BEGINNER', 1, 'MCQ', 1),
(4744, 134, 'Which hook runs a side effect after the component renders?', 'useEffect', 'useState', 'useLayoutEffect only', 'useCallback', 'D', 'useEffect lets you run side effects such as fetching or subscribing after render.', 'BEGINNER', 1, 'MCQ', 1),
(4745, 134, 'What is the second argument of useEffect called?', 'the dependency array', 'the callback', 'the cleanup', 'the initial value', 'A', 'The dependency array controls when the effect re-runs.', 'BEGINNER', 1, 'MCQ', 1),
(4746, 134, 'What does a ref created with useRef allow a component to do?', 'hold a mutable value that does not trigger re-renders', 'change props', 'create a new component', 'persist data to a server', 'B', 'useRef gives a mutable object whose changes do not cause the component to re-render.', 'BEGINNER', 1, 'MCQ', 1),
(4747, 134, 'Which rule about hooks is correct?', 'hooks must be called at the top level, not inside loops or conditions', 'hooks can be called anywhere', 'hooks require class syntax', 'hooks only work in Node.js', 'A', 'Calling hooks unconditionally at the top level keeps their order stable across renders.', 'BEGINNER', 1, 'MCQ', 1),
(4748, 134, 'How many times does state in useState(0) change when setCount(1) is called twice in a row?', 'once, because the second call sets the same value', 'twice', 'zero times', 'three times', 'C', 'React batches the updates and bails out when the new value equals the current state.', 'BEGINNER', 1, 'MCQ', 1),
(4749, 134, 'Which hook is used to derive a cached value from state or props?', 'useMemo', 'useEffect', 'useState', 'useRef', 'D', 'useMemo recomputes its value only when the listed dependencies change.', 'BEGINNER', 1, 'MCQ', 1),
(4750, 134, 'What does the updater returned by useState return when called?', 'nothing useful; it schedules an update and triggers a re-render', 'the new state value', 'a promise', 'the old value', 'A', 'The setter schedules the update and returns undefined; the new value is applied on re-render.', 'BEGINNER', 1, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(4751, 134, 'Given const [count, setCount] = useState(0); what is the final value of count after setCount(count + 1) runs twice?', '1, because both closures see the stale count 0', '2', '0', 'an error', 'B', 'Both updaters close over the same stale count, so both schedule 0 + 1 and the result is 1.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4752, 134, 'Which snippet correctly increments a counter using a functional update?', 'setCount(c => c + 1)', 'setCount(count + 1)', 'count = count + 1', 'setCount(count += 1)', 'A', 'The functional form receives the latest state, making it safe under batching.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4753, 134, 'Why do multiple state updates in one event handler get batched into a single render?', 'React batches state updates for better performance', 'the DOM can only render once per second', 'state is immutable', 'the handler runs twice', 'B', 'React 18 batches updates automatically, so the component re-renders once with both changes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4754, 134, 'What is the purpose of the cleanup function returned by useEffect?', 'it cleans up subscriptions or timers before the effect re-runs or the component unmounts', 'it resets state', 'it cancels props', 'it deletes the component', 'C', 'The cleanup prevents memory leaks by undoing resources set up by the effect.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4755, 134, 'Given useEffect(() => {}, [deps]), when does the effect re-run?', 'only when an item in deps changes', 'after every render', 'never', 'only on mount', 'A', 'With a dependency array, the effect re-runs only when a listed dependency changes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4756, 134, 'How do you read a DOM node stored in a ref created with const myRef = useRef(null)?', 'myRef.current', 'myRef.value', 'myRef.node', 'myRef()', 'B', 'Refs expose their current value through the current property.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4757, 134, 'What is the risk of running a data fetch inside render instead of useEffect?', 'the fetch runs on every render and can loop indefinitely, causing repeated requests', 'fetch is forbidden in React', 'the data is cached forever', 'the DOM blocks requests', 'A', 'Side effects in render run repeatedly and may trigger more renders, creating an infinite loop.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4758, 134, 'Which scenario is a good fit for useRef rather than useState?', 'tracking an interval id that must not cause re-renders', 'displaying a counter', 'storing form values to render', 'showing a modal', 'C', 'Interval ids are mutable values whose changes should not trigger renders, so useRef fits.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4759, 134, 'What does the empty dependency array [] mean for useEffect?', 'the effect runs once after the first render', 'the effect never runs', 'the effect runs on every render', 'the effect runs twice per mount', 'D', 'An empty array means the effect has no dependencies, so it runs only after mount.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4760, 134, 'Why does stale state happen when a click handler reads state from a closure?', 'the handler captured the state value from the render in which it was created', 'state is stored in the DOM', 'the browser freezes state', 'props override state', 'A', 'Each render creates closures that capture that render''s state, so old handlers see old values.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4761, 134, 'Why is it incorrect to skip a dependency in useEffect even when the linter cannot tell?', 'the effect may use stale values and behave incorrectly, so dependencies must match usage', 'the effect runs slower', 'it duplicates state', 'it disables rendering', 'B', 'Missing dependencies let the effect capture stale values, producing bugs that are hard to trace.', 'ADVANCED', 3, 'MCQ', 1),
(4762, 134, 'What is the recommended way to avoid an effect that re-runs just because an inline object changes each render?', 'memoise the object with useMemo so its reference stays stable between renders', 'put the object in state', 'create the object in useEffect', 'use a global object', 'A', 'useMemo keeps the object reference stable so the effect''s dependency comparison passes.', 'ADVANCED', 3, 'MCQ', 1),
(4763, 134, 'When multiple setState calls depend on the previous state, why is the functional form essential?', 'the functional form always receives the latest queued state, avoiding lost updates', 'the direct form is faster', 'the direct form is deprecated', 'the functional form never re-renders', 'B', 'Functional updates chain correctly, so each update builds on the latest scheduled value.', 'ADVANCED', 3, 'MCQ', 1),
(4764, 134, 'A component fetches user data based on an id prop. Which code structure correctly handles the id changing?', 'a useEffect that re-fetches whenever id changes and cancels stale requests in cleanup', 'one fetch on mount only', 'fetching in render', 'a global fetch', 'A', 'Depending on id and cleaning up stale responses avoids showing data for the wrong user.', 'ADVANCED', 3, 'MCQ', 1),
(4765, 134, 'What problem does useCallback solve compared to defining functions inline?', 'it keeps the function reference stable so memoised children skip re-renders', 'it makes functions faster', 'it converts functions to strings', 'it runs functions immediately', 'B', 'useCallback memoises the function so its reference changes only when dependencies change.', 'ADVANCED', 3, 'MCQ', 1),
(4766, 134, 'Why can reading state inside useEffect and setting state directly lead to extra renders?', 'setting state triggers another render, so deriving data during render may be better', 'effects cannot set state', 'state is immutable in effects', 'the DOM blocks it', 'A', 'State set in an effect causes an additional render cycle, so it is best avoided when unnecessary.', 'ADVANCED', 3, 'MCQ', 1),
(4767, 134, 'How does React StrictMode help reveal broken effects in development?', 'it mounts components twice so missing cleanups become visible', 'it disables hooks', 'it removes re-renders', 'it caches all effects', 'C', 'Double-invoking effects surfaces effects that are not idempotent or lack proper cleanup.', 'ADVANCED', 3, 'MCQ', 1),
(4768, 134, 'A timer updates a value every second. Which effect setup prevents the timer from multiplying after re-renders?', 'create the interval once with [] deps and clear it in the cleanup', 'create a new interval on every render', 'use setInterval without cleanup', 'store the interval in state', 'D', 'With an empty dependency array the interval is created once and its cleanup clears it.', 'ADVANCED', 3, 'MCQ', 1),
(4769, 134, 'Why is storing derived values in state a common mistake?', 'it duplicates data that can drift out of sync, so derive it during render or with useMemo', 'state cannot store numbers', 'derived values are slower in state', 'state is destroyed on update', 'A', 'Storing derived data duplicates source-of-truth state and risks inconsistency, so compute it instead.', 'ADVANCED', 3, 'MCQ', 1),
(4770, 134, 'Which hook is most appropriate to run layout measurements that must complete before the browser paints?', 'useLayoutEffect', 'useEffect', 'useState', 'useRef', 'B', 'useLayoutEffect runs synchronously after DOM mutations but before paint, avoiding flicker.', 'ADVANCED', 3, 'MCQ', 1),
(4771, 135, 'What is a router in a single-page application?', 'a component that maps URLs to rendered components', 'a networking library', 'a database', 'a bundler', 'A', 'A router reads the URL and renders the component associated with that route.', 'BEGINNER', 1, 'MCQ', 1),
(4772, 135, 'Which package is the standard routing library for React?', 'react-router-dom', 'express', 'axios', 'redux', 'B', 'react-router-dom is the widely used routing library for React applications.', 'BEGINNER', 1, 'MCQ', 1),
(4773, 135, 'Which component wraps all route definitions in react-router?', '<Routes>', '<Router>', '<Route>', '<Link>', 'C', 'The Routes container holds Route definitions and matches them against the current location.', 'BEGINNER', 1, 'MCQ', 1),
(4774, 135, 'What does the <Link> component do?', 'creates a navigation link without reloading the page', 'fetches remote data', 'renders an image', 'uploads files', 'D', 'Link performs client-side navigation, updating the URL without a full page reload.', 'BEGINNER', 1, 'MCQ', 1),
(4775, 135, 'Which hook gives access to the current location object in react-router?', 'useLocation', 'useState', 'useParams', 'useNavigate', 'A', 'useLocation returns the current location, including its pathname and search.', 'BEGINNER', 1, 'MCQ', 1),
(4776, 135, 'Which hook reads dynamic segments from the URL?', 'useParams', 'useState', 'useRoute', 'useMatch', 'B', 'useParams returns the dynamic parameters captured in the matched route pattern.', 'BEGINNER', 1, 'MCQ', 1),
(4777, 135, 'What does code splitting do in a React app?', 'splits the JavaScript bundle into smaller chunks loaded on demand', 'divides CSS into files', 'separates HTML from JS', 'splits the server', 'C', 'Code splitting loads only the code needed for the current route, reducing the initial download.', 'BEGINNER', 1, 'MCQ', 1),
(4778, 135, 'Which feature of React.lazy is used together with it?', 'React.Suspense', 'React.memo', 'StrictMode', 'Fragment', 'A', 'React.lazy components are wrapped in Suspense to show a fallback while they load.', 'BEGINNER', 1, 'MCQ', 1),
(4779, 135, 'What is the virtual DOM?', 'an in-memory representation of the UI that React diffs before updating the real DOM', 'a real DOM clone in the browser', 'a headless browser', 'a template engine', 'B', 'The virtual DOM is a lightweight JavaScript tree React uses to compute minimal DOM updates.', 'BEGINNER', 1, 'MCQ', 1),
(4780, 135, 'Which button type navigates the user back one step in history with useNavigate?', 'navigate(-1)', 'back()', 'goBack', 'history.back()', 'C', 'Calling navigate(-1) moves one step back in the browser history stack.', 'BEGINNER', 1, 'MCQ', 1),
(4781, 135, 'Which Route path matches both /users and /users/123?', '/users/:id', '/users/*id', '/users+', '/users?', 'D', 'The :id parameter matches a dynamic segment, so /users/123 satisfies the path.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4782, 135, 'What is the correct way to render a 404 fallback inside <Routes>?', '<Route path=''*'' element={<NotFound />} />', '<Route path=''404'' element={<NotFound />} />', '<NotFound path=''*'' />', '<ErrorPage />', 'A', 'A route with path ''*'' catches any unmatched path and renders the fallback.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4783, 135, 'Which hook replaces the current entry in history instead of pushing a new one?', 'navigate(to, { replace: true })', 'navigate(to)', 'useLocation()', 'window.history.pushState', 'B', 'Passing { replace: true } swaps the current history entry rather than adding one.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4784, 135, 'What does React.lazy(() => import(''./Page'')) return?', 'a component that loads Page on demand', 'an HTML element', 'a promise wrapper for data', 'a context object', 'A', 'React.lazy wraps a dynamic import so the component is loaded only when first needed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4785, 135, 'What happens inside React.Suspense while a lazy component is loading?', 'the fallback prop is rendered', 'the page crashes', 'a blank screen appears', 'the browser reloads', 'B', 'Suspense renders the fallback element until the lazy component has loaded.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4786, 135, 'Why does navigating between routes with Link avoid a full page refresh?', 'the router intercepts the click and updates the history state client-side', 'the browser caches the page', 'Link uses an iframe', 'the server responds instantly', 'C', 'The router prevents the default navigation and swaps the rendered view without reloading.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4787, 135, 'Which element type is preferred for links to external sites?', 'a plain <a> tag', 'a <Link>', 'a <NavLink>', 'a <Route>', 'A', 'Plain anchors handle external URLs, while Link is intended for in-app navigation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4788, 135, 'What is the main benefit of route-based code splitting?', 'each route downloads only its own chunk, shrinking the initial bundle', 'routes are rendered faster by the server', 'CSS is removed', 'cookies are smaller', 'B', 'Route-based splitting loads a chunk only when its route is visited, cutting the initial download.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4789, 135, 'Which React tool profiles where rendering time is spent in production builds?', 'the React DevTools Profiler', 'the browser view-source', 'console.log', 'npm audit', 'C', 'The Profiler tab records renders and shows which components cost the most time.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4790, 135, 'What does the <Navigate> component do when rendered?', 'redirects the user to another route immediately', 'renders an image', 'logs the user out', 'refreshes the page', 'A', 'Rendering <Navigate to=''...'' /> performs an immediate client-side redirect.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4791, 135, 'Which pattern is best for lazy-loading a route only after authentication succeeds?', 'guard the route and conditionally render the lazy component after auth resolves', 'load all routes eagerly', 'hide the router', 'disable code splitting', 'A', 'Conditionally rendering the lazy route after auth avoids loading protected code for unauthorised users.', 'ADVANCED', 3, 'MCQ', 1),
(4792, 135, 'Why can React.lazy fail to load on refresh when code splitting is combined with server-rendered routes?', 'the chunk URL may 404 if the server does not serve hashed chunks, so a SPA fallback is needed', 'React.lazy is unstable', 'the browser disables imports', 'bundlers forbid lazy loading', 'B', 'Without a proper SPA fallback, the server may not know the new chunk filename and return 404.', 'ADVANCED', 3, 'MCQ', 1),
(4793, 135, 'What is the benefit of prefetching a lazy chunk on hover before navigation?', 'the chunk starts loading early so navigation feels instant', 'it makes the bundle smaller', 'it disables the router', 'it caches API data', 'A', 'Prefetching on hover overlaps download time with the user''s decision to navigate.', 'ADVANCED', 3, 'MCQ', 1),
(4794, 135, 'Which strategy most reduces Time to Interactive for a landing page?', 'load critical content and defer non-critical chunks and heavy libraries', 'bundle everything into one file', 'increase animation speed', 'use inline styles only', 'B', 'Deferring non-critical code shortens the main thread work required before interactivity.', 'ADVANCED', 3, 'MCQ', 1),
(4795, 135, 'Why should route transitions avoid unmounting the previous view before the new one is ready?', 'showing a fallback or shared shell prevents layout jumps and keeps the UI responsive', 'the old view must always stay', 'React forbids it', 'it wastes memory', 'A', 'Keeping a stable shell and swapping content avoids sudden blank screens during navigation.', 'ADVANCED', 3, 'MCQ', 1),
(4796, 135, 'When navigating, what is the purpose of passing a state object to navigate(''...'', { state: {...} })?', 'carrying non-serialisable or transient data to the next route without putting it in the URL', 'styling the target page', 'sizing the browser', 'hiding the URL bar', 'B', 'Location state transports extra data to the destination route without exposing it in the URL.', 'ADVANCED', 3, 'MCQ', 1),
(4797, 135, 'Which approach best prevents a query-only navigation from recreating the component?', 'treat query changes as a reason to update, not unmount, and read them via hooks', 'remount the component', 'reload the page', 'duplicate the route', 'A', 'Reading query params with hooks keeps the component mounted and updates derived data in place.', 'ADVANCED', 3, 'MCQ', 1),
(4798, 135, 'Why is splitting vendor libraries like lodash and React into separate chunks usually beneficial?', 'their hashes change rarely, so browsers can cache them across deploys', 'it increases requests', 'it disables caching', 'it removes code', 'B', 'Stable vendor chunks stay cached even when app code changes, improving repeat-load performance.', 'ADVANCED', 3, 'MCQ', 1),
(4799, 135, 'Which metric best measures whether a route becomes usable quickly after navigation?', 'time to render the route''s content and have it responsive, not just first paint', 'the number of routes', 'bundle size alone', 'the page title length', 'A', 'Usable-interaction time reflects the experience better than raw first-paint timing.', 'ADVANCED', 3, 'MCQ', 1),
(4800, 135, 'What is the recommended way to handle scroll restoration when navigating between long pages?', 'call window.scrollTo(0, 0) on route change or use router scroll-restoration support', 'do nothing and let the browser decide', 'reload the page', 'keep all content on one page', 'A', 'Explicitly resetting scroll on navigation keeps users at the top of the new page consistently.', 'ADVANCED', 3, 'MCQ', 1),
(4801, 136, 'Which runtime lets JavaScript run outside the browser on a server?', 'Node.js', 'jQuery', 'Bootstrap', 'React', 'A', 'Node.js is a JavaScript runtime built on Chrome V8 that executes JS outside the browser.', 'BEGINNER', 1, 'MCQ', 1),
(4802, 136, 'What is the command to initialize a new Node.js project with a package.json file?', 'npm install', 'npm init', 'node init', 'npm start', 'B', 'npm init walks through creating a package.json, the manifest that stores project metadata and dependencies.', 'BEGINNER', 1, 'MCQ', 1),
(4803, 136, 'Which of the following is a core Node.js module for working with files?', 'http', 'fs', 'path', 'os', 'C', 'The fs module provides filesystem operations such as reading and writing files.', 'BEGINNER', 1, 'MCQ', 1),
(4804, 136, 'What does the ''npm'' in npm install stand for?', 'Node Process Manager', 'Node Package Manager', 'Network Process Manager', 'Node Project Manager', 'D', 'npm stands for Node Package Manager and is used to install and manage packages for Node.js projects.', 'BEGINNER', 1, 'MCQ', 1),
(4805, 136, 'Which method is used to listen for an incoming HTTP request on a server created with http.createServer?', 'server.listen()', 'server.start()', 'server.run()', 'server.bind()', 'A', 'The listen() method starts the server and makes it begin accepting connections on a port.', 'BEGINNER', 1, 'MCQ', 1),
(4806, 136, 'Which event fires when a Node.js EventEmitter emits an event?', 'callback', 'listener', 'handler', 'promise', 'B', 'A listener, registered with on(), is called when the corresponding event is emitted.', 'BEGINNER', 1, 'MCQ', 1),
(4807, 136, 'What file lists the dependencies required by a Node.js project?', 'package.json', 'app.js', 'server.js', 'index.html', 'C', 'package.json lists the project dependencies, scripts, and metadata.', 'BEGINNER', 1, 'MCQ', 1),
(4808, 136, 'Which symbol does require() use to reference a module''s exported value?', 'module.exports', 'exports.default', 'return', 'this.export', 'D', 'module.exports is the CommonJS mechanism for exposing a module''s public API to consumers.', 'BEGINNER', 1, 'MCQ', 1),
(4809, 136, 'Which of the following is NOT a built-in core module in Node.js?', 'fs', 'http', 'path', 'jquery', 'A', 'jQuery is a browser-side library and is not a core Node.js module.', 'BEGINNER', 1, 'MCQ', 1),
(4810, 136, 'What does the fs.readFile() function primarily do?', 'reads a file from disk', 'deletes a file', 'renames a file', 'creates a directory', 'B', 'fs.readFile() reads the contents of a file asynchronously from the filesystem.', 'BEGINNER', 1, 'MCQ', 1),
(4811, 136, 'Consider const f = () => Promise.resolve(5); what does f() return?', '5', 'a resolved Promise wrapping 5', 'undefined', 'NaN', 'B', 'An async arrow function that returns a value wraps it in a resolved Promise, so f() yields a Promise.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4812, 136, 'What is the purpose of the ''require'' function in CommonJS modules?', 'to import another module into the current module', 'to define a new global variable', 'to parse JSON data', 'to start the event loop', 'A', 'require() loads and returns the exports of another module so its API can be used locally.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4813, 136, 'Which of the following is the correct way to export a single function from a CommonJS module?', 'module.exports = myFunction', 'exports.fn = myFunction and import via require()', 'export default myFunction', 'this.myFunction = myFunction', 'C', 'module.exports = myFunction replaces the default export with the single function so it can be required directly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4814, 136, 'What happens when an uncaught exception is thrown inside a Node.js HTTP request handler?', 'the server stays healthy and continues serving', 'the process crashes unless handled', 'the request returns 500 automatically', 'the event loop pauses', 'D', 'An uncaught exception in a Node.js process typically crashes the process, which is why try/catch and process-level handlers are needed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4815, 136, 'Which Node.js feature allows running code in a separate process to avoid blocking the main thread?', 'worker_threads', 'http.Server', 'module.exports', 'process.env', 'A', 'worker_threads spawns additional threads so CPU-heavy work does not block the main event loop.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4816, 136, 'What does process.env do in a Node.js application?', 'provides access to environment variables', 'lists all loaded modules', 'returns the current working directory', 'holds command-line arguments', 'B', 'process.env exposes the environment variables of the current process as an object.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4817, 136, 'Consider this code: setTimeout(() => console.log(''A''), 0); console.log(''B''); What order prints?', 'A then B', 'B then A', 'A and B together', 'only B prints', 'C', 'The synchronous console.log(''B'') runs first, and the timer callback A is deferred to the next tick of the event loop.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4818, 136, 'Which module would you use to build a minimal TCP server in Node.js?', 'net', 'fs', 'path', 'os', 'D', 'The net module provides APIs for creating TCP servers and clients.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4819, 136, 'Which API is used to read a file synchronously in Node.js?', 'fs.readFileSync()', 'fs.readFile()', 'fs.read()', 'fs.readAsync()', 'A', 'fs.readFileSync() performs a synchronous file read, blocking the event loop until complete.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4820, 136, 'Consider const p = new Promise((resolve) => setTimeout(() => resolve(''done''), 1000)); what does await p produce?', '''done''', 'a Promise', 'undefined', 'an error', 'D', 'await p resolves the Promise and yields its fulfilled value, which is the string ''done''.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4821, 136, 'A Node.js service is CPU-bound and its request latency is rising. Which fix most directly improves throughput?', 'spawning worker threads for the heavy computation', 'adding more console.log statements', 'switching all callbacks to promises', 'increasing the HTTP keep-alive timeout', 'A', 'Moving CPU-intensive work to worker threads frees the main event loop so it can handle more requests concurrently.', 'ADVANCED', 3, 'MCQ', 1),
(4822, 136, 'Which of these is the main benefit of using the cluster module for a Node.js web server?', 'spawning multiple processes to utilize multiple CPU cores', 'compressing HTTP responses', 'caching database queries', 'minifying JavaScript files', 'B', 'The cluster module forks worker processes so a Node app can use multiple CPU cores behind a single shared port.', 'ADVANCED', 3, 'MCQ', 1),
(4823, 136, 'A Node.js app reads a huge file to memory with fs.readFile() on every request, causing high memory use. What is the best alternative?', 'stream the file with fs.createReadStream()', 'read it with fs.readFileSync()', 'increase the heap size', 'cache the file in a global variable', 'C', 'Streaming reads the file in chunks, keeping memory usage flat instead of loading the entire file at once.', 'ADVANCED', 3, 'MCQ', 1),
(4824, 136, 'Why does blocking the event loop with a long synchronous loop hurt a Node.js server the most?', 'it prevents other connections from being processed during that time', 'it uses more RAM than async code', 'it causes the process to exit', 'it increases the server''s security risk', 'D', 'The single-threaded event loop can only process one operation at a time, so blocking it stalls every other request.', 'ADVANCED', 3, 'MCQ', 1),
(4825, 136, 'A package.json has ''type'': ''module''. How do you import a function named build from ''./util.js''?', 'import { build } from ''./util.js'';', 'const build = require(''./util.js'');', 'define build from ''./util.js'';', 'include(''./util.js'').build();', 'A', 'With ''type'': ''module'', files use ES module syntax, so named imports use the import statement.', 'ADVANCED', 3, 'MCQ', 1),
(4826, 136, 'What is the purpose of the --experimental-* flags commonly seen in Node.js releases?', 'to opt into features that are not yet stable', 'to speed up the compiler', 'to disable strict mode', 'to reduce memory usage', 'B', 'Experimental flags let developers test in-development features before they reach stable status.', 'ADVANCED', 3, 'MCQ', 1),
(4827, 136, 'You need to gracefully shut down a Node server, finish in-flight requests, and close the DB pool. Which approach is best?', 'listen to SIGTERM/SIGINT and call server.close() plus cleanup', 'call process.exit() immediately', 'throw an exception to stop the process', 'delete the server reference and wait', 'C', 'Handling shutdown signals lets the app stop accepting new connections, finish active work, and release resources cleanly.', 'ADVANCED', 3, 'MCQ', 1),
(4828, 136, 'Why does Node.js prefer asynchronous I/O over blocking I/O for web servers?', 'so the thread can run other tasks while waiting for I/O', 'because synchronous code is slower on V8', 'to avoid garbage collection', 'to guarantee requests arrive in order', 'D', 'Async I/O lets the event loop continue processing other tasks while waiting, keeping the single thread busy and the server responsive.', 'ADVANCED', 3, 'MCQ', 1),
(4829, 136, 'In a multi-instance deployment behind a load balancer, why should you avoid storing session state in the Node process memory?', 'each instance would have a separate session store, breaking sessions across requests', 'process memory is slower than a database', 'Node cannot persist memory to disk', 'memory sessions expire too quickly', 'A', 'In-memory sessions are isolated per process, so a request routed to another instance would not see the session; a shared store is required.', 'ADVANCED', 3, 'MCQ', 1),
(4830, 136, 'Which statement best describes the difference between process.nextTick and setImmediate?', 'nextTick runs before I/O callbacks while setImmediate runs after them', 'nextTick is a browser API', 'setImmediate runs synchronously', 'they are identical aliases', 'B', 'nextTick callbacks run in the current phase before I/O processing resumes, while setImmediate defers to the check phase after I/O.', 'ADVANCED', 3, 'MCQ', 1),
(4831, 137, 'Which framework is built on top of Node.js to simplify building web servers and APIs?', 'Express', 'React', 'Vue', 'Bootstrap', 'A', 'Express is a minimalist Node.js web framework used to build servers and REST APIs.', 'BEGINNER', 1, 'MCQ', 1),
(4832, 137, 'Which HTTP method is used to fetch data from a REST API?', 'GET', 'POST', 'DELETE', 'PUT', 'B', 'GET is the HTTP method designed to retrieve a resource without side effects.', 'BEGINNER', 1, 'MCQ', 1),
(4833, 137, 'Which HTTP method is typically used to create a new resource?', 'GET', 'POST', 'PUT', 'DELETE', 'C', 'POST is the convention for submitting a new resource to the server.', 'BEGINNER', 1, 'MCQ', 1),
(4834, 137, 'What does the acronym REST stand for?', 'Representational State Transfer', 'Remote Endpoint Service Transfer', 'Representational Source Transfer', 'Remote State Transfer', 'D', 'REST stands for Representational State Transfer, an architectural style for distributed systems.', 'BEGINNER', 1, 'MCQ', 1),
(4835, 137, 'Which Express function registers a route handler for GET requests to a path?', 'app.get(path, handler)', 'app.send(path, handler)', 'app.route(path, handler)', 'app.fetch(path, handler)', 'A', 'app.get() binds a callback that responds to GET requests for the given path.', 'BEGINNER', 1, 'MCQ', 1),
(4836, 137, 'Which method is used to send a JSON response in Express?', 'res.json()', 'res.sendFile()', 'res.render()', 'res.redirect()', 'B', 'res.json() serializes the given value to JSON and sends it with the JSON content type.', 'BEGINNER', 1, 'MCQ', 1),
(4837, 137, 'What status code does a successful GET request usually return?', '200 OK', '404 Not Found', '500 Internal Server Error', '302 Found', 'C', 'A 200 status indicates the request succeeded and the response body contains the resource.', 'BEGINNER', 1, 'MCQ', 1),
(4838, 137, 'Which status code means the requested resource was not found?', '404', '200', '201', '401', 'D', '404 Not Found signals that the server could not locate the requested resource.', 'BEGINNER', 1, 'MCQ', 1),
(4839, 137, 'In Express, what is the second argument passed to app.get()?', 'a route handler function', 'the port number', 'a middleware array', 'the response body', 'A', 'The second argument is the handler callback that receives req and res to produce the response.', 'BEGINNER', 1, 'MCQ', 1),
(4840, 137, 'Which HTTP method is used to update an entire existing resource?', 'PUT', 'POST', 'GET', 'OPTIONS', 'B', 'PUT replaces a resource entirely at a known URL, following REST conventions.', 'BEGINNER', 1, 'MCQ', 1),
(4841, 137, 'Consider app.post(''/users'', handler). When is this handler invoked?', 'when an HTTP POST request is made to /users', 'when any request is made to /users', 'when a GET request is made to /users', 'when a POST request is made to any path', 'A', 'The handler runs only for POST requests whose path matches /users.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4842, 137, 'Which Express object holds the URL parameters defined like app.get(''/users/:id'', ...)?', 'req.params', 'req.query', 'req.body', 'req.headers', 'C', 'Route parameters like :id are exposed on the req.params object.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4843, 137, 'How do you read a query string value like ?page=2 in Express?', 'req.query.page', 'req.params.page', 'req.body.page', 'req.url.page', 'D', 'Query string values are parsed and made available on req.query, so page is req.query.page.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4844, 137, 'Which Express method sends a 302 redirect to /home?', 'res.redirect(''/home'')', 'res.send(''/home'')', 'res.location(''/home'') and res.end()', 'res.go(''/home'')', 'A', 'res.redirect() issues a redirect response with the given location.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4845, 137, 'Consider the route app.put(''/items/:id'', handler). Which REST resource does it update?', 'the item identified by :id', 'all items', 'the item at /items', 'a query parameter named id', 'B', 'The :id segment identifies which item the PUT request should replace.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4846, 137, 'What does app.use(''/api'', router) accomplish in Express?', 'mounts a router at the /api prefix', 'creates an API endpoint named /api', 'sends a response to /api', 'defines a GET route at /api', 'C', 'app.use() mounts the router so all of its routes are available under the /api path prefix.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4847, 137, 'Which HTTP method and route best represents deleting a resource in a REST API?', 'DELETE /users/42', 'GET /users/42', 'POST /users/42/delete', 'PATCH /users/42', 'D', 'DELETE with the resource identifier is the idiomatic REST way to remove a resource.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4848, 137, 'What is the most common reason an Express API returns status 400?', 'the request is malformed or fails validation', 'the resource was not found', 'the user is unauthorized', 'the server crashed', 'A', '400 Bad Request indicates the client sent an invalid or unprocessable request.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4849, 137, 'Which Express method is used to respond with a specific HTTP status code and a body?', 'res.status(code).send(body)', 'res.body(code).status(send)', 'res.sendCode(code)', 'res.response(code)', 'D', 'res.status() sets the status code and can be chained with .send() to include a body.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4850, 137, 'Consider app.delete(''/posts/:id'', (req, res) => { ... }). What does req.params.id hold?', 'the value of the id segment from the URL', 'the request body', 'the query string', 'the HTTP header', 'A', 'req.params.id holds the value captured by the :id route parameter.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4851, 137, 'An API uses POST /orders/approve instead of POST /orders/:id/approve. Which REST design issue is most relevant?', 'the route does not clearly identify which order is being approved', 'POST cannot be used with subresources', 'approve is not a valid verb', 'the route violates HTTP 1.1 specs', 'B', 'Without the :id, the endpoint cannot express which order to approve, so the URL is ambiguous and non-idiomatic.', 'ADVANCED', 3, 'MCQ', 1),
(4852, 137, 'Why is versioning an API (for example /v1/users) recommended when multiple clients consume it?', 'so breaking changes can be introduced without breaking existing clients', 'to make routes shorter', 'to reduce HTTP request size', 'to allow the server to use more ports', 'C', 'Versioning lets the API evolve with breaking changes while old clients keep using a stable version.', 'ADVANCED', 3, 'MCQ', 1),
(4853, 137, 'A mobile client keeps sending the full user object on every PUT when only one field changed. Which method is more appropriate?', 'PATCH', 'PUT', 'POST', 'OPTIONS', 'D', 'PATCH sends only the partial change, reducing payload size and matching the intended semantics.', 'ADVANCED', 3, 'MCQ', 1),
(4854, 137, 'What is the primary benefit of using HTTP status codes correctly rather than returning 200 with an error flag?', 'clients and tooling can interpret failures programmatically', 'responses become smaller', 'the server runs faster', 'it removes the need for HTTPS', 'A', 'Proper status codes let clients, proxies, and monitoring tools detect and handle errors without parsing the body.', 'ADVANCED', 3, 'MCQ', 1),
(4855, 137, 'Which approach best prevents an API endpoint from being abused by a single client?', 'rate limiting per client/IP', 'sending all errors as 500', 'disabling caching', 'using GET for mutations', 'B', 'Rate limiting caps how many requests a client can make, protecting the service from overload.', 'ADVANCED', 3, 'MCQ', 1),
(4856, 137, 'An Express API needs to expose data to third parties. What is the most important documentation practice?', 'publishing an OpenAPI/API reference', 'adding more comments in code', 'using POST for all endpoints', 'removing the version number', 'C', 'An OpenAPI-style reference documents endpoints, parameters, and schemas so third-party developers can integrate reliably.', 'ADVANCED', 3, 'MCQ', 1),
(4857, 137, 'Why is HATEOAS considered a good practice in strictly RESTful APIs?', 'the response includes links that guide the client through the API', 'it makes responses JSON instead of XML', 'it removes the need for authentication', 'it allows the server to be stateless', 'D', 'HATEOAS embeds discoverable links in responses so clients can navigate related actions dynamically.', 'ADVANCED', 3, 'MCQ', 1),
(4858, 137, 'Your API endpoint returns sensitive data over plain HTTP in production. What is the correct fix?', 'enforce HTTPS/TLS on the server', 'obfuscate the JSON keys', 'split the data across endpoints', 'return the data as a string', 'A', 'Encrypting traffic with TLS prevents interception of sensitive data in transit.', 'ADVANCED', 3, 'MCQ', 1),
(4859, 137, 'What is the main reason REST APIs should be stateless on the server side?', 'any server instance can serve any request, enabling horizontal scaling', 'stateless APIs are always faster', 'it removes the need for a database', 'it prevents SQL injection', 'B', 'Statelessness lets any instance handle any request, making it trivial to scale out behind a load balancer.', 'ADVANCED', 3, 'MCQ', 1),
(4860, 137, 'An API accepts GET /users?fields=id,name to return only some properties. This pattern is known as:', 'field selection / sparse fields', 'pagination', 'filtering', 'sorting', 'C', 'Field selection lets clients request only the properties they need, reducing bandwidth and processing.', 'ADVANCED', 3, 'MCQ', 1),
(4861, 138, 'What is the process of verifying that a user is who they claim to be?', 'Authentication', 'Authorization', 'Encryption', 'Hashing', 'A', 'Authentication confirms a user''s identity, such as through credentials or tokens.', 'BEGINNER', 1, 'MCQ', 1),
(4862, 138, 'What is the process of determining what an authenticated user is allowed to do?', 'Authorization', 'Authentication', 'Validation', 'Serialization', 'B', 'Authorization decides which resources and actions a verified user may access.', 'BEGINNER', 1, 'MCQ', 1),
(4863, 138, 'Which token format is commonly used for stateless authentication in web APIs?', 'JWT', 'CSRF', 'SSL', 'DNS', 'C', 'JWTs (JSON Web Tokens) are compact, signed tokens widely used for stateless API authentication.', 'BEGINNER', 1, 'MCQ', 1),
(4864, 138, 'Which of the following is a password hashing library commonly used in Node.js?', 'bcrypt', 'crypto-js encryption', 'jquery', 'lodash', 'D', 'bcrypt is a popular library for safely hashing and comparing passwords.', 'BEGINNER', 1, 'MCQ', 1),
(4865, 138, 'What does the Authorization HTTP header commonly carry?', 'a credential or token proving the user is authorized', 'the user''s IP address', 'the requested resource name', 'the server''s version', 'A', 'The Authorization header carries credentials such as a Bearer token that proves identity.', 'BEGINNER', 1, 'MCQ', 1),
(4866, 138, 'Which package is most commonly used to create and verify JWTs in Node.js?', 'jsonwebtoken', 'jwt-express', 'express-session', 'passport-local', 'B', 'The jsonwebtoken package provides sign() and verify() for creating and validating JWTs.', 'BEGINNER', 1, 'MCQ', 1),
(4867, 138, 'What does the ''iat'' claim in a JWT represent?', 'issued-at timestamp', 'expiration time', 'subject', 'issuer', 'C', 'iat records when the token was issued, helping clients and servers check token age.', 'BEGINNER', 1, 'MCQ', 1),
(4868, 138, 'Which HTTP method is used to log in and obtain a session?', 'POST', 'GET', 'PUT', 'DELETE', 'D', 'POST is used to submit credentials to a login endpoint that returns a session or token.', 'BEGINNER', 1, 'MCQ', 1),
(4869, 138, 'What does OAuth 2.0 primarily provide?', 'a framework for delegated authorization', 'a password hashing scheme', 'an encryption cipher', 'a caching layer', 'A', 'OAuth 2.0 lets third-party apps obtain limited access to a user''s resources without sharing passwords.', 'BEGINNER', 1, 'MCQ', 1),
(4870, 138, 'Which mechanism stores the user''s login state on the server in a traditional web app?', 'session cookies', 'client-side JavaScript', 'localStorage', 'a query string', 'B', 'Server-side sessions keep login state on the server and track it with a cookie holding a session ID.', 'BEGINNER', 1, 'MCQ', 1),
(4871, 138, 'Consider a JWT signed with HS256. What is required to verify the signature?', 'the same secret key that was used to sign', 'the user''s password', 'the public key of the server', 'the token''s audience claim', 'A', 'HS256 is symmetric, so verification requires the exact same secret key used to sign the token.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4872, 138, 'Which part of a JWT contains the user claims like sub and roles?', 'the payload', 'the header', 'the signature', 'the footer', 'B', 'The payload is the middle segment of a JWT and holds the claims about the subject.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4873, 138, 'What is the typical purpose of the ''exp'' claim in a JWT?', 'to define when the token expires', 'to identify the token issuer', 'to store the user id', 'to mark the token as revoked', 'C', 'The exp claim sets an expiration timestamp after which the token must be rejected.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4874, 138, 'Why should JWT secret keys be stored in environment variables rather than committed to source control?', 'so the secret is not exposed to anyone who reads the repo', 'so the token can be decoded faster', 'because JWT cannot work with hardcoded strings', 'to reduce token size', 'D', 'Committing secrets in the repo leaks them to anyone with access, so they belong in secure environment configuration.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4875, 138, 'Consider a route that requires the user to be an admin. What step is this enforcing?', 'Authorization', 'Authentication', 'Hashing', 'Encryption', 'A', 'Requiring a specific role or permission is an authorization check performed after authentication.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4876, 138, 'Which strategy does Passport.js use to authenticate with a username and password?', 'LocalStrategy', 'BearerStrategy', 'JWTStrategy', 'AnonymousStrategy', 'B', 'Passport''s LocalStrategy verifies a username and password against stored credentials.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4877, 138, 'What is the safest way to store passwords in a database?', 'store a salted, slow hash like bcrypt', 'store them in plain text', 'store an MD5 hash', 'store them encrypted with a shared key', 'C', 'Salted, computationally expensive hashes like bcrypt resist brute-force and rainbow-table attacks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4878, 138, 'What happens if a JWT signature fails verification on the server?', 'the request is rejected as unauthorized', 'the payload is ignored but the request continues', 'the token is refreshed automatically', 'the server signs it again', 'D', 'A failed signature check means the token was tampered with or forged, so the request must be rejected.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4879, 138, 'Which header format is standard for sending a JWT in a REST API?', 'Authorization: Bearer <token>', 'Cookie: JWT=<token>', 'X-Token: <token>', 'Accept: <token>', 'A', 'Bearer tokens are transmitted in the Authorization header in the form Authorization: Bearer <token>.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4880, 138, 'What is the main reason to store a session ID in a cookie with the HttpOnly flag?', 'to prevent client-side JavaScript from reading the cookie', 'to make the cookie expire sooner', 'to encrypt the session data', 'to allow cross-site requests', 'B', 'HttpOnly keeps cookies inaccessible to JavaScript, reducing the risk of theft via XSS.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4881, 138, 'Your API uses JWT stored in localStorage, and an XSS vulnerability has been found. What is the safest mitigation?', 'move tokens to HttpOnly, Secure cookies', 'store tokens in a global variable', 'use a shorter secret', 'disable CORS entirely', 'A', 'HttpOnly cookies keep tokens out of JavaScript''s reach so even successful XSS cannot steal them.', 'ADVANCED', 3, 'MCQ', 1),
(4882, 138, 'A user logs out but their JWT remains valid for hours. Which token strategy best solves this?', 'maintain a server-side revocation list for tokens', 're-issue a new token on every request', 'delete the user account', 'shorter token signatures', 'C', 'A revocation list or short-lived tokens with refresh rotation lets the server invalidate tokens before expiry.', 'ADVANCED', 3, 'MCQ', 1),
(4883, 138, 'Why is it risky to trust a ''role'' claim inside a client-provided JWT without verifying its signature?', 'an attacker could forge a token and gain admin access', 'it makes tokens larger', 'it slows down verification', 'roles cannot be encoded in JSON', 'D', 'Without signature verification, a client can modify the role claim and escalate privileges.', 'ADVANCED', 3, 'MCQ', 1),
(4884, 138, 'What is the primary reason bcrypt is preferred over plain SHA-256 for passwords?', 'bcrypt is deliberately slow, resisting brute-force attacks', 'SHA-256 is reversible', 'bcrypt produces shorter hashes', 'SHA-256 is not supported on servers', 'A', 'bcrypt''s configurable cost factor makes each hash expensive, dramatically slowing password cracking.', 'ADVANCED', 3, 'MCQ', 1),
(4885, 138, 'In a microservices architecture, which approach avoids each service needing to verify JWT signatures independently against a shared secret?', 'having a central auth service issue tokens that all services validate via a shared public key', 'storing sessions in each service''s memory', 'sending passwords with every request', 'disabling authorization in most services', 'B', 'A central auth service signs tokens with a private key while services verify them with a shared public key, avoiding one shared secret everywhere.', 'ADVANCED', 3, 'MCQ', 1),
(4886, 138, 'Why should access tokens be short-lived while refresh tokens have longer lifetimes?', 'short-lived tokens limit the damage if they leak, while refresh tokens can be rotated and revoked', 'short tokens are easier to sign', 'refresh tokens are always stored in memory', 'access tokens cannot expire', 'C', 'Short access tokens minimize exposure on compromise, while refresh tokens enable rotation and revocation.', 'ADVANCED', 3, 'MCQ', 1),
(4887, 138, 'Your app sends a JWT in a URL query string. What is the security problem with this practice?', 'tokens in URLs can be leaked via logs, history, and referer headers', 'query strings are too short for JWTs', 'JWT is a binary format', 'URLs cannot contain dots', 'D', 'URLs are commonly logged and shared, so tokens in query strings risk accidental exposure.', 'ADVANCED', 3, 'MCQ', 1),
(4888, 138, 'What does the ''aud'' (audience) claim in a JWT help prevent?', 'a token issued for one service being used against another service', 'the token from expiring', 'the server from restarting', 'the payload from being decoded', 'A', 'The audience claim binds a token to a specific intended service, blocking token reuse elsewhere.', 'ADVANCED', 3, 'MCQ', 1),
(4889, 138, 'Which best practice mitigates CSRF attacks on cookie-based session authentication?', 'use CSRF tokens or SameSite=Strict cookies', 'store sessions in localStorage', 'log in via GET requests', 'disable HTTPS', 'D', 'SameSite cookies and CSRF tokens prevent malicious sites from making authenticated requests on the user''s behalf.', 'ADVANCED', 3, 'MCQ', 1),
(4890, 138, 'A single-sign-on system lets users authenticate once with an identity provider and then use many apps. Which token mechanism best supports this?', 'short-lived access tokens plus refresh tokens issued by the identity provider', 'a per-app password', 'the user''s raw password in a cookie', 'a fixed API key per browser', 'A', 'SSO providers issue access and refresh tokens so apps can authenticate users without handling passwords directly.', 'ADVANCED', 3, 'MCQ', 1),
(4891, 139, 'What is middleware in Express?', 'a function that runs between receiving a request and sending a response', 'a database connector', 'a front-end component', 'a build tool', 'A', 'Middleware functions intercept requests to perform logic before the final route handler responds.', 'BEGINNER', 1, 'MCQ', 1),
(4892, 139, 'Which Express function is used to register global middleware?', 'app.use()', 'app.listen()', 'app.route()', 'app.set()', 'B', 'app.use() mounts middleware so it runs for every matching request.', 'BEGINNER', 1, 'MCQ', 1),
(4893, 139, 'Which argument does Express middleware receive to continue to the next middleware?', 'next', 'continue', 'move', 'done', 'C', 'Calling next() hands control to the next middleware or route handler in the stack.', 'BEGINNER', 1, 'MCQ', 1),
(4894, 139, 'What are the three arguments of a standard Express middleware function?', 'req, res, next', 'req, res, end', 'request, response, done', 'url, method, handler', 'D', 'Standard middleware receives the request, response, and next callback.', 'BEGINNER', 1, 'MCQ', 1),
(4895, 139, 'Which status code class indicates a client-side error in Express?', '4xx', '2xx', '3xx', '5xx', 'A', '4xx codes mean the client sent an invalid request, such as 400 or 404.', 'BEGINNER', 1, 'MCQ', 1),
(4896, 139, 'What is the purpose of Express error-handling middleware?', 'to catch and respond to errors thrown in routes', 'to parse JSON bodies', 'to log incoming requests', 'to serve static files', 'B', 'Error-handling middleware receives errors and sends an appropriate response instead of crashing.', 'BEGINNER', 1, 'MCQ', 1),
(4897, 139, 'How is Express error-handling middleware recognized from regular middleware?', 'it has four arguments: err, req, res, next', 'it is named error()', 'it uses async/await', 'it returns a Promise', 'C', 'Express identifies error middleware by its four-parameter signature starting with err.', 'BEGINNER', 1, 'MCQ', 1),
(4898, 139, 'Which built-in Express middleware parses incoming JSON request bodies?', 'express.json()', 'express.urlencoded()', 'express.static()', 'express.cors()', 'D', 'express.json() parses JSON bodies and populates req.body.', 'BEGINNER', 1, 'MCQ', 1),
(4899, 139, 'What happens if a middleware never calls next() and never sends a response?', 'the request hangs until the client times out', 'Express returns a 500', 'the server crashes', 'the response is sent automatically', 'A', 'Without next() or a terminating response, the request stalls because no handler completes it.', 'BEGINNER', 1, 'MCQ', 1),
(4900, 139, 'Which middleware would you add to serve static files like images and CSS?', 'express.static()', 'express.json()', 'express.urlencoded()', 'express.logger()', 'B', 'express.static() serves files from a directory for direct browser access.', 'BEGINNER', 1, 'MCQ', 1),
(4901, 139, 'Consider app.use((req, res, next) => { console.log(''A''); next(); }); app.get(''/'', handler); What prints before handler runs?', 'A', 'nothing', 'the route path', 'an error', 'C', 'The middleware logs ''A'' first, then calls next() to continue to the route handler.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4902, 139, 'What does calling next(''route'') do inside a route-level middleware in Express?', 'skips to the next route that matches', 'sends a 404', 'stops all processing', 're-runs the current handler', 'D', 'next(''route'') passes control to the next matching route, skipping the remaining handlers of the current route.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4903, 139, 'Consider the middleware order: [auth, logging, cache]. Which middleware runs first for a request?', 'auth', 'logging', 'cache', 'they all run at once', 'A', 'Express executes middleware in the order they were registered, so auth runs first.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4904, 139, 'Why does the body-parsing middleware like express.json() need to be registered before routes that read req.body?', 'routes read req.body only after middleware has populated it', 'it speeds up JSON parsing', 'it validates the URL', 'it sets response headers', 'B', 'Middleware runs first, so the parser must execute before the route handler to populate req.body.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4905, 139, 'What is the purpose of a 404 handler placed at the end of an Express app?', 'to catch requests that matched no route', 'to speed up responses', 'to handle database errors', 'to enforce authentication', 'C', 'A trailing handler that returns 404 catches any request no earlier route or middleware matched.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4906, 139, 'Consider an error-handling middleware (err, req, res, next) that does not send a response and does not call next(). What occurs?', 'the request hangs and the client times out', 'Express sends a 500 automatically', 'the error is logged and ignored', 'the server restarts', 'D', 'Like any uncompleted handler, the request stalls because nothing terminates the response.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4907, 139, 'Which middleware would you add first to log the method and URL of every incoming request?', 'app.use((req, res, next) => { console.log(req.method, req.url); next(); })', 'a route handler on GET /', 'express.json()', 'a database middleware', 'A', 'A global middleware registered first logs each request before any route logic runs.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4908, 139, 'What is the main difference between application-level and router-level middleware?', 'router-level middleware only applies to routes under that router', 'application middleware runs only in production', 'router middleware cannot use next()', 'application middleware can only parse JSON', 'D', 'Router-level middleware scopes its effect to the router''s path prefix, unlike global app.use().', 'INTERMEDIATE', 2, 'MCQ', 1),
(4909, 139, 'Which of the following is the correct signature for an Express error handler?', 'function(err, req, res, next)', 'function(req, res)', 'function(err)', 'function(req, res, err, next)', 'A', 'Express recognizes error handlers by the four arguments in the exact order err, req, res, next.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4910, 139, 'Consider app.use(''/admin'', adminRouter). Which requests does this middleware affect?', 'all requests whose path starts with /admin', 'only POST /admin', 'only GET /admin', 'every request to the server', 'B', 'Mounting at ''/admin'' restricts the middleware to requests under that path prefix.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4911, 139, 'Why is it a problem to place an error-handling middleware before the routes in an Express app?', 'it never sees errors because routes run after it', 'it slows down the server', 'it cannot be async', 'it breaks JSON parsing', 'C', 'Errors are forwarded to error handlers only after routes run, so an error handler placed first never triggers.', 'ADVANCED', 3, 'MCQ', 1),
(4912, 139, 'An async route handler rejects a Promise and no error middleware exists. What happens to the request?', 'the process may crash and the client never gets a response', 'Express auto-sends a 200', 'the request is retried', 'the client receives a blank page', 'D', 'Rejected promises in async handlers are unhandled unless caught or forwarded to error middleware, which can crash the server.', 'ADVANCED', 3, 'MCQ', 1),
(4913, 139, 'What is the recommended structure of a centralized error-handling strategy in Express?', 'a single error middleware that maps error types to status codes and responses', 'hundreds of try/catch blocks in every route', 'silently swallowing errors', 'sending every error as a 500', 'A', 'Central error middleware normalizes errors, logs them, and returns consistent responses in one place.', 'ADVANCED', 3, 'MCQ', 1),
(4914, 139, 'Which of the following best describes the optimal ordering of middleware in a typical Express app?', 'body parsing, then auth, then routes, then 404, then error handler', 'routes first, then auth, then parsing', 'error handler first, then routes', 'all middleware after routes', 'C', 'Parse request data early, guard with auth, run business routes, catch unmatched with 404, and handle errors last.', 'ADVANCED', 3, 'MCQ', 1),
(4915, 139, 'A logging middleware wraps res.json() to measure response time. What must it do after recording?', 'restore or call the original method and let the response continue', 'stop the response from being sent', 'call next() twice', 'return a new status code', 'D', 'The wrapper must still produce the original behavior so the client receives the real response.', 'ADVANCED', 3, 'MCQ', 1),
(4916, 139, 'Which pattern lets a route handler share a heavy computation across all requests in Express?', 'a singleton module cached after first use', 'recomputing in every route', 'inline code duplication', 'creating a new database each request', 'A', 'A singleton module caches the result once and reuses it across requests, avoiding repeated heavy work.', 'ADVANCED', 3, 'MCQ', 1),
(4917, 139, 'Why should a request-rate-limiting middleware be registered early in the middleware chain?', 'it rejects abusive traffic before expensive handlers run', 'it makes logs prettier', 'it requires the response body', 'it replaces authentication', 'B', 'Early registration ensures excessive requests are blocked before they consume route processing resources.', 'ADVANCED', 3, 'MCQ', 1),
(4918, 139, 'In Express 4 and later, which mechanism must you use to handle errors from an async/await route handler?', 'catch the promise and call next(err)', 'ignore the rejection', 'return the error as JSON', 'restart the event loop', 'C', 'Since Express 4 does not auto-catch async rejections, you must catch them and forward via next(err).', 'ADVANCED', 3, 'MCQ', 1),
(4919, 139, 'An app returns the raw stack trace to clients on every error. Why is this a security risk?', 'it leaks internal paths and implementation details to attackers', 'it makes responses slower', 'it breaks JSON parsing', 'it exposes user passwords', 'D', 'Stack traces reveal server internals that help attackers map the application, so they should only be logged server-side.', 'ADVANCED', 3, 'MCQ', 1),
(4920, 139, 'Which middleware approach best enforces that only the API prefix uses JSON parsing?', 'mount express.json() on the /api router instead of globally', 'parse JSON in every route manually', 'disable all parsing', 'use a global catch-all parser', 'A', 'Scoping the parser to the API router keeps it from processing other paths unnecessarily.', 'ADVANCED', 3, 'MCQ', 1),
(4921, 140, 'Which practice protects passwords at rest in a database?', 'hashing with salt', 'storing plain text', 'encoding in base64', 'duplicating across tables', 'A', 'Salted hashing makes stored passwords unreadable and resistant to reverse lookup attacks.', 'BEGINNER', 1, 'MCQ', 1),
(4922, 140, 'Which HTTP header enables encrypted communication between browser and server?', 'HTTPS/TLS', 'Content-Type', 'Accept-Language', 'User-Agent', 'B', 'HTTPS uses TLS to encrypt traffic in transit between client and server.', 'BEGINNER', 1, 'MCQ', 1),
(4923, 140, 'What does CORS stand for?', 'Cross-Origin Resource Sharing', 'Common Origin Resource System', 'Cross-Origin Request Security', 'Central Origin Routing Service', 'C', 'CORS is a browser security mechanism controlling which origins may access a resource.', 'BEGINNER', 1, 'MCQ', 1),
(4924, 140, 'What is the main purpose of an SQL injection prevention technique?', 'to prevent attackers from injecting malicious SQL into queries', 'to speed up database lookups', 'to reduce disk usage', 'to encrypt the database', 'D', 'Parameterized queries and input validation stop attackers from altering SQL statements.', 'BEGINNER', 1, 'MCQ', 1),
(4925, 140, 'Which attack involves tricking a user''s browser into sending unwanted authenticated requests?', 'CSRF', 'XSS', 'DDoS', 'MITM', 'A', 'CSRF (Cross-Site Request Forgery) makes a victim''s browser perform unwanted actions on an authenticated site.', 'BEGINNER', 1, 'MCQ', 1),
(4926, 140, 'What is a Web Application Firewall (WAF) designed to do?', 'inspect and filter HTTP traffic to block web attacks', 'compile the backend source code', 'manage database backups', 'optimize CSS files', 'A', 'A WAF sits in front of a web application and filters malicious HTTP requests, blocking common attacks such as SQL injection and XSS.', 'BEGINNER', 1, 'MCQ', 1),
(4927, 140, 'Which security header prevents a browser from MIME-sniffing responses?', 'X-Content-Type-Options', 'Content-Length', 'ETag', 'Connection', 'C', 'X-Content-Type-Options: nosniff stops browsers from guessing content types.', 'BEGINNER', 1, 'MCQ', 1),
(4928, 140, 'What is the main goal of rate limiting?', 'to cap how many requests a client can make in a period', 'to increase server memory', 'to change HTTP status codes', 'to compress responses', 'D', 'Rate limiting restricts request volume, protecting services from abuse and brute force.', 'BEGINNER', 1, 'MCQ', 1),
(4929, 140, 'What does a horizontal scaling strategy add to handle more traffic?', 'more server instances', 'a faster CPU on one machine', 'more RAM on a single server', 'a larger hard drive', 'A', 'Horizontal scaling adds more instances to distribute load across machines.', 'BEGINNER', 1, 'MCQ', 1),
(4930, 140, 'Which HTTP header must be present for cross-origin requests to be allowed by CORS?', 'Access-Control-Allow-Origin', 'X-CSRF-Token', 'Referer', 'Content-Disposition', 'B', 'Access-Control-Allow-Origin tells the browser which origins are permitted to access the resource.', 'BEGINNER', 1, 'MCQ', 1),
(4931, 140, 'Which security header is specifically designed to block a page from being loaded inside an iframe?', 'X-Frame-Options', 'X-Content-Type-Options', 'Cache-Control', 'Accept-Encoding', 'A', 'X-Frame-Options prevents clickjacking by forbidding framing of the page.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4932, 140, 'Which statement best describes the difference between scaling up and scaling out?', 'scaling up adds resources to one machine while scaling out adds more machines', 'they are identical', 'scaling up adds more machines', 'scaling out upgrades the CPU', 'B', 'Vertical scaling (up) strengthens a single machine; horizontal scaling (out) adds more instances.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4933, 140, 'Consider an API query built by concatenating user input directly into SQL. What attack is most likely?', 'SQL injection', 'XSS', 'CSRF', 'session fixation', 'C', 'Concatenating unsanitized input into SQL lets attackers break out of the query and inject their own statements.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4934, 140, 'Which tool would you use in front of a Node.js service to handle load balancing?', 'nginx', 'bcrypt', 'jsonwebtoken', 'nodemon', 'D', 'nginx is a reverse proxy that can distribute requests across multiple app instances.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4935, 140, 'Which approach ensures secrets like API keys are not exposed in the front-end code?', 'keep them only on the server', 'embed them in HTML comments', 'hardcode them in a public JS file', 'put them in a data attribute', 'A', 'Anything shipped to the browser is visible to users, so secrets must live server-side only.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4936, 140, 'What does a Content Security Policy (CSP) header help prevent?', 'XSS attacks by restricting allowed scripts and resources', 'SQL injection', 'server crashes', 'slow network requests', 'B', 'CSP restricts which scripts and sources can run, blocking many injected script attacks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4937, 140, 'Which strategy helps a stateless API survive the loss of any single server?', 'running multiple instances behind a load balancer', 'storing sessions in process memory', 'using only one server', 'disabling replication', 'C', 'Multiple interchangeable instances behind a load balancer keep the service available if one fails.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4938, 140, 'Which approach best protects sensitive fields in a JWT payload?', 'do not put secrets in the payload and keep the token''s scope minimal', 'store the password in the payload', 'repeat claims many times', 'use a longer username', 'D', 'JWTs are base64-encoded, not encrypted, so sensitive data must be kept out of the payload.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4939, 140, 'What is the primary benefit of using parameterized queries over string interpolation in SQL?', 'they separate query structure from user data, preventing injection', 'they make queries faster', 'they return more rows', 'they disable indexing', 'A', 'Parameterized queries treat input as data, never as executable SQL, eliminating injection.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4940, 140, 'Which header, when set, tells browsers not to cache sensitive responses?', 'Cache-Control: no-store', 'Content-Length', 'Keep-Alive', 'Last-Modified', 'B', 'Cache-Control: no-store prevents browsers and proxies from persisting sensitive responses.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4941, 140, 'Your Node service is stateless and scaled horizontally. Which is the best session strategy?', 'store sessions in a shared store like Redis', 'store sessions in each instance''s memory', 'rely on process variables', 'disable sessions entirely', 'A', 'A shared store lets any instance read the same session, preserving state across instances.', 'ADVANCED', 3, 'MCQ', 1),
(4942, 140, 'An attacker floods the login endpoint with many requests to guess passwords. Which countermeasure is most effective?', 'rate limiting plus account lockout after failed attempts', 'increasing the bcrypt rounds', 'shortening passwords', 'logging every attempt', 'D', 'Rate limiting and lockout throttle and stop brute-force guessing at the source.', 'ADVANCED', 3, 'MCQ', 1),
(4943, 140, 'Why is it important to validate input length and format before storing user data?', 'it prevents buffer overflows, injection, and storage abuse', 'it speeds up the database', 'it makes passwords optional', 'it removes the need for HTTPS', 'A', 'Strict validation reduces attack surface and prevents malformed data from harming the system.', 'ADVANCED', 3, 'MCQ', 1),
(4944, 140, 'Which deployment practice provides the strongest defense against a single compromised server being fully controlled?', 'run each service with least-privilege and isolate workloads in containers', 'run everything as root', 'open all firewall ports', 'share one database password', 'B', 'Least-privilege accounts and container isolation limit the blast radius of a compromise to a single workload.', 'ADVANCED', 3, 'MCQ', 1),
(4945, 140, 'A sudden traffic spike comes from a few IPs. Which response best protects availability?', 'apply aggressive rate limiting and block anomalous sources', 'remove all limits', 'double server memory', 'disable HTTPS', 'C', 'Limiting anomalous sources prevents a single abusive client from exhausting the service.', 'ADVANCED', 3, 'MCQ', 1),
(4946, 140, 'Why should a production service be behind HTTPS termination at the load balancer?', 'so traffic is encrypted before it reaches the backend', 'to expose plaintext traffic', 'to speed up decryption', 'to remove authentication', 'D', 'Terminating TLS at the edge ensures all client traffic is encrypted in transit.', 'ADVANCED', 3, 'MCQ', 1),
(4947, 140, 'Which approach is the best defense-in-depth combination for a production API?', 'TLS, input validation, rate limiting, CSP, parameterized queries, and least privilege', 'only using HTTPS', 'only using a secret header', 'only adding more servers', 'A', 'Defense in depth layers independent controls so a failure in any one is covered by the others.', 'ADVANCED', 3, 'MCQ', 1),
(4948, 140, 'What is the best practice for handling dependency vulnerabilities in a Node project?', 'run npm audit regularly and update vulnerable packages', 'ignore the warnings', 'disable all dependencies', 'remove package-lock.json', 'D', 'npm audit flags known vulnerabilities, and updating packages patches them promptly.', 'ADVANCED', 3, 'MCQ', 1),
(4949, 140, 'Which statement best describes vertical scaling for a database?', 'buying a more powerful machine, which has a hard upper limit', 'adding more database replicas', 'sharding data across clusters', 'running multiple app instances', 'A', 'Vertical scaling improves one machine until a hardware ceiling, unlike horizontal options.', 'ADVANCED', 3, 'MCQ', 1),
(4950, 140, 'Why does a reverse proxy like nginx improve the security of a Node.js service?', 'it can terminate TLS, filter malicious traffic, and hide backend details', 'it removes the need for authentication', 'it makes the app code smaller', 'it replaces the database', 'B', 'A reverse proxy adds a hardened edge that handles TLS, access control, and traffic filtering.', 'ADVANCED', 3, 'MCQ', 1),
(4951, 141, 'Which of the following is a key advantage of native mobile apps over web pages?', 'direct access to device hardware such as the camera and GPS', 'no need for a backend server', 'they never need updates', 'they run in every browser', 'A', 'Native apps can use device hardware like cameras, GPS and sensors through platform APIs, which web pages cannot do directly.', 'BEGINNER', 1, 'MCQ', 1),
(4952, 141, 'What does an app store such as the Google Play Store provide?', 'a tool for writing app code', 'a marketplace to distribute and update apps', 'an emulator for testing', 'a cloud database', 'B', 'App stores host, distribute and update mobile apps so users can install them in one place.', 'BEGINNER', 1, 'MCQ', 1),
(4953, 141, 'Which type of app runs inside a browser?', 'native app', 'hybrid app', 'web app', 'compiled app', 'C', 'A web app is accessed through a browser and does not need to be installed from an app store.', 'BEGINNER', 1, 'MCQ', 1),
(4954, 141, 'Which file format is commonly used to distribute an Android app?', 'EXE', 'DWG', 'IPA', 'APK', 'D', 'The APK (Android Package) is the installable format for Android apps distributed to devices.', 'BEGINNER', 1, 'MCQ', 1),
(4955, 141, 'What does the term native app mean?', 'an app built for a specific platform using its native tools and languages', 'an app that runs only on the web', 'an app written entirely in HTML and CSS', 'an app that works without any code', 'A', 'A native app is developed with the platform''s own SDK and languages, such as Kotlin for Android or Swift for iOS.', 'BEGINNER', 1, 'MCQ', 1),
(4956, 141, 'Which operating system powers the iPhone?', 'Android', 'iOS', 'Windows', 'Linux', 'B', 'The iPhone runs on iOS, Apple''s mobile operating system.', 'BEGINNER', 1, 'MCQ', 1),
(4957, 141, 'What does an API allow an app to do?', 'make the app run faster', 'delete unnecessary files', 'communicate with other software services', 'prevent the phone from locking', 'C', 'An application programming interface lets an app request data and functionality from other software services.', 'BEGINNER', 1, 'MCQ', 1),
(4958, 141, 'What is a common reason an app needs an Internet connection?', 'to display a local database', 'to run the user interface', 'to take screenshots', 'to fetch data from a remote server', 'D', 'Many apps fetch data, such as news or user accounts, from remote servers over the Internet.', 'BEGINNER', 1, 'MCQ', 1),
(4959, 141, 'Which of the following is an example of an emulator used in mobile development?', 'Android Studio''s virtual device', 'Microsoft Word', 'Adobe Photoshop', 'Excel', 'A', 'Android Studio provides a virtual device emulator that simulates an Android phone for testing.', 'BEGINNER', 1, 'MCQ', 1),
(4960, 141, 'What is the main purpose of app notifications?', 'to increase battery life', 'to inform users of events even when the app is not open', 'to speed up the processor', 'to store photos', 'B', 'Notifications alert users to events from an app even when it is not currently open.', 'BEGINNER', 1, 'MCQ', 1),
(4961, 141, 'Which type of mobile app generally offers the best performance and hardware access?', 'a native app', 'a web app', 'an SMS-based app', 'a bookmarklet', 'A', 'Native apps compile directly for the platform and can use its full APIs, giving the best performance and hardware access.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4962, 141, 'What is a key trade-off of hybrid apps built with web technologies?', 'they cannot use the device camera', 'they may have slower performance and limited native features', 'they require a Mac to build', 'they cannot access the Internet', 'B', 'Hybrid apps rely on web rendering, which can be slower and less capable than native APIs for demanding features.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4963, 141, 'A developer must build one codebase for Android, iOS and the web. Which approach fits best?', 'write separate native code per platform', 'write an SMS gateway', 'use a cross-platform framework such as Flutter or React Native', 'install two operating systems', 'C', 'Cross-platform frameworks compile a shared codebase to multiple targets, reducing duplicated work.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4964, 141, 'Which activity best describes responsive design in a mobile context?', 'designing a fixed desktop layout', 'blocking all resizing', 'using only landscape orientation', 'adapting the layout to different screen sizes', 'D', 'Responsive design adjusts layout and content so an app looks correct across many screen sizes and orientations.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4965, 141, 'Which service is commonly used to send push notifications in a mobile app?', 'Google''s Firebase Cloud Messaging', 'a spreadsheet program', 'a file manager', 'a password manager', 'A', 'Firebase Cloud Messaging delivers push notifications to Android, iOS and web apps from a single service.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4966, 141, 'Why might an app be rejected during app store review?', 'it has too many downloads', 'it violates content or privacy guidelines', 'it uses too little storage', 'it runs on a Mac', 'B', 'App stores enforce content, privacy and quality guidelines, so violations lead to rejection.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4967, 141, 'What does versioning of a mobile app refer to?', 'the file size of the app', 'the model of the phone', 'tracking and numbering the releases of the app', 'the screen resolution', 'C', 'Version numbers identify each release so users and stores know which build of the app is installed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4968, 141, 'Which scenario best illustrates monetization through in-app purchases?', 'the app is free but offers digital items for payment', 'the developer sells the phone', 'the app only works offline', 'the app has no users', 'D', 'In-app purchases let users pay for digital goods or features inside a free app.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4969, 141, 'What is a sandbox in the context of mobile apps?', 'a restricted environment that limits what an app can access', 'a place to store backups', 'a type of screen', 'an antivirus program', 'A', 'Mobile operating systems sandbox each app so it can only access its own data and approved system resources.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4970, 141, 'Which statement about app data storage is correct?', 'apps cannot store data locally', 'apps can store data locally in databases or files on the device', 'all data must be stored in the app package', 'data disappears as soon as the app is closed', 'B', 'Mobile apps commonly persist data locally using databases, files or key-value stores on the device.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4971, 141, 'A startup must ship an app to both Android and iOS quickly with a small team. What is the most efficient strategy?', 'use a cross-platform framework to share most of the codebase', 'build two entirely separate native apps', 'write a web app and wrap it manually', 'skip the app stores', 'A', 'A cross-platform framework lets one team maintain a single shared codebase for both platforms, reducing cost and time.', 'ADVANCED', 3, 'MCQ', 1),
(4972, 141, 'An app crashes only on older devices with limited memory. What is the best first step?', 'buy new hardware', 'analyze crash reports and reduce memory usage such as image sizes', 'increase the app version number', 'remove the app from the store', 'B', 'Crash reports reveal the failing code, and reducing memory-heavy work such as oversized bitmaps fixes low-memory crashes.', 'ADVANCED', 3, 'MCQ', 1),
(4973, 141, 'Which approach best protects user data transmitted by a mobile app?', 'send passwords in plain text', 'disable encryption', 'use TLS/HTTPS for all network communication', 'store passwords in a text file', 'C', 'TLS/HTTPS encrypts traffic between the app and servers, protecting data from interception in transit.', 'ADVANCED', 3, 'MCQ', 1),
(4974, 141, 'A developer finds push notifications stop after the user clears the app from recent apps. What is the most likely cause?', 'the phone has no battery', 'the notifications are scheduled at the wrong time', 'the app icon is incorrect', 'the background service was killed and is not rescheduled properly', 'D', 'Killing a background service prevents it from delivering notifications, so the app must reschedule or rely on the push service after the process restarts.', 'ADVANCED', 3, 'MCQ', 1),
(4975, 141, 'Which strategy is best for offline-first data synchronization in a mobile app?', 'store data locally and sync with the server when connectivity is restored', 'require a constant connection', 'block all offline features', 're-download all data on every launch', 'A', 'Offline-first apps save data locally and reconcile it with the server once a connection returns, keeping the app usable offline.', 'ADVANCED', 3, 'MCQ', 1),
(4976, 141, 'What is the main purpose of app signing in production distribution?', 'to make the app run faster', 'to verify the identity of the developer and ensure the package is not tampered with', 'to reduce the app size', 'to enable encryption of photos', 'B', 'App signing cryptographically proves who published the app and lets the platform detect modified or untrusted packages.', 'ADVANCED', 3, 'MCQ', 1),
(4977, 141, 'Why should an app follow the platform''s design guidelines?', 'to make the code compile', 'to avoid using the compiler', 'to provide a consistent and familiar user experience', 'to increase battery drain', 'C', 'Following platform guidelines makes an app feel native and predictable, improving usability and user trust.', 'ADVANCED', 3, 'MCQ', 1),
(4978, 141, 'Which release channel should be used to test a new feature with a limited group before a full rollout?', 'production', 'staging with no users', 'alpha', 'a beta or staged rollout track', 'D', 'A beta or staged rollout reaches a controlled group of users so issues can be found before wide release.', 'ADVANCED', 3, 'MCQ', 1),
(4979, 141, 'A team needs to ship an update that fixes a critical bug. Which consideration matters most?', 'follow the store update process and release the fix to affected users quickly', 'rewrite the whole app', 'change the app icon', 'remove all features', 'A', 'A fast, focused fix released through the normal update channel minimizes user exposure to the bug.', 'ADVANCED', 3, 'MCQ', 1),
(4980, 141, 'How should an app handle a large image download to avoid memory problems?', 'load the full image into memory at once', 'decode and downscale the image to the needed size and cache it', 'avoid loading any images', 'store the image as a string', 'B', 'Downscaling decodes only the pixels actually needed and caching prevents repeated expensive loads, reducing peak memory.', 'ADVANCED', 3, 'MCQ', 1),
(4981, 142, 'Which language is one of the two primary languages recommended for native Android development?', 'Kotlin', 'Swift', 'Objective-C', 'PHP', 'A', 'Kotlin is Google''s recommended language for modern Android development alongside Java.', 'BEGINNER', 1, 'MCQ', 1),
(4982, 142, 'In Android, what is an Activity?', 'a background process with no interface', 'a single screen with a user interface', 'a network request', 'a database table', 'B', 'An Activity represents a single screen with which the user can interact.', 'BEGINNER', 1, 'MCQ', 1),
(4983, 142, 'Which file declares the components and permissions of an Android app?', 'build.gradle', 'colors.xml', 'AndroidManifest.xml', 'MainActivity.kt', 'C', 'AndroidManifest.xml describes app components, permissions and other metadata to the Android system.', 'BEGINNER', 1, 'MCQ', 1),
(4984, 142, 'Which IDE is officially recommended for Android development?', 'NetBeans', 'Eclipse only', 'Xcode', 'Android Studio', 'D', 'Android Studio is the official IDE for building Android apps.', 'BEGINNER', 1, 'MCQ', 1),
(4985, 142, 'What is an Android Service?', 'a component that runs in the background without a user interface', 'a screen for user input', 'a type of notification', 'a layout container', 'A', 'A Service performs long-running background work without presenting a user interface.', 'BEGINNER', 1, 'MCQ', 1),
(4986, 142, 'Where are layout files such as activity_main.xml stored?', 'res/values', 'res/layout', 'res/drawable', 'src/main/java', 'B', 'XML layout files live in the res/layout directory of an Android project.', 'BEGINNER', 1, 'MCQ', 1),
(4987, 142, 'What does an Android emulator provide?', 'a real physical phone', 'a simulated Android device for testing', 'a web browser', 'a cloud storage service', 'C', 'An emulator simulates an Android device so developers can run and test apps without real hardware.', 'BEGINNER', 1, 'MCQ', 1),
(4988, 142, 'Which of the following is NOT a core Android app component?', 'Activity', 'Service', 'ContentProvider', 'TextView', 'D', 'The core components are Activity, Service, BroadcastReceiver and ContentProvider; TextView is a UI widget.', 'BEGINNER', 1, 'MCQ', 1),
(4989, 142, 'What is an Intent used for in Android?', 'to launch another activity or component', 'to store app passwords', 'to manage battery level', 'to draw the interface', 'A', 'An Intent is a message that requests an action, such as starting an Activity or Service.', 'BEGINNER', 1, 'MCQ', 1),
(4990, 142, 'Which file stores user-readable strings so they can be localized?', 'AndroidManifest.xml', 'strings.xml', 'colors.xml', 'build.gradle', 'B', 'strings.xml holds user-facing text, which makes localization easy by replacing the file per language.', 'BEGINNER', 1, 'MCQ', 1),
(4991, 142, 'Which Android lifecycle method is called when an Activity becomes partially hidden by another activity?', 'onPause()', 'onStop()', 'onDestroy()', 'onDetach()', 'A', 'onPause() runs when an Activity loses focus but is still visible, such as when partially covered.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4992, 142, 'Which method is called first when an Activity is being created?', 'onStart()', 'onCreate()', 'onResume()', 'onRestart()', 'B', 'onCreate() is the first callback invoked when an Activity is created, where initial setup is done.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4993, 142, 'A developer wants to run a one-time network fetch when the Activity enters the foreground. Which callback is most appropriate?', 'onPause()', 'onStop()', 'onResume()', 'onRestart()', 'C', 'onResume() fires every time the Activity becomes interactive and visible in the foreground.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4994, 142, 'What is the main purpose of onSaveInstanceState()?', 'to free memory', 'to stop services', 'to launch a new activity', 'to preserve transient UI state across configuration changes', 'D', 'onSaveInstanceState() stores temporary UI state so it can be restored when the Activity is recreated.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4995, 142, 'In Kotlin, which keyword declares a variable whose value cannot be changed after assignment?', 'val', 'var', 'lateinit', 'static', 'A', 'val declares an immutable reference that can be assigned once, unlike var which is mutable.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4996, 142, 'What does the ?. safe-call operator do in Kotlin?', 'throws if null', 'calls a method only if the receiver is not null', 'converts a type', 'declares a nullable type', 'B', 'The safe-call operator ?. performs the call only when the receiver is non-null, otherwise it returns null.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4997, 142, 'A null pointer crash happens when reading a property. Which Kotlin issue most likely caused it?', 'smart cast', 'data class', 'the property was declared as a non-null type but was assigned null', 'companion object', 'C', 'Assigning null to a non-null type violates Kotlin''s type system and causes a null pointer failure at runtime.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4998, 142, 'Which view is best for displaying a long scrollable list of items?', 'TextView', 'LinearLayout', 'ScrollView with a fixed number of text views', 'RecyclerView', 'D', 'RecyclerView efficiently displays large lists by reusing views and lazy loading items.', 'INTERMEDIATE', 2, 'MCQ', 1),
(4999, 142, 'What does an explicit Intent specify in Android?', 'the exact component, such as a specific Activity class, that should receive the action', 'the current battery level', 'the model of the device', 'the app icon color', 'A', 'An explicit Intent names the precise target component, while an implicit Intent is resolved by the system from its action and data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5000, 142, 'Which component allows one app to expose structured data to other apps?', 'Activity', 'ContentProvider', 'Fragment', 'Layout', 'B', 'A ContentProvider shares structured data with other apps through a standard content URI interface.', 'INTERMEDIATE', 2, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(5001, 142, 'A user reports that an app crashes only after the screen rotates. What is the most likely cause?', 'the Activity was recreated and code relied on stale references to the old instance', 'the battery is low', 'the screen size is wrong', 'the app icon is corrupted', 'A', 'Rotation recreates the Activity, so code holding references to the destroyed instance crashes when it runs again.', 'ADVANCED', 3, 'MCQ', 1),
(5002, 142, 'Which statement best describes app signing with a release keystore?', 'the signature proves the developer''s identity and protects against tampering', 'signing speeds up the build', 'signing removes permissions', 'signing is only for testing', 'B', 'The release keystore signature authenticates the developer and lets Android reject modified packages.', 'ADVANCED', 3, 'MCQ', 1),
(5003, 142, 'What is the purpose of code shrinking and obfuscation such as R8 in a release build?', 'to make code compile faster', 'to add new features', 'to remove unused code and obscure names, making reverse engineering harder', 'to translate the app to another language', 'C', 'R8 removes dead code and renames symbols, which shrinks the APK and protects against easy reverse engineering.', 'ADVANCED', 3, 'MCQ', 1),
(5004, 142, 'Which best practice reduces memory pressure from large images in a RecyclerView?', 'decode images at the exact display size and reuse views', 'load every image at full resolution', 'keep all images in memory', 'disable images entirely', 'D', 'Decoding only the needed size and reusing item views cuts the memory each image consumes.', 'ADVANCED', 3, 'MCQ', 1),
(5005, 142, 'A developer releases an update but must keep the same package name. Why?', 'changing the package name creates a different app and breaks updates', 'package names must be lowercase', 'the store forces a new name', 'the compiler refuses uppercase names', 'A', 'The package name is the app''s identity, so changing it makes the update look like a brand new app.', 'ADVANCED', 3, 'MCQ', 1),
(5006, 142, 'Which approach best avoids dropped frames during scrolling?', 'perform heavy work such as database queries on the main thread', 'run network and heavy work off the main thread and keep the UI thread responsive', 'use many nested layouts', 'disable the scrollable view', 'B', 'Off-loading heavy work from the main thread prevents it from blocking UI updates and causing dropped frames.', 'ADVANCED', 3, 'MCQ', 1),
(5007, 142, 'What is the recommended way to persist simple user settings that must survive restarts?', 'write them into the app logs', 'store them with SharedPreferences or DataStore', 'put them in the manifest', 'recreate them on each launch', 'C', 'SharedPreferences and DataStore persist key-value settings locally across app restarts.', 'ADVANCED', 3, 'MCQ', 1),
(5008, 142, 'Which scenario is a legitimate reason to use a WorkManager periodic task?', 'to keep an Activity alive', 'to show a dialog', 'to change the app icon', 'to sync data in the background at intervals that survive process death', 'D', 'WorkManager schedules reliable, battery-friendly background work that survives app restarts and process death.', 'ADVANCED', 3, 'MCQ', 1),
(5009, 142, 'Why should a release APK be built with minification enabled?', 'it reduces APK size and removes unused code', 'it guarantees there are no crashes', 'it makes debugging easier', 'it is required for testing', 'A', 'Minification removes unused classes and resources, producing a smaller and more secure release APK.', 'ADVANCED', 3, 'MCQ', 1),
(5010, 142, 'What is the correct way to handle a dangerous runtime permission in modern Android?', 'declare it in the manifest only', 'declare it in the manifest and request it at runtime from the user', 'request it at compile time', 'never request permissions', 'B', 'Dangerous permissions must be declared in the manifest and also requested from the user at runtime.', 'ADVANCED', 3, 'MCQ', 1),
(5011, 143, 'Which language is the primary modern language for iOS development?', 'Swift', 'Kotlin', 'Java', 'Python', 'A', 'Swift is Apple''s modern, primary language for iOS, macOS and other Apple platform apps.', 'BEGINNER', 1, 'MCQ', 1),
(5012, 143, 'Which IDE is used to develop iOS apps?', 'Android Studio', 'Xcode', 'Visual Studio Code', 'Eclipse', 'B', 'Xcode is Apple''s IDE for building iOS, macOS and other Apple platform applications.', 'BEGINNER', 1, 'MCQ', 1),
(5013, 143, 'What is a ViewController in iOS?', 'a network request', 'a database', 'a component that manages a screen of content and its interactions', 'a font', 'C', 'A ViewController manages the content, layout and behavior of one screen of an app.', 'BEGINNER', 1, 'MCQ', 1),
(5014, 143, 'Which file format is used to distribute an iOS app?', 'APK', 'IPA', 'EXE', 'JAR', 'D', 'An IPA (iOS App Store Package) is the installable archive format for iOS apps.', 'BEGINNER', 1, 'MCQ', 1),
(5015, 143, 'What does the term app store refer to in iOS?', 'Apple''s official marketplace for apps', 'a cloud storage service', 'a backup tool', 'a programming language', 'A', 'The App Store is Apple''s official marketplace where users download and update iOS apps.', 'BEGINNER', 1, 'MCQ', 1),
(5016, 143, 'Which of these is a UI framework for building iOS interfaces?', 'SwiftUI', 'Jetpack Compose', 'Unity only', 'Android XML', 'B', 'SwiftUI is Apple''s modern declarative framework for building iOS user interfaces.', 'BEGINNER', 1, 'MCQ', 1),
(5017, 143, 'What is an IBOutlet used for?', 'to connect a code property to a user interface element', 'to fetch data from a server', 'to declare a function', 'to store passwords', 'C', 'An IBOutlet links a property in code to a specific UI element so the code can read and update it.', 'BEGINNER', 1, 'MCQ', 1),
(5018, 143, 'Which statement about the iOS simulator is true?', 'it can fully test device-only hardware such as the camera', 'it simulates iOS devices for testing but lacks some real hardware capabilities', 'it is a physical phone', 'it is a web server', 'D', 'The simulator runs iOS software but cannot fully emulate real hardware such as the camera or motion sensors.', 'BEGINNER', 1, 'MCQ', 1),
(5019, 143, 'What does the acronym SDK stand for?', 'Software Development Kit', 'System Data Kernel', 'Source Distribution Kit', 'Security Device Key', 'A', 'SDK stands for Software Development Kit, a set of tools and libraries for building apps.', 'BEGINNER', 1, 'MCQ', 1),
(5020, 143, 'Which Swift type stores a whole number?', 'String', 'Int', 'Bool', 'Void', 'B', 'Int is Swift''s type for whole numbers, while Double and Float store decimals.', 'BEGINNER', 1, 'MCQ', 1),
(5021, 143, 'Which Swift keyword declares a constant whose value cannot change?', 'let', 'var', 'const', 'static', 'A', 'let declares an immutable constant in Swift, while var declares a mutable variable.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5022, 143, 'Which syntax declares an optional integer in Swift?', 'var x: Int!', 'var x: Int?', 'var x: ?Int', 'var x = Int?', 'B', 'Appending ? to a type creates an optional, so var x: Int? can hold an Int or nil.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5023, 143, 'What does optional chaining do in Swift?', 'it forces an optional to unwrap', 'it converts an optional to a string', 'it safely accesses a value only when the optional is not nil', 'it removes all optionals from a program', 'C', 'Optional chaining with ?. accesses a property or method only if the optional contains a value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5024, 143, 'In Swift, what does the ?? operator do?', 'declares a nullable type', 'appends a string', 'multiplies two numbers', 'provides a default value when the left side is nil', 'D', 'The nil-coalescing operator ?? returns the left value if it is non-nil, otherwise the right-hand default.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5025, 143, 'Which is the correct way to declare a function in Swift?', 'func greet(name: String) -> String { return name }', 'function greet(name)', 'def greet(name):', 'greet(name) {}', 'A', 'Swift functions use the func keyword, labeled parameters and a -> return type.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5026, 143, 'What is a struct in Swift?', 'a network request', 'a value type that bundles related properties and methods', 'an alias for a string', 'a kind of button', 'B', 'A struct is a value type grouping related data and behavior; instances are copied on assignment.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5027, 143, 'Which SwiftUI modifier is used to add spacing around a view?', '.background()', '.foregroundColor()', '.padding()', '.cornerRadius()', 'C', 'The padding() modifier adds space around a view, giving it clear spacing from surrounding content.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5028, 143, 'What is a delegate in iOS development?', 'a design pattern where one object hands off tasks to another object', 'a type of button', 'a database table', 'a color scheme', 'D', 'Delegation lets one object act on behalf of another by sending it events, a core Cocoa pattern.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5029, 143, 'Which method reloads the data shown in a UITableView?', 'reloadData()', 'refreshView()', 'updateRows()', 'reloadAll()', 'A', 'Calling reloadData() asks the table view to fetch its data source again and redraw its rows.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5030, 143, 'Which of the following best describes an @IBAction?', 'a method that links code to a user interface event', 'a constant value', 'a data type', 'a database query', 'B', 'An @IBAction is a method wired in Interface Builder to run when the user triggers a UI event such as a tap.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5031, 143, 'An iOS app crashes with EXC_BAD_ACCESS after dismissing a view. What is the most likely cause?', 'accessing a freed or over-released object, such as a dangling reference', 'the screen is too large', 'the font is too big', 'too many strings', 'A', 'EXC_BAD_ACCESS typically means code accessed memory of an object that was already deallocated, a dangling reference.', 'ADVANCED', 3, 'MCQ', 1),
(5032, 143, 'What is the purpose of an app''s bundle identifier in iOS?', 'it is the app''s icon', 'it uniquely identifies the app and is tied to signing and provisioning', 'it sets the screen size', 'it stores user passwords', 'B', 'The bundle identifier uniquely names the app and is used in provisioning profiles and app signing.', 'ADVANCED', 3, 'MCQ', 1),
(5033, 143, 'Which statement about iOS app sandboxing is true?', 'apps can read any file on the device', 'apps are restricted to their own container and must use system APIs to share data', 'sandboxing only applies to games', 'sandboxing was removed in iOS 15', 'C', 'Each iOS app runs in a sandbox and can only access its own container, sharing data through approved APIs.', 'ADVANCED', 3, 'MCQ', 1),
(5034, 143, 'A release build crashes while the debug build works. What is the most likely difference?', 'debug builds are slower', 'release builds strip debug symbols and apply optimizations that can change behavior', 'release builds have more memory', 'release builds skip the interface', 'D', 'Release builds apply optimizations and remove debugging support, which can expose timing or lifetime bugs not seen in debug builds.', 'ADVANCED', 3, 'MCQ', 1),
(5035, 143, 'Why should sensitive data such as passwords be stored in the Keychain rather than UserDefaults?', 'the Keychain stores data encrypted and protected by the operating system', 'UserDefaults is faster', 'Keychain is easier to code', 'UserDefaults cannot store strings', 'A', 'The Keychain encrypts items and protects them at the OS level, unlike UserDefaults which stores plain data.', 'ADVANCED', 3, 'MCQ', 1),
(5036, 143, 'What is automatic reference counting (ARC) in Swift?', 'a garbage collector that runs periodically', 'a compiler feature that manages object lifetime by counting strong references', 'a network protocol', 'a UI framework', 'B', 'ARC tracks strong references to objects and releases them when the count reaches zero, managing memory automatically.', 'ADVANCED', 3, 'MCQ', 1),
(5037, 143, 'Which strategy best avoids retain cycles between Swift objects?', 'always use strong references', 'never use classes', 'use weak or unowned references where a cycle would otherwise form', 'store everything in arrays', 'C', 'Marking one side of a two-way reference as weak or unowned breaks the cycle so ARC can deallocate the objects.', 'ADVANCED', 3, 'MCQ', 1),
(5038, 143, 'How can an iOS app legally perform work while in the background?', 'run a never-ending timer', 'use background tasks such as background fetch or short scheduled work', 'play silent audio forever', 'it is impossible', 'D', 'iOS permits limited background activity through APIs such as background fetch and short background tasks for legitimate work.', 'ADVANCED', 3, 'MCQ', 1),
(5039, 143, 'Which service do developers use to upload and manage app releases for the App Store?', 'App Store Connect', 'Google Play Console', 'GitHub', 'Slack', 'A', 'App Store Connect is Apple''s portal for uploading builds, managing app metadata and submitting to review.', 'ADVANCED', 3, 'MCQ', 1),
(5040, 143, 'Why should a UITableView reuse cells with dequeueReusableCell?', 'to increase battery drain', 'to reuse existing cell objects and avoid allocating new ones during fast scrolling', 'to change colors', 'to store data', 'B', 'Reusing cells avoids creating new views constantly, which keeps scrolling smooth and reduces memory pressure.', 'ADVANCED', 3, 'MCQ', 1),
(5041, 144, 'Which language is used to write Flutter apps?', 'Dart', 'JavaScript', 'Swift', 'Kotlin', 'A', 'Flutter apps are written in Dart, a language created by Google.', 'BEGINNER', 1, 'MCQ', 1),
(5042, 144, 'What is a widget in Flutter?', 'a file type', 'a reusable building block of the user interface', 'a database', 'a network request', 'B', 'Everything in a Flutter interface is a widget, from layout containers to buttons and text.', 'BEGINNER', 1, 'MCQ', 1),
(5043, 144, 'Which of the following best describes Flutter?', 'a web server', 'a cross-platform UI framework that compiles to native code', 'an operating system', 'a database engine', 'C', 'Flutter is a cross-platform toolkit that compiles Dart into native code for Android, iOS and other targets.', 'BEGINNER', 1, 'MCQ', 1),
(5044, 144, 'Which function is required to start a Flutter app?', 'startApp()', 'launch()', 'initApp()', 'main()', 'D', 'Every Flutter app begins in main(), which calls runApp() to launch the widget tree.', 'BEGINNER', 1, 'MCQ', 1),
(5045, 144, 'What does hot reload do in Flutter?', 'it applies code changes to the running app quickly without a full restart', 'it reboots the device', 'it deletes the project', 'it downloads updates', 'A', 'Hot reload injects updated source into the running app so developers see changes almost instantly.', 'BEGINNER', 1, 'MCQ', 1),
(5046, 144, 'Which widget is commonly used to display text?', 'Text', 'Image', 'Icon', 'Button', 'B', 'The Text widget renders a string of characters on screen.', 'BEGINNER', 1, 'MCQ', 1),
(5047, 144, 'In Dart, which keyword declares a variable that can only be assigned once?', 'var', 'final', 'late', 'dynamic', 'C', 'final creates a variable assigned exactly once, whereas var declares a reassignable variable.', 'BEGINNER', 1, 'MCQ', 1),
(5048, 144, 'Which widget is commonly used to wrap a single child with padding or decoration?', 'Row', 'Column', 'ListView', 'Container', 'D', 'Container gives a child padding, margins, decoration and sizing options.', 'BEGINNER', 1, 'MCQ', 1),
(5049, 144, 'What is a StatelessWidget?', 'a widget that builds its interface once and has no mutable state', 'a widget that never appears', 'a widget for networking', 'a widget with a built-in database', 'A', 'A StatelessWidget renders fixed content and cannot change its internal state after being built.', 'BEGINNER', 1, 'MCQ', 1),
(5050, 144, 'Which widget arranges its children vertically?', 'Row', 'Column', 'Stack', 'Wrap', 'B', 'A Column places its children from top to bottom, while Row lays them out horizontally.', 'BEGINNER', 1, 'MCQ', 1),
(5051, 144, 'What does setState() do in Flutter?', 'it marks the State object as dirty and triggers a rebuild of its widget', 'it deletes the current state', 'it starts a network request', 'it stops the app', 'A', 'setState() notifies the framework that the state changed, scheduling a rebuild of the widget.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5052, 144, 'Which widget is best for a scrollable vertical list of widgets?', 'Column', 'ListView', 'Row', 'Expanded', 'B', 'ListView scrolls its children lazily, which is ideal for long vertical lists.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5053, 144, 'In Dart, what is the difference between const and final?', 'there is no difference', 'final is for numbers only', 'const values are compile-time constants while final can be set once at runtime', 'const can be reassigned', 'C', 'const must be known at compile time, whereas final is assigned once and can hold a runtime value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5054, 144, 'Which widget is best for a horizontal row of equally sized children?', 'Column with Expanded children', 'ListView', 'Row with Expanded children', 'Stack', 'D', 'A Row with each child wrapped in Expanded distributes the available width equally among them.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5055, 144, 'What does the async keyword indicate in Dart?', 'the function returns a Future and may perform asynchronous work', 'the function is private', 'the function never returns', 'the function runs on a background thread only', 'A', 'Marking a function async lets it use await and return a Future for asynchronous operations.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5056, 144, 'Which keyword is used to wait for a Future to complete in Dart?', 'async', 'await', 'then only', 'yield', 'B', 'The await keyword suspends the function until the awaited Future completes, giving its result.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5057, 144, 'What is a StatefulWidget?', 'a widget that never rebuilds', 'a widget whose State can change and trigger rebuilds', 'a widget used only for animations', 'a widget with no build method', 'C', 'A StatefulWidget owns mutable State that can be changed with setState() to trigger rebuilds.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5058, 144, 'Which class is commonly used to navigate between screens in Flutter?', 'TextButton', 'Navigator', 'Scaffold', 'Align', 'D', 'The Navigator manages a stack of routes and pushes or pops screens for navigation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5059, 144, 'What is the purpose of the Expanded widget?', 'to make a child fill the remaining space in a Row or Column', 'to add padding', 'to round corners', 'to hide a widget', 'A', 'Expanded forces its child to fill the leftover space in a flex container such as Row or Column.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5060, 144, 'Which code displays a SnackBar in Flutter?', 'call showSnackBar() on the ScaffoldMessenger', 'call toast()', 'call alert()', 'call popup()', 'B', 'ScaffoldMessenger.of(context).showSnackBar() displays a temporary SnackBar at the bottom of the screen.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5061, 144, 'A Flutter app drops frames when scrolling a large list. What is the most effective fix?', 'build items lazily with ListView.builder instead of creating all children at once', 'increase the font size', 'use a Column', 'disable scrolling', 'A', 'ListView.builder creates only visible items on demand, which keeps scrolling smooth for large lists.', 'ADVANCED', 3, 'MCQ', 1),
(5062, 144, 'What is the purpose of the pubspec.yaml file in a Flutter project?', 'to define app dependencies, assets and metadata', 'to store user data', 'to render the interface', 'to compile Dart code', 'B', 'pubspec.yaml declares packages, fonts, assets and other project settings used by the pub tool.', 'ADVANCED', 3, 'MCQ', 1),
(5063, 144, 'Which command builds an Android release APK from a Flutter project?', 'flutter run --debug', 'flutter build apk --release', 'flutter test', 'flutter pub add', 'C', 'flutter build apk --release produces an optimized, signed release APK for distribution.', 'ADVANCED', 3, 'MCQ', 1),
(5064, 144, 'What does the const keyword on a widget constructor enable?', 'runtime mutation', 'automatic rebuilding', 'compile-time constant widgets that can skip rebuild work', 'network caching', 'D', 'Const widgets are created once at compile time, so rebuilding them is almost free.', 'ADVANCED', 3, 'MCQ', 1),
(5065, 144, 'Which approach is best for managing app state across many screens in Flutter?', 'use a state management solution such as Provider or Riverpod', 'store everything in local variables', 'recreate the app each time', 'use only StatelessWidgets', 'A', 'A state management library centralizes shared state so multiple widgets can read and update it consistently.', 'ADVANCED', 3, 'MCQ', 1),
(5066, 144, 'What is the main benefit of the repository pattern in a Flutter app?', 'it makes the app prettier', 'it separates data sources from the UI, making the code testable and maintainable', 'it removes all classes', 'it speeds up hot reload', 'B', 'The repository pattern isolates data access behind one interface, simplifying testing and swapping data sources.', 'ADVANCED', 3, 'MCQ', 1),
(5067, 144, 'Which approach is recommended for periodic background work in Flutter?', 'keep the UI busy', 'run a tight loop in main()', 'use background isolates or WorkManager plugins for platform background tasks', 'never perform background work', 'C', 'Flutter apps delegate reliable periodic background work to platform APIs such as WorkManager or background isolates.', 'ADVANCED', 3, 'MCQ', 1),
(5068, 144, 'Why does Flutter compile Dart to native code for release builds?', 'it makes the code unreadable', 'to allow web development', 'to achieve native performance with ahead-of-time compilation', 'to save disk space only', 'D', 'Ahead-of-time compilation produces native machine code that runs much faster than an interpreted approach.', 'ADVANCED', 3, 'MCQ', 1),
(5069, 144, 'What commonly inflates the size of a Flutter Android app?', 'bundling many assets and not using app bundle shrinking', 'too many comments', 'short class names', 'using English strings', 'A', 'Large assets and uncompressed resources increase APK size, which shrinking and app bundles help reduce.', 'ADVANCED', 3, 'MCQ', 1),
(5070, 144, 'What is the purpose of integration tests in Flutter?', 'to check syntax', 'to test the full app flow on a real device or emulator', 'to format code', 'to upload the app', 'B', 'Integration tests run the complete app and verify user flows on a device or emulator.', 'ADVANCED', 3, 'MCQ', 1),
(5071, 145, 'What does UI stand for in mobile development?', 'User Interface', 'Universal Input', 'User Integration', 'Unit Interface', 'A', 'UI stands for User Interface, the visual elements users see and interact with.', 'BEGINNER', 1, 'MCQ', 1),
(5072, 145, 'Which unit is commonly used for text size on Android?', 'dp', 'sp', 'px', 'mm', 'B', 'Text size uses sp (scale-independent pixels), which adapts to the user''s font settings.', 'BEGINNER', 1, 'MCQ', 1),
(5073, 145, 'What is a wireframe in app design?', 'a compiled app', 'a low-fidelity sketch of the app layout', 'a database schema', 'a test report', 'C', 'A wireframe is a simple blueprint of an app''s screens and layout before visual design.', 'BEGINNER', 1, 'MCQ', 1),
(5074, 145, 'Which of the following is an example of a navigation element in a mobile app?', 'a color', 'a font', 'a tab bar', 'a padding value', 'D', 'A tab bar lets users switch between major sections of an app, so it is a navigation element.', 'BEGINNER', 1, 'MCQ', 1),
(5075, 145, 'What is a responsive design goal for mobile apps?', 'the UI adapts to different screen sizes and orientations', 'the app never changes layout', 'the app runs on one device only', 'the app ignores the screen size', 'A', 'Responsive design makes the interface scale and rearrange to fit various screens and orientations.', 'BEGINNER', 1, 'MCQ', 1),
(5076, 145, 'Which store is used to distribute Android apps?', 'App Store', 'Google Play', 'npm', 'GitHub', 'B', 'Google Play is the primary official store for distributing Android apps.', 'BEGINNER', 1, 'MCQ', 1),
(5077, 145, 'What is an app icon?', 'a database', 'a color', 'the visual symbol that represents the app on the home screen', 'a network address', 'C', 'The app icon is the image users tap to open the app and it represents the app''s identity.', 'BEGINNER', 1, 'MCQ', 1),
(5078, 145, 'What does a splash screen typically show?', 'the app''s branding while it loads', 'user passwords', 'the database contents', 'error logs', 'D', 'A splash screen displays branding such as a logo while the app prepares its content.', 'BEGINNER', 1, 'MCQ', 1),
(5079, 145, 'Which interaction lets a user scroll a list?', 'a swipe or drag gesture', 'a double tap', 'a long press', 'a pinch', 'A', 'Scrolling is performed with a swipe or drag gesture across the touch screen.', 'BEGINNER', 1, 'MCQ', 1),
(5080, 145, 'What does the release process of a mobile app involve?', 'writing a new language', 'building, testing, signing and submitting the app to a store', 'deleting the code', 'buying a phone', 'B', 'Releasing an app requires building, testing, signing and submitting it to an app store for distribution.', 'BEGINNER', 1, 'MCQ', 1),
(5081, 145, 'Which approach best handles a variety of Android screen sizes?', 'use responsive layouts with weights, constraints and dimension resources', 'fix a single pixel size for everything', 'use only one layout file', 'require a minimum screen resolution', 'A', 'Responsive layouts and resource qualifiers let the UI adapt to different screens cleanly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5082, 145, 'What is the role of a navigation drawer?', 'to show a loading bar', 'to present a slide-out menu of navigation options', 'to display notifications', 'to save settings', 'B', 'A navigation drawer is a slide-out panel that offers navigation between the main sections of an app.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5083, 145, 'Which practice improves the accessibility of a mobile app?', 'adding text labels and ensuring sufficient color contrast', 'making all text tiny', 'removing all descriptions', 'using only colors to convey meaning', 'C', 'Labels and contrast help users with visual impairments understand and use the interface.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5084, 145, 'What is A/B testing in the context of a mobile app?', 'testing on two phones at once', 'comparing two versions of a feature to measure which performs better', 'installing two apps', 'writing two test cases', 'D', 'A/B testing shows different users different versions and uses data to pick the better-performing one.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5085, 145, 'What is a beta release used for?', 'testing a near-final version with a limited audience before the full release', 'deleting old versions', 'selling the app', 'compressing files', 'A', 'A beta release gathers feedback from a limited group to catch issues before the public release.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5086, 145, 'Which tool helps track crashes in a released mobile app?', 'a text editor', 'a crash reporting service such as Crashlytics', 'a calendar app', 'a font tool', 'B', 'Crash reporting services collect stack traces from real users so developers can fix crashes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5087, 145, 'What does the term dark mode refer to?', 'an app that never opens', 'a text-only design', 'a color theme with light text on a dark background', 'a night-time-only feature', 'C', 'Dark mode uses light text and dark surfaces, which some users prefer and which can save battery on OLED screens.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5088, 145, 'Why is it important to test an app on a real device before release?', 'real devices exercise actual hardware, sensors and performance', 'real devices are free', 'emulators are banned', 'testing is optional', 'D', 'Real hardware exposes issues with sensors, performance and gestures that emulators cannot fully replicate.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5089, 145, 'Why should an app explain a permission request to the user?', 'to explain why the app needs the permission and build trust', 'to make the app slower', 'to hide features', 'to show an advertisement', 'A', 'Explaining the reason for a permission builds user trust and reduces the chance of denial.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5090, 145, 'Which metric is most useful for measuring user retention?', 'the percentage of users who return to the app after a period', 'the number of source files', 'the app icon color', 'the phone model used', 'B', 'Retention measures whether users keep returning, which indicates the app delivers ongoing value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5091, 145, 'An app works in portrait but breaks in landscape. What is the best approach?', 'provide adaptive layouts for both orientations and test configuration changes', 'lock the app to portrait permanently', 'ignore the problem', 'add more advertisements', 'A', 'Adaptive layouts and testing both orientations ensure the app works no matter how the user holds the device.', 'ADVANCED', 3, 'MCQ', 1),
(5092, 145, 'What is the purpose of a staged rollout in the Google Play Console?', 'to delete an app', 'to gradually release an update to a percentage of users and limit risk', 'to change the app name', 'to increase prices', 'B', 'A staged rollout exposes an update to a small percentage of users first, limiting the impact of problems.', 'ADVANCED', 3, 'MCQ', 1),
(5093, 145, 'Which statement about app store optimization (ASO) is correct?', 'it guarantees the top of the charts', 'it only involves the icon', 'it improves an app''s visibility through its title, keywords and screenshots', 'it is illegal', 'C', 'ASO optimizes metadata such as the title, keywords and screenshots to improve search visibility.', 'ADVANCED', 3, 'MCQ', 1),
(5094, 145, 'What is the primary risk of shipping an app that logs sensitive data to the console?', 'it slows the app', 'it increases the app size', 'it is required by stores', 'it can expose secrets or user data in logs and crash reports', 'D', 'Sensitive data in logs may end up in crash reports and analytics, leaking credentials or user information.', 'ADVANCED', 3, 'MCQ', 1),
(5095, 145, 'How should a team decide whether to ship a new feature in a released app?', 'use feature flags to roll out and measure impact incrementally', 'remove the app', 'release everything at once without testing', 'skip analytics', 'A', 'Feature flags let a team enable a feature for a subset of users, measure it and roll back if needed.', 'ADVANCED', 3, 'MCQ', 1),
(5096, 145, 'What is the recommended way to handle app icons across devices?', 'one fixed size for all devices', 'provide multiple densities using adaptive icons on Android and asset catalogs on iOS', 'use one tiny image', 'icons are not needed', 'B', 'Adaptive icons and asset catalogs supply correctly scaled versions of the icon for each screen density.', 'ADVANCED', 3, 'MCQ', 1),
(5097, 145, 'Why should a UI be tested on devices with small screens?', 'it improves battery life', 'it is optional', 'small screens are still widely used and often expose layout overflow issues', 'it reduces the code size', 'C', 'Testing small screens catches layout overflow and usability problems that affect a large share of users.', 'ADVANCED', 3, 'MCQ', 1),
(5098, 145, 'What is the purpose of a privacy policy for a store-submitted mobile app?', 'it is only for lawyers', 'it lets the app read the clipboard', 'it discloses how user data is collected and used, and is often required by app stores', 'it replaces the app icon', 'D', 'A privacy policy explains data collection and usage, and stores often require one before approval.', 'ADVANCED', 3, 'MCQ', 1),
(5099, 145, 'What does the minSdkVersion setting control in an Android build?', 'the lowest Android version the app supports', 'the highest Android version', 'the app size', 'the font scale', 'A', 'minSdkVersion sets the oldest Android version on which the app is allowed to install and run.', 'ADVANCED', 3, 'MCQ', 1),
(5100, 145, 'Which release practice best catches device-specific issues before a wide launch?', 'skip the beta program', 'run a staged beta program across diverse devices and respond to feedback', 'release only to one phone model', 'never test', 'B', 'A diverse beta program surfaces device-specific bugs on many models and OS versions before the full launch.', 'ADVANCED', 3, 'MCQ', 1),
(5101, 146, 'What does the acronym HTTP stand for?', 'Hypertext Transfer Protocol', 'Hypertext Terminal Processing', 'High Transfer Text Protocol', 'Hyperlink Transport Protocol', 'A', 'HTTP stands for Hypertext Transfer Protocol, the foundation protocol used to request and transfer web resources.', 'BEGINNER', 1, 'MCQ', 1),
(5102, 146, 'Which HTTP method is used to retrieve a resource from a server?', 'POST', 'GET', 'PUT', 'DELETE', 'B', 'GET is a safe, read-only method designed to fetch a resource without changing server state.', 'BEGINNER', 1, 'MCQ', 1),
(5103, 146, 'Which HTTP method is commonly used to submit form data that creates a new resource?', 'GET', 'HEAD', 'POST', 'TRACE', 'C', 'POST sends data in the request body and is the standard method for creating or submitting new resources.', 'BEGINNER', 1, 'MCQ', 1),
(5104, 146, 'What does the status code 404 indicate?', 'The request succeeded', 'The server had an internal error', 'The resource was not found', 'The client is unauthorized', 'C', 'Status code 404 Not Found means the server could not locate the requested resource.', 'BEGINNER', 1, 'MCQ', 1),
(5105, 146, 'Which status code range represents successful responses?', '100-199', '200-299', '300-399', '400-499', 'B', 'The 2xx range, starting at 200 OK, signals that the request was received and processed successfully.', 'BEGINNER', 1, 'MCQ', 1),
(5106, 146, 'Which HTTP method is typically used to update an existing resource?', 'GET', 'DELETE', 'PUT', 'POST', 'C', 'PUT is intended to replace or update a resource at a known URI with the payload provided.', 'BEGINNER', 1, 'MCQ', 1),
(5107, 146, 'What does the ''REST'' in REST API stand for?', 'Representational State Transfer', 'Remote Event System Transfer', 'Resource Entity State Testing', 'Representative Server Technology', 'A', 'REST stands for Representational State Transfer, an architectural style for designing networked APIs.', 'BEGINNER', 1, 'MCQ', 1),
(5108, 146, 'Which HTTP method removes a resource from the server?', 'POST', 'PUT', 'PATCH', 'DELETE', 'D', 'DELETE is the HTTP method designed to remove the resource identified by the request URI.', 'BEGINNER', 1, 'MCQ', 1),
(5109, 146, 'What is a URL?', 'A type of server software', 'A unique address used to locate a resource on the web', 'A programming language', 'A database format', 'B', 'A URL (Uniform Resource Locator) uniquely identifies and addresses a web resource.', 'BEGINNER', 1, 'MCQ', 1),
(5110, 146, 'Which HTTP header is commonly used to send authentication credentials?', 'Accept', 'Content-Type', 'Authorization', 'Cache-Control', 'C', 'The Authorization header carries credentials such as tokens or basic auth data for a request.', 'BEGINNER', 1, 'MCQ', 1),
(5111, 146, 'A client calls GET /users/42 and receives a JSON object. What best describes this design?', 'State-changing RPC', 'A RESTful read operation that returns a representation', 'A file download', 'A session handshake', 'B', 'GET on a specific resource URI is a read-only REST operation returning that resource''s representation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5112, 146, 'Which HTTP method should be used to partially update an existing resource?', 'PATCH', 'PUT', 'POST', 'DELETE', 'A', 'PATCH applies a partial modification, unlike PUT which replaces the whole resource.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5113, 146, 'What does the 201 status code specifically signal?', 'The resource was moved', 'The resource was created', 'The request is invalid', 'The server is too busy', 'B', '201 Created indicates the request succeeded and a new resource was created as a result.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5114, 146, 'An API returns 401 to a request with no token. What is the problem?', 'The resource does not exist', 'The client is not authenticated', 'The server crashed', 'The request timed out', 'B', '401 Unauthorized means the request lacks valid authentication credentials.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5115, 146, 'Which status code indicates the client was authenticated but lacks permission?', '401', '403', '404', '410', 'C', '403 Forbidden means the server understood the request but refuses to authorize it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5116, 146, 'A mobile app polls for updates every second. Which HTTP response header should it respect?', 'Cache-Control', 'Set-Cookie', 'Content-Language', 'Server', 'A', 'Cache-Control instructs the client how long a response may be cached, reducing unnecessary requests.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5117, 146, 'What does it mean when an HTTP response includes the header Location: /orders/7?', 'The response body is a redirect target', 'The client should request /orders/7 to find the created resource', 'The server moved permanently', 'The request is forbidden', 'B', 'The Location header indicates where a newly created resource can be found, commonly used with 201 Created.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5118, 146, 'Which status code is returned when a request method is not allowed on a URI?', '405', '400', '500', '302', 'A', '405 Method Not Allowed is returned when the resource exists but does not support the requested method.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5119, 146, 'What is the primary purpose of the HTTP HEAD method?', 'To delete a resource', 'To retrieve headers only, without the body', 'To upload a file', 'To establish a secure connection', 'B', 'HEAD behaves like GET but returns only the response headers, which is useful for checking existence or metadata.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5120, 146, 'In REST, what is an idempotent method?', 'A method that always returns an error', 'A method whose repeated identical calls have the same effect as a single call', 'A method that requires authentication', 'A method that changes state on every call', 'B', 'Idempotent methods such as GET, PUT and DELETE produce the same server state no matter how many times they are repeated.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5121, 146, 'An API allows DELETE /users/7 to be retried safely without side effects. Which property does this demonstrate?', 'Idempotency', 'Latency', 'Caching', 'Session state', 'A', 'Repeating an idempotent DELETE leaves the server in the same state, making retries safe after timeouts.', 'ADVANCED', 3, 'MCQ', 1),
(5122, 146, 'Which of these best follows RESTful resource naming conventions?', '/getAllUsers', '/users/7/orders', '/updateUser?id=7', '/createOrder', 'B', 'RESTful design uses noun-based hierarchical URIs such as /users/7/orders to represent related resources.', 'ADVANCED', 3, 'MCQ', 1),
(5123, 146, 'A developer returns HTTP 200 with an error object in the body when validation fails. Why is this a poor design?', 'It is faster than 400', 'It hides the failure from clients and monitoring tools that rely on status codes', 'It makes the server stateful', 'It prevents caching entirely', 'B', 'Using 200 for failures defeats status-code signalling, making errors harder to detect and handle programmatically.', 'ADVANCED', 3, 'MCQ', 1),
(5124, 146, 'Which HTTP mechanism allows a client to retry a failed request and avoid creating duplicate orders?', 'Idempotency keys sent in headers', 'Changing GET to POST', 'Increasing the timeout', 'Disabling compression', 'A', 'An idempotency key lets the server recognize and deduplicate repeated POST attempts for the same logical operation.', 'ADVANCED', 3, 'MCQ', 1),
(5125, 146, 'What does the 429 status code indicate and what header should the server send with it?', 'A server crash, Retry-After', 'Rate limiting exceeded, Retry-After', 'Resource not found, Cache-Control', 'Bad request, Location', 'B', '429 Too Many Requests signals rate limiting and Retry-After tells the client when it may try again.', 'ADVANCED', 3, 'MCQ', 1),
(5126, 146, 'What is the difference between PUT and PATCH?', 'PUT is always unsafe and PATCH is safe', 'PUT replaces the entire resource while PATCH applies a partial update', 'PATCH replaces the entire resource while PUT applies a partial update', 'They are identical in every framework', 'B', 'PUT sends a complete replacement representation while PATCH sends only the fields to be changed.', 'ADVANCED', 3, 'MCQ', 1),
(5127, 146, 'Which strategy best improves the performance of a chat API that clients poll every 5 seconds?', 'Returning 404 for empty polls', 'Using long polling, SSE, or WebSockets instead of frequent polling', 'Making GET requests idempotent', 'Adding more query parameters', 'B', 'Long polling or push technologies avoid wasteful repeated requests by delivering updates as they occur.', 'ADVANCED', 3, 'MCQ', 1),
(5128, 146, 'Which HTTP cache-control directive prevents any intermediate cache from storing a response?', 'no-store', 'no-transform', 'max-age=0', 'must-revalidate', 'A', 'no-store tells caches not to persist the response at all, which is essential for sensitive data.', 'ADVANCED', 3, 'MCQ', 1),
(5129, 146, 'When designing versioned REST APIs, which approach is generally recommended?', 'Changing resource semantics in place', 'Adding the version in the URI such as /v1/users', 'Returning a random error', 'Deleting old endpoints immediately', 'B', 'URI versioning such as /v1/users lets older clients keep working while new versions are introduced.', 'ADVANCED', 3, 'MCQ', 1),
(5130, 146, 'An API exposes /orders and /orders/{id}. Which HTTP method pairs are the most RESTful for list and detail views?', 'GET on both, plus POST and PUT', 'POST for list and DELETE for detail', 'HEAD only', 'Any method works equally', 'A', 'GET lists resources, POST creates, and GET with an id retrieves or PUT/PATCH updates a single resource.', 'ADVANCED', 3, 'MCQ', 1),
(5131, 147, 'What does JSON stand for?', 'JavaScript Object Notation', 'Java Standard Object Names', 'JavaScript Output Network', 'JQuery Serialized Object Naming', 'A', 'JSON stands for JavaScript Object Notation, a lightweight text format for data interchange.', 'BEGINNER', 1, 'MCQ', 1),
(5132, 147, 'Which of the following is valid JSON?', '{''name'': ''Ada''}', '{''name'': "Ada"}', '{"name": "Ada"}', '{name: "Ada"}', 'C', 'JSON requires double-quoted property names and string values, so {"name": "Ada"} is valid.', 'BEGINNER', 1, 'MCQ', 1),
(5133, 147, 'What does the JavaScript method JSON.parse do?', 'Turns an object into a string', 'Converts a JSON string into a JavaScript value', 'Sends a request to a server', 'Encodes data as base64', 'B', 'JSON.parse converts a valid JSON string into its corresponding JavaScript object or value.', 'BEGINNER', 1, 'MCQ', 1),
(5134, 147, 'What does the JavaScript method JSON.stringify do?', 'Converts a JavaScript value into a JSON string', 'Parses a JSON string', 'Compresses an object', 'Validates form input', 'A', 'JSON.stringify serializes a JavaScript value into a JSON-formatted string for transmission or storage.', 'BEGINNER', 1, 'MCQ', 1),
(5135, 147, 'What does AJAX stand for?', 'Asynchronous JavaScript and XML', 'Active Java Application eXchange', 'Automatic JSON and XML', 'Asynchronous JSON and XML', 'A', 'AJAX stands for Asynchronous JavaScript and XML, a technique for updating pages without full reloads.', 'BEGINNER', 1, 'MCQ', 1),
(5136, 147, 'Which JavaScript object is used to make an HTTP request?', 'XMLHttpRequest', 'JSONParser', 'Document', 'HTMLElement', 'B', 'XMLHttpRequest is the traditional browser object used to perform asynchronous HTTP requests.', 'BEGINNER', 1, 'MCQ', 1),
(5137, 147, 'Which newer fetch-based API is commonly used for AJAX requests in modern JavaScript?', 'fetch()', 'request()', 'retrieve()', 'transfer()', 'A', 'fetch() is the modern promise-based API for making network requests in the browser.', 'BEGINNER', 1, 'MCQ', 1),
(5138, 147, 'Which MIME type should a server set for JSON responses?', 'text/html', 'application/json', 'text/plain', 'image/png', 'B', 'application/json is the correct MIME type signalling that the response body is JSON.', 'BEGINNER', 1, 'MCQ', 1),
(5139, 147, 'In JSON, how are arrays represented?', 'With parentheses ()', 'With angle brackets <>', 'With square brackets []', 'With curly braces {}', 'C', 'JSON arrays are ordered lists enclosed in square brackets, such as [1, 2, 3].', 'BEGINNER', 1, 'MCQ', 1),
(5140, 147, 'Which property of AJAX means the page continues responding while a request is in flight?', 'Synchronous', 'Asynchronous', 'Idempotent', 'Serialized', 'B', 'Asynchronous execution lets JavaScript keep running and handle the response later instead of blocking.', 'BEGINNER', 1, 'MCQ', 1),
(5141, 147, 'What does JSON.parse(''{"a":1}'') return in JavaScript?', 'A string', 'An object with property a equal to 1', 'An array', 'null', 'B', 'JSON.parse builds a real JavaScript object, so the result has a numeric property a of 1.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5142, 147, 'What happens when JSON.parse is called on the string ''{"a":}''?', 'Returns null', 'Returns an empty object', 'Throws a SyntaxError because the JSON is invalid', 'Returns undefined', 'C', 'A missing value after the colon is invalid JSON, so JSON.parse throws a SyntaxError.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5143, 147, 'What is the difference between XMLHttpRequest with async true and async false?', 'No difference', 'async true is blocking, false is non-blocking', 'async true is non-blocking, false blocks the page until completion', 'async controls compression', 'C', 'async true lets the page continue working, while async false freezes script execution until the response arrives.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5144, 147, 'In a fetch chain, which method converts the response body into a JSON object?', 'response.text()', 'response.json()', 'response.parse()', 'response.format()', 'B', 'response.json() reads the body stream and parses it as JSON, returning a promise of the resulting value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5145, 147, 'How do you check whether a fetch request succeeded with status 200-299?', 'Using response.ok', 'Checking response.url', 'Using response.type', 'Comparing response.headers', 'A', 'response.ok is true whenever the HTTP status is in the successful 200-299 range.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5146, 147, 'What is a common cause of JSON.parse throwing while fetching data?', 'The server returned non-JSON, such as an HTML error page', 'The connection was too slow', 'The data was too large', 'The browser is offline', 'A', 'If the server returns an HTML error page instead of JSON, parsing it throws a SyntaxError.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5147, 147, 'How does jQuery''s $.ajax with dataType ''json'' differ from a plain GET?', 'It automatically parses the JSON response into a JavaScript object', 'It always uses POST', 'It disables caching', 'It returns a string always', 'A', 'jQuery inspects the dataType setting and automatically parses the response body into an object.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5148, 147, 'What does CORS stand for and why is it relevant to AJAX?', 'Cross-Origin Resource Sharing, which governs browser requests between origins', 'Common Origin Request System', 'Central Online Resource Service', 'Cross-Opening Response Standard', 'A', 'CORS is a browser security mechanism that controls whether scripts on one origin may fetch resources from another.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5149, 147, 'Which of these is the correct JSON representation of a list of names?', '["Ana", "Ben", "Cara"]', '{"Ana", "Ben", "Cara"}', '("Ana", "Ben", "Cara")', '"Ana", "Ben", "Cara"', 'A', 'A JSON array of strings uses square brackets with each value double-quoted and comma-separated.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5150, 147, 'What does fetch(''url'').then(r => r.json()) accomplish?', 'Sends the body as JSON', 'Fetches the URL and parses the JSON response', 'Compresses the response', 'Cancels the request', 'B', 'fetch starts the request and the .json() call parses the resolved response body into a JavaScript value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5151, 147, 'A fetch to another origin fails in the browser even though curl works. What is the most likely cause?', 'The server lacks CORS headers for browser requests', 'The URL has a typo', 'The client is offline', 'HTTP is disabled', 'A', 'Browsers enforce CORS, so without the correct Access-Control-Allow-Origin header the response is blocked.', 'ADVANCED', 3, 'MCQ', 1),
(5152, 147, 'What happens to a fetch promise when the server responds with status 500?', 'It rejects immediately', 'It resolves because the request completed; the caller must check response.ok', 'It retries automatically', 'It returns null', 'B', 'fetch only rejects on network failure, so an HTTP 500 still resolves and the caller must inspect the status.', 'ADVANCED', 3, 'MCQ', 1),
(5153, 147, 'Which header must the server send for a browser to allow a cross-origin POST with Content-Type application/json?', 'Access-Control-Allow-Origin', 'Set-Cookie', 'Retry-After', 'X-Requested-With', 'A', 'Access-Control-Allow-Origin authorizes the browser to expose the response to the requesting origin.', 'ADVANCED', 3, 'MCQ', 1),
(5154, 147, 'Why do many APIs use JSON over XML?', 'JSON is smaller and easier to parse in JavaScript', 'XML is faster to transmit', 'JSON requires more libraries', 'XML is more secure by default', 'A', 'JSON''s compact syntax and native JavaScript parsing make it lighter and simpler than XML for most APIs.', 'ADVANCED', 3, 'MCQ', 1),
(5155, 147, 'What is the difference between JSON.stringify on an object containing a function and one without?', 'Functions are serialized normally', 'Functions are omitted because JSON has no function type', 'Functions become strings', 'The object becomes null', 'B', 'JSON has no function representation, so JSON.stringify silently drops function properties.', 'ADVANCED', 3, 'MCQ', 1),
(5156, 147, 'Which server-side technique lets a long AJAX request appear to ''hang'' until new data arrives?', 'Long polling', 'Synchronous XMLHttpRequest', 'Cookie flashing', 'Document fragments', 'A', 'Long polling keeps the connection open until the server has new data to send, then immediately reopens it.', 'ADVANCED', 3, 'MCQ', 1),
(5157, 147, 'How should a page gracefully degrade when JSON.parse of a fetched response fails?', 'Let the error propagate uncaught', 'Wrap parsing in a try/catch and show a fallback message or state', 'Reload the page', 'Return 500 to the user', 'B', 'Catching the parse error and showing fallback UI keeps the application usable when data is malformed.', 'ADVANCED', 3, 'MCQ', 1),
(5158, 147, 'What is the primary benefit of sending JSON over a compact binary protocol like Protocol Buffers?', 'Binary is always safer', 'JSON is human-readable and works everywhere without a schema step', 'Binary cannot be cached', 'JSON transfers faster in all cases', 'B', 'JSON''s human-readable format and universal support trade size for simplicity and debuggability.', 'ADVANCED', 3, 'MCQ', 1),
(5159, 147, 'When uploading a large file via AJAX, which object reports upload progress?', 'XMLHttpRequest.upload', 'document.readyState', 'navigator.onLine', 'history.state', 'A', 'XMLHttpRequest.upload exposes progress events so the UI can show upload completion percentages.', 'ADVANCED', 3, 'MCQ', 1),
(5160, 147, 'Which pattern sends a fallback request when a cross-origin JSONP-style callback would be blocked?', 'Using fetch with CORS headers negotiated by the server', 'Increasing the timeout', 'Switching to FTP', 'Disabling JavaScript', 'A', 'Proper CORS support from the server is the modern replacement for workarounds like JSONP callbacks.', 'ADVANCED', 3, 'MCQ', 1),
(5161, 148, 'What is a cookie in web development?', 'A small piece of data stored in the browser by a website', 'A hardware device', 'A type of database', 'A server log file', 'A', 'A cookie is a small text record that a server stores in the browser, associated with that domain.', 'BEGINNER', 1, 'MCQ', 1),
(5162, 148, 'Which web API stores key-value data with no expiration in the browser?', 'sessionStorage', 'localStorage', 'cookies', 'indexedDB', 'B', 'localStorage persists data indefinitely until it is explicitly removed by script or the user.', 'BEGINNER', 1, 'MCQ', 1),
(5163, 148, 'Which web API stores data for the lifetime of a single browser tab?', 'localStorage', 'sessionStorage', 'Service Worker', 'WebSQL', 'B', 'sessionStorage scopes data to one tab and clears it when that tab closes.', 'BEGINNER', 1, 'MCQ', 1),
(5164, 148, 'Which HTTP header is used to send a cookie back to the server?', 'Set-Cookie', 'Cookie', 'Authorization', 'Accept-Language', 'B', 'The Cookie request header carries stored cookie values back to the server on subsequent requests.', 'BEGINNER', 1, 'MCQ', 1),
(5165, 148, 'Which HTTP header is used by the server to store a cookie in the browser?', 'Set-Cookie', 'Cookie', 'Location', 'Content-Disposition', 'A', 'The server sends Set-Cookie in its response to instruct the browser to store the cookie.', 'BEGINNER', 1, 'MCQ', 1),
(5166, 148, 'What is the approximate default storage limit for localStorage in modern browsers?', 'About 1 KB', 'About 5-10 MB', 'About 1 GB', 'Unlimited', 'B', 'Most browsers cap localStorage at roughly 5-10 MB per origin.', 'BEGINNER', 1, 'MCQ', 1),
(5167, 148, 'Which of the following data is best suited for localStorage?', 'The user''s session token', 'Passwords', 'Small non-sensitive preferences', 'Server database backups', 'C', 'localStorage is appropriate for small, non-sensitive preferences because it is accessible to any script on the origin.', 'BEGINNER', 1, 'MCQ', 1),
(5168, 148, 'What does the JavaScript statement localStorage.setItem(''theme'', ''dark'') do?', 'Deletes the theme key', 'Stores the value dark under the key theme', 'Sends theme to the server', 'Creates a cookie', 'B', 'setItem stores a string value under the given key in localStorage.', 'BEGINNER', 1, 'MCQ', 1),
(5169, 148, 'Which JavaScript call retrieves the value stored under a localStorage key?', 'localStorage.getItem(''theme'')', 'localStorage.getValue(''theme'')', 'localStorage.fetch(''theme'')', 'localStorage.read(''theme'')', 'A', 'getItem returns the string stored for the given key, or null if the key does not exist.', 'BEGINNER', 1, 'MCQ', 1),
(5170, 148, 'What happens to cookies when the user closes the browser?', 'All cookies always remain', 'Session cookies are usually deleted, but cookies with an Expires or Max-Age may persist', 'Cookies move to the server', 'Cookies double in size', 'B', 'Session-only cookies die with the session, while persistent cookies survive because they carry an expiry.', 'BEGINNER', 1, 'MCQ', 1),
(5171, 148, 'How much data can a single cookie typically hold?', 'About 4 KB', 'About 5 MB', 'About 64 KB', 'Unlimited', 'A', 'Individual cookies are limited to roughly 4 KB, far less than localStorage.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5172, 148, 'What happens when localStorage is accessed in a private or incognito browsing mode?', 'It always works normally', 'It may throw a SecurityError or fail to persist', 'It stores data on the server', 'It converts data to cookies', 'B', 'Some browsers restrict storage in private mode, causing access attempts to throw or silently not persist.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5173, 148, 'Why is a session token safer in an HttpOnly cookie than in localStorage?', 'HttpOnly cookies cannot be read by JavaScript, reducing XSS theft', 'Cookies are encrypted by default', 'localStorage is server-side', 'HttpOnly cookies never expire', 'A', 'An HttpOnly cookie is invisible to document.cookie and script, so stolen-script attacks cannot read the token.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5174, 148, 'Which attribute of a cookie restricts it to HTTPS connections only?', 'Secure', 'Domain', 'Path', 'SameSite', 'A', 'The Secure attribute makes the browser send the cookie only over encrypted HTTPS connections.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5175, 148, 'Which cookie attribute limits the cookie to a specific URL path?', 'Max-Age', 'Path', 'Priority', 'Domain', 'B', 'The Path attribute restricts the cookie so it is only sent for requests under that path.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5176, 148, 'What does the cookie attribute SameSite=Lax prevent?', 'Cross-site requests sending the cookie except for top-level navigation', 'All cookie storage', 'Secure-only transmission', 'JavaScript reading cookies', 'A', 'SameSite=Lax blocks the cookie on cross-site subrequests while still allowing top-level navigations.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5177, 148, 'In what order should localStorage and sessionStorage be used for the same data?', 'They share the same storage and cannot both be used', 'sessionStorage for tab-local data, localStorage for data that should survive tab closing', 'localStorage always, sessionStorage never', 'sessionStorage always, localStorage never', 'B', 'Choose sessionStorage when data belongs to one tab and localStorage when data should persist across sessions.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5178, 148, 'What does the Size QuotaExceededError signal?', 'The server is full', 'The browser storage quota has been exceeded', 'The page is too large', 'A network error', 'B', 'QuotaExceededError is thrown when writing would push the origin past its storage limit.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5179, 148, 'What happens to a cookie with both Expires and Max-Age attributes?', 'Expires wins in all browsers', 'Max-Age takes precedence where supported', 'Both are ignored', 'The browser crashes', 'B', 'The Max-Age attribute takes precedence over Expires in browsers that support it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5180, 148, 'How can a website read a cookie set for a parent domain like example.com from sub.example.com?', 'It cannot be done', 'By setting the cookie Domain attribute to example.com', 'By using localStorage', 'By setting HttpOnly', 'B', 'A cookie with Domain=example.com is shared across all subdomains including sub.example.com.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5181, 148, 'Why is storing sensitive data like passwords in localStorage considered risky?', 'localStorage is server-side', 'Any script running on the origin can read it, and it survives until explicitly removed', 'localStorage encrypts data', 'localStorage expires every hour', 'B', 'localStorage is readable by any script on the origin and persists, so a single XSS can exfiltrate it.', 'ADVANCED', 3, 'MCQ', 1),
(5182, 148, 'Which cookie flag protects against CSRF attacks by restricting cross-site sending?', 'HttpOnly', 'SameSite', 'Max-Age', 'Domain', 'B', 'SameSite prevents the browser from sending the cookie on cross-site requests, blocking many CSRF attacks.', 'ADVANCED', 3, 'MCQ', 1),
(5183, 148, 'What is the difference between the Path and Domain cookie attributes?', 'Domain controls which hosts receive the cookie, Path controls which URL prefixes', 'They are identical', 'Path controls hosts, Domain controls URLs', 'Both are deprecated', 'A', 'Domain restricts the cookie to a host or subdomains, while Path restricts it to URL prefixes on that host.', 'ADVANCED', 3, 'MCQ', 1),
(5184, 148, 'A multi-tab application needs shared real-time state that survives reloads. Which option is best?', 'sessionStorage', 'localStorage combined with storage events', 'An in-memory variable', 'A hidden input field', 'B', 'localStorage plus the ''storage'' event synchronizes values across tabs and survives page reloads.', 'ADVANCED', 3, 'MCQ', 1),
(5185, 148, 'What does the ''storage'' event fire and where?', 'In all other tabs of the same origin when localStorage changes', 'In the tab that made the change', 'On the server', 'In the console only', 'A', 'The storage event fires in other tabs/windows of the same origin, letting them react to the change.', 'ADVANCED', 3, 'MCQ', 1),
(5186, 148, 'Which attribute must a cookie have to be inaccessible to document.cookie?', 'Secure', 'HttpOnly', 'SameSite', 'Path=/', 'B', 'HttpOnly removes the cookie from the JavaScript cookie view, protecting it from XSS reads.', 'ADVANCED', 3, 'MCQ', 1),
(5187, 148, 'What is the primary trade-off between cookies and localStorage for storing small data?', 'Cookies are larger', 'Cookies are sent with every HTTP request, increasing traffic, while localStorage stays on the client', 'localStorage is sent with every request', 'They are identical', 'B', 'Every cookie is transmitted on each request to its domain, so localStorage avoids that overhead for client-only data.', 'ADVANCED', 3, 'MCQ', 1),
(5188, 148, 'What is the danger of using JSON.parse directly on data read from localStorage?', 'Malformed or tampered data can throw or produce unexpected values', 'localStorage stores binary only', 'It is always safe', 'The parse happens on the server', 'A', 'localStorage data is user-modifiable, so parsing untrusted JSON requires validation and error handling.', 'ADVANCED', 3, 'MCQ', 1),
(5189, 148, 'Which cookie flag is most effective at blocking third-party tracking across sites?', 'HttpOnly', 'Secure', 'SameSite=Strict', 'Max-Age=0', 'C', 'SameSite=Strict stops the cookie from being sent on any cross-site request, limiting cross-site tracking.', 'ADVANCED', 3, 'MCQ', 1),
(5190, 148, 'To invalidate a session on logout, what is the correct cookie approach?', 'Set the cookie value to the same token', 'Set Max-Age=0 or an Expires in the past so the browser deletes it', 'Remove the Domain attribute', 'Increase the Path value', 'B', 'Expiring the cookie immediately, with Max-Age=0 or a past Expires, removes it from the browser.', 'ADVANCED', 3, 'MCQ', 1),
(5191, 149, 'What is a WebSocket?', 'A full-duplex communication channel over a single TCP connection', 'A type of HTTP request', 'A database protocol', 'A CSS framework', 'A', 'WebSockets provide a persistent, full-duplex channel where both client and server can send messages anytime.', 'BEGINNER', 1, 'MCQ', 1),
(5192, 149, 'Which protocol does a WebSocket URL beginning with wss:// use?', 'Plain HTTP', 'A secure TCP connection with TLS', 'FTP', 'SMTP', 'B', 'wss:// is the secure WebSocket scheme, using TLS encryption over the underlying TCP connection.', 'BEGINNER', 1, 'MCQ', 1),
(5193, 149, 'How does WebSocket communication compare with HTTP?', 'Both close after one response', 'WebSocket keeps the connection open for two-way exchange, unlike request-response HTTP', 'HTTP is full-duplex', 'WebSocket only sends one message', 'B', 'HTTP follows a request-response cycle, while WebSockets hold an open bidirectional channel.', 'BEGINNER', 1, 'MCQ', 1),
(5194, 149, 'Which JavaScript API creates a WebSocket connection?', 'new WebSocket(url)', 'new Socket(url)', 'connect(url)', 'fetchSocket(url)', 'A', 'The WebSocket constructor, new WebSocket(url), opens a connection to the given endpoint.', 'BEGINNER', 1, 'MCQ', 1),
(5195, 149, 'What does the abbreviation SSE stand for in web real-time technology?', 'Server-Sent Events', 'Secure Socket Exchange', 'Serialized Stream Engine', 'Server State Extension', 'A', 'SSE stands for Server-Sent Events, a one-way push channel from server to client over HTTP.', 'BEGINNER', 1, 'MCQ', 1),
(5196, 149, 'Which direction of communication does Server-Sent Events support?', 'Bidirectional', 'Server-to-client only', 'Client-to-server only', 'Neither direction', 'B', 'SSE pushes data from server to client; the client cannot stream messages back over the same channel.', 'BEGINNER', 1, 'MCQ', 1),
(5197, 149, 'Which built-in JavaScript object is used with Server-Sent Events?', 'EventSource', 'WebSocket', 'XMLHttpRequest', 'Worker', 'A', 'EventSource is the browser API that listens to an SSE stream pushed by the server.', 'BEGINNER', 1, 'MCQ', 1),
(5198, 149, 'What protocol does SSE use for its underlying connection?', 'A custom binary protocol', 'Standard HTTP', 'SMTP', 'UDP', 'B', 'SSE runs over ordinary HTTP, making it simple to deploy and compatible with existing proxies.', 'BEGINNER', 1, 'MCQ', 1),
(5199, 149, 'Which HTTP upgrade request header is used to initiate a WebSocket handshake?', 'Upgrade', 'Sec-WebSocket-Key', 'Connection', 'Accept', 'C', 'The Upgrade header tells the server to switch protocols, along with a 101 Switching Protocols response.', 'BEGINNER', 1, 'MCQ', 1),
(5200, 149, 'What response status code completes a successful WebSocket handshake?', '200', '101', '301', '404', 'B', 'Status 101 Switching Protocols confirms the connection is being upgraded to WebSocket.', 'BEGINNER', 1, 'MCQ', 1),
(5201, 149, 'Which method sends a message over an open WebSocket connection?', 'socket.send(''hi'')', 'socket.write(''hi'')', 'socket.emit(''hi'')', 'socket.post(''hi'')', 'A', 'WebSocket''s send() transmits a text or binary message to the server once the connection is open.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5202, 149, 'What does the WebSocket event open represent?', 'The connection failed', 'The handshake completed and messages can be exchanged', 'The server closed the socket', 'A message was received', 'B', 'The open event fires when the handshake finishes, marking the connection ready for use.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5203, 149, 'How can the client know when the server closed a WebSocket connection?', 'The close event', 'The error event', 'The message event', 'The open event', 'A', 'The close event fires whenever the connection terminates, whether initiated by either side.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5204, 149, 'Which of the following is a typical use case for WebSockets?', 'A live chat application', 'A static documentation page', 'A one-time form submission', 'A plain image gallery', 'A', 'Live chat needs low-latency two-way updates, which is exactly what WebSockets provide.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5205, 149, 'What content type must a server stream for Server-Sent Events?', 'text/event-stream', 'application/json', 'text/html', 'image/gif', 'A', 'The SSE response uses the text/event-stream content type to signal the event stream format.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5206, 149, 'What happens if a WebSocket connection drops on a flaky network?', 'The connection never reconnects', 'The browser fires close and the app must reconnect', 'Data is silently lost', 'The server restarts', 'B', 'The close event fires and the application is responsible for reconnecting and resynchronizing state.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5207, 149, 'What is a heartbeat in a WebSocket application?', 'A periodic ping message to detect dead connections', 'A chat emoji', 'A CSS animation', 'A database backup', 'A', 'Heartbeats send periodic small messages so either side can detect when a connection has silently died.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5208, 149, 'Why is a single WebSocket better than polling for a stock ticker?', 'WebSocket is slower', 'It pushes updates instantly with no repeated request overhead', 'It uses less CPU on the server', 'It is more secure', 'B', 'A persistent socket delivers updates as they happen, avoiding the latency and traffic of repeated polls.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5209, 149, 'Which scenario best fits Server-Sent Events over WebSockets?', 'A bidirectional game', 'One-way notification feeds like news tickers or activity streams', 'File uploads', 'Database queries', 'B', 'SSE is ideal for one-way server pushes such as notifications, where client-to-server traffic is minimal.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5210, 149, 'How do WebSocket frames differ from full HTTP messages?', 'Frames are lightweight messages over a persistent connection instead of full request-response cycles', 'Frames are larger', 'Frames replace the TCP layer', 'Frames are unencrypted', 'A', 'WebSocket messages travel as small frames over one open connection, avoiding HTTP header overhead per message.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5211, 149, 'A chat app''s WebSocket server crashes mid-session. What must the client implement?', 'Reconnection with a resume or resync strategy', 'Nothing, the connection recovers itself', 'A full page reload', 'A DNS change', 'A', 'Clients should auto-reconnect and reconcile missed messages to stay consistent after server outages.', 'ADVANCED', 3, 'MCQ', 1),
(5212, 149, 'Why might a company choose SSE over WebSockets for a notification feed?', 'SSE is full-duplex and faster', 'SSE reconnects automatically via HTTP and works through more proxies', 'SSE supports binary uploads', 'SSE does not need a server', 'B', 'SSE has built-in auto-reconnection over ordinary HTTP, which works with far more infrastructure than WebSockets.', 'ADVANCED', 3, 'MCQ', 1),
(5213, 149, 'What is a common scaling challenge when many WebSocket connections share one server?', 'Each open socket holds a persistent connection, so memory and connections grow per user', 'CPU never grows', 'Disks fill with logs', 'TLS is disabled', 'A', 'Persistent connections consume server resources per socket, requiring careful load balancing and sticky sessions.', 'ADVANCED', 3, 'MCQ', 1),
(5214, 149, 'Which strategy handles a WebSocket flood of messages overwhelming a client''s UI?', 'Rendering every message as fast as possible', 'Batching and throttling UI updates or applying backpressure', 'Closing the socket', 'Ignoring all messages', 'B', 'Throttling or batching prevents layout thrash and keeps the interface responsive under high message rates.', 'ADVANCED', 3, 'MCQ', 1),
(5215, 149, 'In a multi-server WebSocket deployment, how should a message be routed to a specific connected user?', 'A shared pub/sub layer such as Redis broadcasts or routes to the server owning that socket', 'Each server holds all sockets', 'The database sends the message', 'Polling every server', 'A', 'A pub/sub broker lets any server publish messages that reach the server currently holding the target connection.', 'ADVANCED', 3, 'MCQ', 1),
(5216, 149, 'What is the main reason WebSockets and SSE are typically preferred over long polling today?', 'Long polling reconnects more often and uses more overhead for each update', 'Long polling is full-duplex', 'Long polling is secure by default', 'Long polling has no latency', 'A', 'Long polling opens a fresh request for every update, while sockets and SSE maintain one efficient connection.', 'ADVANCED', 3, 'MCQ', 1),
(5217, 149, 'How does backpressure work when a server sends messages faster than the client can process them?', 'The server pauses or buffers until the client catches up', 'Messages are dropped silently', 'The socket reopens', 'The client restarts', 'A', 'Applying backpressure lets the sender slow down, preventing memory exhaustion and data loss.', 'ADVANCED', 3, 'MCQ', 1),
(5218, 149, 'Which option correctly secures a WebSocket connection?', 'Always use wss:// with TLS and validate origins', 'Using ws:// over HTTP', 'Sending passwords in the URL', 'Disabling heartbeat', 'A', 'TLS (wss://) encrypts frames and origin checks prevent cross-site hijacking of sockets.', 'ADVANCED', 3, 'MCQ', 1),
(5219, 149, 'What is the typical maximum practical message size to send over a WebSocket in one frame?', 'No limit at all', 'A few MB at most, with large payloads chunked or streamed', '50 bytes', 'Exactly 1 GB', 'B', 'Very large single messages can stall the connection, so chunks and streams are used for big payloads.', 'ADVANCED', 3, 'MCQ', 1),
(5220, 149, 'What does an event ID in an SSE stream enable?', 'The client to resume from the last processed event after a reconnect', 'The server to reject events', 'Encryption of events', 'Compression of events', 'A', 'Last-Event-ID lets a reconnecting client tell the server which event it last received so nothing is missed.', 'ADVANCED', 3, 'MCQ', 1),
(5221, 150, 'What does XSS stand for?', 'Cross-Site Scripting', 'Extra Secure System', 'XML Site Syntax', 'Cross-Site Sending', 'A', 'XSS stands for Cross-Site Scripting, an attack that injects malicious scripts into web pages.', 'BEGINNER', 1, 'MCQ', 1),
(5222, 150, 'Which attack tricks a user into executing unwanted actions on a site where they are authenticated?', 'CSRF', 'SQL injection', 'Phishing via email', 'Denial of service', 'B', 'CSRF (Cross-Site Request Forgery) forges requests so the victim''s browser performs actions they did not intend.', 'BEGINNER', 1, 'MCQ', 1),
(5223, 150, 'What is the purpose of HTTPS?', 'To make pages load faster', 'To encrypt traffic between the browser and server', 'To store cookies', 'To compress images', 'B', 'HTTPS uses TLS to encrypt data in transit, protecting it from eavesdropping and tampering.', 'BEGINNER', 1, 'MCQ', 1),
(5224, 150, 'Which type of attack targets database queries by injecting malicious input?', 'SQL injection', 'XSS', 'CSRF', 'Phishing', 'C', 'SQL injection occurs when user input is placed directly into SQL queries without sanitization.', 'BEGINNER', 1, 'MCQ', 1),
(5225, 150, 'What is CORS in the context of web security?', 'A mechanism controlling cross-origin resource access in browsers', 'A database engine', 'A CSS layout technique', 'A password manager', 'A', 'CORS (Cross-Origin Resource Sharing) governs which origins a browser allows a page to access.', 'BEGINNER', 1, 'MCQ', 1),
(5226, 150, 'What does ''sanitizing'' user input mean?', 'Cleaning and validating input to remove dangerous content', 'Encrypting the input', 'Compressing the input', 'Sending input to the server', 'A', 'Sanitization strips or escapes dangerous characters so the input cannot inject scripts or SQL.', 'BEGINNER', 1, 'MCQ', 1),
(5227, 150, 'Which of the following is a strong password characteristic?', 'Using only your birth year', 'Being short and easy to remember', 'A long mix of letters, numbers and symbols', 'Using the word password', 'C', 'Length and variety make passwords hard to guess, especially when combined with other measures.', 'BEGINNER', 1, 'MCQ', 1),
(5228, 150, 'What is the primary purpose of input validation?', 'Rejecting data that does not meet expected rules before it is used', 'Making the page prettier', 'Speeding up the server', 'Reducing the number of files', 'A', 'Validation ensures incoming data matches expected formats and ranges, preventing malformed or malicious values.', 'BEGINNER', 1, 'MCQ', 1),
(5229, 150, 'Which HTTP response header is used by a server to allow a specific origin?', 'Access-Control-Allow-Origin', 'Set-Cookie', 'Content-Type', 'Location', 'A', 'Access-Control-Allow-Origin tells the browser which origin is permitted to read the response.', 'BEGINNER', 1, 'MCQ', 1),
(5230, 150, 'What is a security vulnerability?', 'A weakness in a system that can be exploited', 'A type of virus', 'A performance improvement', 'A programming language', 'A', 'A vulnerability is any flaw an attacker can exploit to compromise a system.', 'BEGINNER', 1, 'MCQ', 1),
(5231, 150, 'A page inserts user comments directly into HTML with innerHTML. What attack is it vulnerable to?', 'SQL injection', 'Stored XSS', 'CSRF', 'DNS rebinding', 'B', 'Persisting unescaped user HTML leads to stored XSS because any viewer''s browser executes the injected script.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5232, 150, 'Which encoding strategy defeats XSS when inserting text into HTML?', 'HTML-escaping characters like < and > before output', 'Using innerHTML', 'Upper-casing the input', 'Sending it to the console', 'A', 'Escaping angle brackets and quotes prevents injected content from being treated as markup.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5233, 150, 'How does a CSRF token protect a form?', 'The server validates a per-session unpredictable token included in the request', 'The token hides the form', 'The token compresses data', 'The token speeds up the request', 'A', 'A unique per-session token proves the request came from the real form, since attackers cannot guess it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5234, 150, 'What does SameSite=Strict do on a cookie?', 'It blocks the cookie from being sent on cross-site requests', 'It makes the cookie bigger', 'It encrypts the cookie', 'It deletes the cookie', 'A', 'SameSite=Strict prevents the browser from sending the cookie on any cross-site request, blocking CSRF.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5235, 150, 'What does SQL injection ''SELECT * FROM users WHERE id = 1 OR 1=1'' demonstrate?', 'The query returns all users because the condition is always true', 'The query fails with a syntax error', 'The database shuts down', 'The query is optimized', 'A', 'OR 1=1 makes the WHERE clause always true, returning every row when input is concatenated unsafely.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5236, 150, 'What is the correct mitigation for SQL injection?', 'Parameterized queries or prepared statements', 'Escaping the entire query', 'Using more indexes', 'Disabling the database', 'A', 'Parameterized statements separate data from SQL structure, so injected text cannot change the query.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5237, 150, 'Which Content Security Policy goal directly mitigates XSS?', 'Restricting which scripts a page may load and execute', 'Speeding up page loads', 'Compressing images', 'Caching fonts', 'A', 'CSP blocks inline and untrusted scripts, so injected script tags fail to execute.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5238, 150, 'What does the HTTP Strict Transport Security header enforce?', 'Browsers only connect to the site over HTTPS', 'Cookies are deleted', 'JavaScript is disabled', 'Forms are encrypted', 'A', 'HSTS tells browsers to use HTTPS exclusively, preventing downgrade attacks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5239, 150, 'What is the risk of allowing a page to be embedded in any site''s iframe?', 'Clickjacking, where attackers overlay UI to trick clicks', 'Faster loading', 'Better SEO', 'Stronger encryption', 'A', 'Without X-Frame-Options or CSP frame-ancestors, attackers can iframe the page and trick users into clicks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5240, 150, 'Which header helps prevent MIME-sniffing attacks?', 'X-Content-Type-Options: nosniff', 'Set-Cookie', 'Server', 'Accept-Encoding', 'A', 'nosniff tells browsers to honor declared MIME types instead of guessing, blocking some content confusion.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5241, 150, 'An authenticated bank form lacks a CSRF token and uses no SameSite cookie. What single mitigation is most effective?', 'Adding a per-session CSRF token or SameSite=Strict cookie', 'Adding more colors to the form', 'Renaming the submit button', 'Increasing the timeout', 'A', 'A per-session token or a strict SameSite cookie prevents forged cross-site submissions.', 'ADVANCED', 3, 'MCQ', 1),
(5242, 150, 'Why does output encoding alone not fully protect against XSS in all contexts?', 'Contexts like attribute values, URLs and JSON require different encoding rules', 'Encoding slows the server', 'Encoding deletes data', 'Encoding only works on GET requests', 'A', 'Each injection context needs its own escaping, so one universal encoding can miss attribute or URL sinks.', 'ADVANCED', 3, 'MCQ', 1),
(5243, 150, 'What is the difference between reflected and stored XSS?', 'Stored XSS persists on the server and affects all viewers, reflected only triggers when crafted input is used', 'They are identical', 'Reflected XSS is stored in the database', 'Stored XSS never executes', 'A', 'Reflected XSS bounces input back in one response, while stored XSS is saved and served to many users later.', 'ADVANCED', 3, 'MCQ', 1),
(5244, 150, 'A developer disables CORS checks and sets Access-Control-Allow-Origin: * with credentials. What is the danger?', 'Any origin could read credentialed responses, enabling data theft', 'The site loads faster', 'Cookies become invalid', 'The server restarts', 'A', 'Wildcard CORS with credentials lets any malicious site read responses that rely on the user''s session.', 'ADVANCED', 3, 'MCQ', 1),
(5245, 150, 'What is clickjacking and which header directly defends against it?', 'UI overlay trickery defeated by X-Frame-Options: DENY', 'A type of phishing email', 'A SQL injection variant', 'A brute-force attack', 'A', 'X-Frame-Options: DENY (or a CSP frame-ancestors directive) stops the page from being framed and overlaid.', 'ADVANCED', 3, 'MCQ', 1),
(5246, 150, 'Why are security headers like CSP and HSTS often inspected by automated scanners?', 'Missing headers reveal misconfiguration and increased attack surface', 'Headers speed up pages', 'Headers reduce file size', 'Headers improve SEO', 'A', 'Scanners flag missing headers because their absence widens the attack surface for known attacks.', 'ADVANCED', 3, 'MCQ', 1),
(5247, 150, 'What is the correct order for handling untrusted input?', 'Validate on the server, then encode on output', 'Trust all client input', 'Encode first and skip validation', 'Never validate', 'A', 'Server-side validation rejects bad data and output encoding neutralizes the data that is legitimately rendered.', 'ADVANCED', 3, 'MCQ', 1),
(5248, 150, 'Which practice best protects sensitive tokens that must be sent with API requests?', 'Storing tokens in HttpOnly Secure SameSite cookies and relying on CSRF protections', 'Placing tokens in URLs', 'Hard-coding tokens in scripts', 'Logging tokens to the console', 'A', 'HttpOnly Secure SameSite cookies keep tokens out of script reach and cross-site traffic, with CSRF defenses layered on top.', 'ADVANCED', 3, 'MCQ', 1),
(5249, 150, 'What is the danger of logging raw user input without sanitization?', 'Log injection lets attackers forge or corrupt log entries', 'Logs get shorter', 'Logs become encrypted', 'Logs are deleted', 'A', 'Unescaped input with newlines can inject fake log lines, misleading monitoring and forensics.', 'ADVANCED', 3, 'MCQ', 1),
(5250, 150, 'A site must load scripts only from its own domain and never inline. Which policy expresses this?', 'Content-Security-Policy: default-src ''self''; script-src ''self''', 'X-Content-Type-Options: nosniff', 'Accept: text/html', 'Cache-Control: no-cache', 'A', 'That CSP directive blocks external and inline scripts while permitting same-origin scripts only.', 'ADVANCED', 3, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(5251, 291, 'How would you define a microservice in a distributed system?', 'A small, independently deployable service that handles one business capability', 'A giant monolithic application', 'A database index', 'A single HTML file', 'A', 'Microservices are small, focused services that can be developed, deployed and scaled independently.', 'BEGINNER', 1, 'MCQ', 1),
(5252, 291, 'Which approach is the opposite of microservices architecture?', 'Monolithic architecture', 'Serverless architecture', 'Edge computing', 'CDN caching', 'B', 'A monolith packages all functionality into one application, the opposite of a decomposed microservice design.', 'BEGINNER', 1, 'MCQ', 1),
(5253, 291, 'Which containerisation tool bundles an app together with everything it needs to run?', 'Docker', 'Notepad', 'Excel', 'Paint', 'A', 'Docker packages apps and dependencies into containers that run consistently in any environment.', 'BEGINNER', 1, 'MCQ', 1),
(5254, 291, 'What is a container image?', 'A lightweight, executable package containing the app and its dependencies', 'A screenshot of the app', 'A backup of the database', 'A network packet', 'A', 'A container image is a static snapshot of an app with everything it needs to run.', 'BEGINNER', 1, 'MCQ', 1),
(5255, 291, 'Which tool orchestrates and manages many containers at scale?', 'Kubernetes', 'A text editor', 'A spreadsheet', 'A file manager', 'A', 'Kubernetes coordinates containers, handling scheduling, scaling and networking.', 'BEGINNER', 1, 'MCQ', 1),
(5256, 291, 'Which file defines how a Docker image is built?', 'Dockerfile', 'README.md', 'style.css', 'package-lock.json only', 'A', 'A Dockerfile contains instructions for building a container image.', 'BEGINNER', 1, 'MCQ', 1),
(5257, 291, 'What does the term ''service discovery'' mean in a microservice system?', 'Finding where each service is running so they can talk to each other', 'Searching for bugs', 'Finding free disk space', 'Locating the database backup', 'A', 'Service discovery resolves how services locate each other''s network addresses dynamically.', 'BEGINNER', 1, 'MCQ', 1),
(5258, 291, 'Which of the following is a benefit of microservices?', 'Independent scaling of individual services', 'One big deployment every year', 'Tight coupling of all teams', 'A single shared database schema', 'A', 'Microservices allow each service to scale, deploy and evolve independently.', 'BEGINNER', 1, 'MCQ', 1),
(5259, 291, 'What is an API gateway in a microservice architecture?', 'A single entry point that routes client requests to the right services', 'A firewall only', 'A database', 'A caching layer only', 'A', 'An API gateway fronts the services, routing, authenticating and aggregating requests.', 'BEGINNER', 1, 'MCQ', 1),
(5260, 291, 'Which term describes running multiple instances of a service to handle more load?', 'Horizontal scaling', 'Vertical scaling', 'Downsizing', 'Code obfuscation', 'A', 'Horizontal scaling adds more instances of a service to spread the load.', 'BEGINNER', 1, 'MCQ', 1),
(5261, 291, 'A request in a microservice system calls service A, which calls service B. Which concern becomes important?', 'Managing latency, failure and timeout propagation across the call chain', 'The size of the HTML', 'The colour of the buttons', 'The font family', 'A', 'Chained calls introduce latency and failure modes that must be handled with timeouts and retries.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5262, 291, 'Which pattern prevents a failing service from cascading failures to its callers?', 'Circuit breaker', 'Monolithic rebuild', 'Full replication', 'Static caching', 'A', 'A circuit breaker stops calls to a failing service, protecting callers from timeouts and overload.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5263, 291, 'Which practice is essential for debugging distributed microservices?', 'Centralised logging and tracing with request IDs', 'Reading logs one service at a time on paper', 'Deleting all logs', 'Rebooting services randomly', 'A', 'Centralised logs and distributed tracing correlate requests across services.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5264, 291, 'Two services both read and write the same customer table. Which design problem does this indicate?', 'Shared data ownership that couples the services and makes scaling hard', 'Too much logging', 'Missing CSS', 'Slow internet', 'A', 'Microservices should own their data; sharing tables couples them and breaks independence.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5265, 291, 'Which deployment unit best matches the microservice principle of deploy independently?', 'Each service packaged and deployed on its own', 'All services in one jar', 'Every service in one HTML page', 'All code in one branch', 'A', 'Independent packaging and deployment per service is what makes microservices agile.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5266, 291, 'Which architecture concern arises when teams deploy services on different release schedules?', 'Versioning and compatibility between service contracts', 'The office layout', 'The coffee machine', 'The meeting length', 'A', 'Different release cadences require careful versioning so services stay compatible.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5267, 291, 'Which approach most improves resilience when one microservice is overloaded?', 'Backpressure and graceful degradation in dependent services', 'Adding more HTML', 'Disabling logging', 'Doubling the database', 'A', 'Backpressure lets services signal overload and degrade gracefully instead of failing hard.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5268, 291, 'Which tooling practice helps teams share standard microservice building blocks?', 'Shared base images and service templates across teams', 'Each team reinventing everything', 'Hiding all configuration', 'Deleting shared libraries', 'A', 'Shared images and templates standardise security, logging and startup across services.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5269, 291, 'What is the main advantage of containerising a microservice?', 'It runs identically on a developer laptop and in production', 'It makes code longer', 'It hides all bugs', 'It removes the need for tests', 'A', 'Containers eliminate environment differences so behaviour is consistent everywhere.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5270, 291, 'Which design most effectively handles a long-running job in a microservice without blocking the request?', 'Queueing the job and returning immediately, with a worker consuming it', 'Holding the HTTP request open for an hour', 'Rebooting the server', 'Duplicating the job', 'A', 'Async job queues decouple request handling from long work, keeping services responsive.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5271, 291, 'Which strategy best prevents an API gateway from becoming a single point of failure?', 'Running multiple gateway instances behind a load balancer', 'Running one gateway', 'Disabling the gateway', 'Hard-coding the gateway address', 'A', 'Redundant gateway instances behind a load balancer keep the entry point highly available.', 'ADVANCED', 3, 'MCQ', 1),
(5272, 291, 'Which service-communication pattern reduces coupling between producer and consumer?', 'Event-driven messaging through a broker', 'Direct synchronous calls to a hard-coded URL', 'Shared global variables', 'One big database trigger', 'A', 'Event-driven messaging decouples producers from consumers through a durable broker.', 'ADVANCED', 3, 'MCQ', 1),
(5273, 291, 'A microservice system suffers from distributed transactions across services. Which pattern best addresses it?', 'Saga pattern with compensating actions', 'Two-phase commit across all services', 'One giant transaction', 'Deleting transactions', 'A', 'Sagas break large transactions into local transactions with compensating rollback steps.', 'ADVANCED', 3, 'MCQ', 1),
(5274, 291, 'Which practice best ensures a microservice can be debugged in production?', 'Structured logs, metrics and distributed trace IDs on every request', 'No logging at all', 'Logs only on the developer''s machine', 'Random console prints', 'A', 'Structured observability with trace IDs lets engineers reconstruct requests across services.', 'ADVANCED', 3, 'MCQ', 1),
(5275, 291, 'Why might a small project still choose a monolith over microservices?', 'The operational overhead of many services exceeds the benefits for a small team', 'Monoliths are always slower', 'Microservices are illegal', 'Monoliths need no code', 'A', 'Microservices bring significant operational complexity that only pays off at a certain scale.', 'ADVANCED', 3, 'MCQ', 1),
(5276, 291, 'Which container security practice is essential in a multi-tenant cluster?', 'Running containers with least-privilege user accounts and read-only filesystems', 'Running every container as root', 'Sharing all secrets', 'Disabling namespaces', 'A', 'Least-privilege containers limit the damage if a container is compromised.', 'ADVANCED', 3, 'MCQ', 1),
(5277, 291, 'Which deployment strategy lets a new service version be validated before receiving full traffic?', 'Canary release of the new version to a small slice of users', 'Deleting the old version', 'Switching everyone instantly', 'Skipping validation', 'A', 'Canary releases expose new versions gradually, catching problems before full rollout.', 'ADVANCED', 3, 'MCQ', 1),
(5278, 291, 'Which design best keeps microservice teams autonomous?', 'Each team owning its service, its data and its deployment pipeline', 'One team controlling everything', 'A shared global database', 'Monorepo-only development', 'A', 'Full ownership of service, data and pipeline is what enables team autonomy.', 'ADVANCED', 3, 'MCQ', 1),
(5279, 291, 'Which metric best indicates the health of the whole microservice ecosystem?', 'The error rate and latency of end-to-end user requests across services', 'The number of microservices', 'The lines of code', 'The number of Docker files', 'A', 'End-to-end request health reflects the real user experience regardless of internal structure.', 'ADVANCED', 3, 'MCQ', 1),
(5280, 291, 'Which contract-testing practice best prevents integration breaks between services?', 'Consumer-driven contract tests that each service validates against', 'Testing services only in production', 'No contract at all', 'Random testing', 'A', 'Consumer-driven contracts let providers test against consumer expectations, catching breaks early.', 'ADVANCED', 3, 'MCQ', 1),
(5281, 292, 'What is GraphQL?', 'A query language and runtime for APIs that lets clients request exactly what they need', 'A CSS framework', 'A database engine', 'A hosting service', 'A', 'GraphQL is a query language where clients specify exactly the data they want in a single request.', 'BEGINNER', 1, 'MCQ', 1),
(5282, 292, 'In GraphQL, which operation retrieves data?', 'Query', 'Mutation', 'Subscription', 'Delete', 'A', 'The query operation is used to read data in GraphQL.', 'BEGINNER', 1, 'MCQ', 1),
(5283, 292, 'Which GraphQL operation modifies data?', 'Mutation', 'Query', 'Fragment', 'Scalar', 'A', 'Mutations are the GraphQL operations used to create, update or delete data.', 'BEGINNER', 1, 'MCQ', 1),
(5284, 292, 'What does a GraphQL schema define?', 'The types, queries and mutations the API exposes', 'The colour of the UI', 'The server location', 'The login page', 'A', 'The schema is the contract describing what data and operations the API supports.', 'BEGINNER', 1, 'MCQ', 1),
(5285, 292, 'What is a GraphQL resolver?', 'The function that fetches data for a field', 'A CSS selector', 'A DNS record', 'A load balancer', 'A', 'Resolvers tell GraphQL how to obtain the value for each field.', 'BEGINNER', 1, 'MCQ', 1),
(5286, 292, 'Which GraphQL concept lets a client request only the fields it needs?', 'Field selection', 'Fixed responses', 'Server-defined projections', 'URL parameters', 'A', 'Clients select exactly which fields they want returned.', 'BEGINNER', 1, 'MCQ', 1),
(5287, 292, 'What is the single endpoint typically used by a GraphQL API?', 'One /graphql endpoint for all operations', 'A different URL for every field', 'A random port', 'An FTP server', 'A', 'GraphQL serves all queries and mutations from a single endpoint.', 'BEGINNER', 1, 'MCQ', 1),
(5288, 292, 'What is an API contract?', 'The agreed format and behaviour clients can rely on', 'A legal employment contract', 'A service-level invoice', 'A server certificate', 'A', 'An API contract defines request and response shapes that clients and servers must honour.', 'BEGINNER', 1, 'MCQ', 1),
(5289, 292, 'Which HTTP method is most commonly used for a GraphQL query?', 'POST', 'DELETE', 'PUT', 'HEAD', 'A', 'GraphQL typically uses POST, even for queries, because the query lives in the request body.', 'BEGINNER', 1, 'MCQ', 1),
(5290, 292, 'What does REST stand for?', 'Representational State Transfer', 'Rapid Electronic Software Transfer', 'Realtime Entity Storage', 'Remote Execution Service Tool', 'A', 'REST is an architectural style for building APIs around resources and HTTP verbs.', 'BEGINNER', 1, 'MCQ', 1),
(5291, 292, 'A mobile client needs only three fields but the REST endpoint returns fifty. Which API design problem is this?', 'Over-fetching, which wastes bandwidth and battery', 'Under-fetching', 'Caching', 'Authentication', 'A', 'Over-fetching occurs when an API returns more data than the client needs.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5292, 292, 'A client needs a user and all their posts in one round trip. Which GraphQL feature helps?', 'Nested queries that traverse the relationship in one request', 'Multiple separate HTTP calls', 'CSS animations', 'Server-side rendering only', 'A', 'GraphQL lets clients request related data in one nested query, avoiding round trips.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5293, 292, 'Which GraphQL feature reduces duplication by allowing a reusable set of fields?', 'Fragments', 'Enums', 'Scalars', 'Directives', 'A', 'Fragments define reusable field sets that queries can spread to avoid repetition.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5294, 292, 'How does a GraphQL schema protect clients from unknown field names?', 'Validation against the schema rejects unknown fields at request time', 'Clients get a blank screen', 'The server guesses the field', 'Extra fields are ignored silently', 'A', 'GraphQL validates queries against the schema, so unknown fields fail immediately.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5295, 292, 'Which design concern is a downside of allowing arbitrarily deep GraphQL queries?', 'Malicious clients can create expensive, deeply nested queries', 'It is too fast', 'It uses too little memory', 'It cannot be cached', 'A', 'Deep nested queries can cause expensive server work, so depth and complexity limits are often needed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5296, 292, 'Which API design choice helps a versioned REST API avoid breaking existing clients?', 'Backwards-compatible additions such as new optional fields or new endpoints', 'Deleting old endpoints', 'Renaming all fields', 'Changing response formats randomly', 'A', 'Adding optional fields and new endpoints keeps existing clients working while evolving the API.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5297, 292, 'Which tool is commonly used to document a REST API?', 'OpenAPI/Swagger', 'A text file with no structure', 'A whiteboard', 'An email thread', 'A', 'OpenAPI provides a standard, machine-readable description of a REST API.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5298, 292, 'Which HTTP status code signals a client error such as a missing resource?', '404', '200', '302', '500', 'A', '404 Not Found indicates the requested resource does not exist, a client-side error.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5299, 292, 'Which practice helps API consumers understand pagination?', 'Returning next/prev cursor tokens or page metadata', 'Returning all records in one response', 'Hiding the page count', 'Returning random slices', 'A', 'Explicit pagination metadata lets clients navigate large collections predictably.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5300, 292, 'Which GraphQL feature helps solve the N+1 query problem when resolving lists?', 'Data loaders that batch and deduplicate per-request queries', 'Increasing the database size', 'Adding more resolvers', 'Disabling caching', 'A', 'Data loaders batch field resolution, collapsing many small queries into fewer efficient ones.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5301, 292, 'Which design best protects a public GraphQL API from resource-exhaustion attacks?', 'Query depth, complexity and rate limits enforced at the gateway', 'Unlimited queries', 'No schema validation', 'A single shared resolver', 'A', 'Complexity analysis and limits prevent expensive queries from overloading the server.', 'ADVANCED', 3, 'MCQ', 1),
(5302, 292, 'Which API design decision best supports clients with heterogeneous screen sizes?', 'Designing endpoints to return minimal, flexible data that clients shape as needed', 'Returning one giant fixed payload', 'Returning only image files', 'Ignoring mobile clients', 'A', 'Flexible, minimal responses let each client fetch only what its form factor needs.', 'ADVANCED', 3, 'MCQ', 1),
(5303, 292, 'Which trade-off must a team weigh when choosing GraphQL over REST?', 'Flexible client queries versus added gateway complexity and caching difficulty', 'REST is always worse', 'GraphQL has no schema', 'GraphQL cannot handle reads', 'A', 'GraphQL''s flexibility comes at the cost of more complex caching and operations.', 'ADVANCED', 3, 'MCQ', 1),
(5304, 292, 'How should a team evolve a GraphQL schema without breaking existing clients?', 'Add new fields and types while keeping old fields, using deprecation directives before removal', 'Delete old fields immediately', 'Rename everything', 'Disable the schema', 'A', 'Additive evolution with deprecation lets clients migrate gradually.', 'ADVANCED', 3, 'MCQ', 1),
(5305, 292, 'Which practice best secures a GraphQL API''s sensitive fields?', 'Per-field authorisation checks inside resolvers', 'Trusting the client to filter', 'Serving all data publicly', 'Hiding the schema', 'A', 'Field-level authorisation prevents unauthorised access to sensitive data even within valid queries.', 'ADVANCED', 3, 'MCQ', 1),
(5306, 292, 'Which caching strategy works best with a typical GraphQL API?', 'Persisted queries and edge caching keyed on the query hash', 'Disabling all caching', 'Caching the entire schema', 'Caching only mutations', 'A', 'Persisted queries give cacheable identifiers, making GraphQL caching practical.', 'ADVANCED', 3, 'MCQ', 1),
(5307, 292, 'Which design best handles a REST API that must support both batch and single-item requests?', 'Separate collection and item endpoints with consistent semantics', 'One endpoint that behaves randomly', 'No endpoints', 'A single POST that guesses', 'A', 'Distinct collection and item endpoints keep the API predictable and easy to use.', 'ADVANCED', 3, 'MCQ', 1),
(5308, 292, 'Which approach best communicates API errors to clients consistently?', 'A structured error object with code, message and field details', 'Random error strings', 'Returning HTML error pages', 'Silent failures', 'A', 'Structured error responses let clients handle failures programmatically and reliably.', 'ADVANCED', 3, 'MCQ', 1),
(5309, 292, 'Which concern is most important when opening a REST API to third-party developers?', 'Rate limiting, quotas and clear documentation', 'The number of colours', 'The server''s hostname', 'The repository name', 'A', 'Rate limits and documentation protect the API and make it usable by external developers.', 'ADVANCED', 3, 'MCQ', 1),
(5310, 292, 'Which measure most improves the developer experience of an API?', 'Interactive documentation with live examples and try-it tools', 'No documentation', 'Obfuscated endpoints', 'Vague error messages', 'A', 'Interactive, well-exampled documentation reduces integration time and errors.', 'ADVANCED', 3, 'MCQ', 1),
(5311, 293, 'What does the WebSocket protocol provide?', 'Full-duplex communication over a single TCP connection', 'A one-way email service', 'A static file server', 'A database query language', 'A', 'WebSockets keep a single connection open for two-way, real-time messaging.', 'BEGINNER', 1, 'MCQ', 1),
(5312, 293, 'Which HTTP protocol upgrade initiates a WebSocket connection?', 'The WebSocket handshake via the Upgrade header', 'A POST request', 'A DNS lookup', 'A TLS handshake only', 'A', 'The client sends an HTTP Upgrade request that the server accepts to switch to WebSockets.', 'BEGINNER', 1, 'MCQ', 1),
(5313, 293, 'Which use case is best suited to WebSockets?', 'Live chat and real-time notifications', 'Serving static images', 'Search engine indexing', 'Printing documents', 'A', 'WebSockets excel at low-latency, bidirectional real-time applications like chat.', 'BEGINNER', 1, 'MCQ', 1),
(5314, 293, 'Which JavaScript API opens a WebSocket connection?', 'new WebSocket(url)', 'fetch(url)', 'XMLHttpRequest', 'document.querySelector', 'A', 'The WebSocket constructor creates a connection to the given URL.', 'BEGINNER', 1, 'MCQ', 1),
(5315, 293, 'What does ''full-duplex'' mean?', 'Both client and server can send messages simultaneously', 'Only the client can send', 'Only the server can send', 'Messages alternate one at a time', 'A', 'Full-duplex means data flows in both directions at the same time on the connection.', 'BEGINNER', 1, 'MCQ', 1),
(5316, 293, 'Which event fires when a WebSocket message arrives?', 'onmessage', 'onload', 'onresize', 'onclick', 'A', 'The message event delivers incoming WebSocket data to the client.', 'BEGINNER', 1, 'MCQ', 1),
(5317, 293, 'Which statement best contrasts WebSockets with regular HTTP polling?', 'WebSockets keep one connection open instead of repeatedly requesting updates', 'Polling is always faster', 'WebSockets only work offline', 'Polling needs no server', 'A', 'WebSockets avoid the overhead of constant polling by maintaining a persistent connection.', 'BEGINNER', 1, 'MCQ', 1),
(5318, 293, 'Which protocol do WebSockets use for the initial handshake?', 'HTTP', 'FTP', 'SMTP', 'DNS', 'A', 'WebSocket connections begin with an HTTP handshake that upgrades the connection.', 'BEGINNER', 1, 'MCQ', 1),
(5319, 293, 'What is a chat message broadcast to all connected users called?', 'Broadcast', 'Unicast only', 'A join query', 'A compile step', 'A', 'Broadcasting sends a message to every connected client, common in group chat.', 'BEGINNER', 1, 'MCQ', 1),
(5320, 293, 'Which of the following is a real-time web technology similar to WebSockets?', 'Server-Sent Events', 'FTP', 'SMTP', 'BitTorrent', 'A', 'Server-Sent Events push updates one-way from server to client, another real-time option.', 'BEGINNER', 1, 'MCQ', 1),
(5321, 293, 'A chat app sends a message but the user sees it twice. What is the most likely cause?', 'Duplicate delivery because the message was sent without an idempotency key', 'The server was offline', 'The font was wrong', 'The screen was small', 'A', 'Reconnect or retry logic can resend messages; idempotency keys prevent duplicates.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5322, 293, 'Which challenge arises when a WebSocket server must scale across many machines?', 'Sticky sessions or a shared message bus so clients reach the right server', 'Bigger monitors', 'More colours', 'Longer URLs', 'A', 'Horizontal scaling of WebSockets needs shared state or sticky routing so sessions stay consistent.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5323, 293, 'Which practice handles a dropped WebSocket connection gracefully?', 'Automatic reconnection with exponential backoff', 'Freezing the page', 'Showing a crash screen', 'Uninstalling the browser', 'A', 'Reconnection logic with backoff restores real-time updates after transient drops.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5324, 293, 'Which technology helps a WebSocket server broadcast to clients connected to different nodes?', 'A pub/sub message broker such as Redis Pub/Sub or Kafka', 'A single shared file', 'Email', 'A printer', 'A', 'Pub/sub brokers relay messages between server nodes so every connected client receives broadcasts.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5325, 293, 'Which message pattern lets only clients subscribed to a topic receive updates?', 'Publish/subscribe on a topic', 'Broadcast to everyone', 'Unicast to nobody', 'Sending to a random client', 'A', 'Pub/sub delivers each message only to subscribers of that topic.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5326, 293, 'Which statement about the WebSocket close handshake is correct?', 'Either side can initiate a graceful close with a status code and reason', 'Only the server can close', 'Closing requires a full HTTP request', 'Connections never close', 'A', 'The close frame lets either peer end the connection cleanly with a status code.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5327, 293, 'Which message type is a lightweight control frame used to keep connections alive?', 'Ping/pong heartbeat frames', 'HTTP GET', 'CSS rules', 'SQL queries', 'A', 'Ping/pong frames keep the connection alive and detect dead peers.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5328, 293, 'Which problem is common when mixing WebSockets with classic load balancers?', 'Idle connection timeouts that close long-lived sockets', 'Too much disk space', 'Slow keyboards', 'Dark mode issues', 'A', 'Load balancers may time out idle connections, so settings must tolerate long-lived WebSockets.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5329, 293, 'Which security concern is specific to WebSocket-based chat?', 'Message-level sanitisation to prevent script injection in chat content', 'The screen resolution', 'The login button colour', 'The footer text', 'A', 'Chat content can carry XSS payloads, so it must be sanitised before display.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5330, 293, 'Which design best delivers real-time game state to thousands of players?', 'Sharded WebSocket gateways with a low-latency pub/sub backbone', 'One giant WebSocket for everyone', 'HTTP polling every second', 'Email updates', 'A', 'Sharded gateways plus a fast pub/sub backbone scale real-time broadcasting.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5331, 293, 'How should a system guarantee at-most-once or exactly-once delivery semantics over WebSockets?', 'By assigning message IDs and deduplicating on the receiving side', 'By sending messages faster', 'By using only UDP', 'By ignoring duplicates', 'A', 'Message IDs and receiver-side deduplication enforce delivery guarantees over unreliable networks.', 'ADVANCED', 3, 'MCQ', 1),
(5332, 293, 'Which strategy best recovers client state after a WebSocket reconnect?', 'Replaying missed messages from the last acknowledged sequence number', 'Resetting all state', 'Reconnecting forever', 'Deleting the chat history', 'A', 'Sequence-number replay lets clients resume exactly where they left off.', 'ADVANCED', 3, 'MCQ', 1),
(5333, 293, 'Which design decision most reduces the cost of keeping millions of connections idle?', 'Long-lived connections with efficient heartbeats and shared infrastructure', 'More servers per connection', 'Polling more often', 'Sending larger frames', 'A', 'Efficient heartbeats and pooled infrastructure keep idle connections cheap.', 'ADVANCED', 3, 'MCQ', 1),
(5334, 293, 'Which concern is critical when WebSocket traffic carries financial order data?', 'End-to-end encryption and ordering guarantees', 'The chart colours', 'The page background', 'The button labels', 'A', 'Financial data demands integrity, ordering and confidentiality over the socket.', 'ADVANCED', 3, 'MCQ', 1),
(5335, 293, 'Which approach best authenticates WebSocket connections?', 'Authenticating in the HTTP handshake with a token or cookie', 'Trusting all connections', 'Sending passwords in chat', 'Disabling auth', 'A', 'Authenticating at the upgrade handshake prevents unauthorised socket access.', 'ADVANCED', 3, 'MCQ', 1),
(5336, 293, 'Which metric best indicates the health of a real-time system?', 'Message delivery latency percentiles such as p95 and p99', 'The number of CSS files', 'The screen width', 'The logo size', 'A', 'Latency percentiles reveal the real-time experience most users actually get.', 'ADVANCED', 3, 'MCQ', 1),
(5337, 293, 'Which approach best handles backpressure when a slow client lags behind fast broadcasts?', 'Dropping or coalescing messages for the slow client with a reconnect path', 'Sending unlimited buffers', 'Stopping all traffic', 'Restarting the client', 'A', 'Backpressure strategies prevent slow clients from exhausting server memory.', 'ADVANCED', 3, 'MCQ', 1),
(5338, 293, 'Which technology choice most improves real-time collaboration in a document editor?', 'Operational transformation or CRDTs over the socket channel', 'Saving files only at the end', 'Manual copy-paste', 'Reloading the page', 'A', 'OT and CRDTs resolve concurrent edits to keep collaborators consistent in real time.', 'ADVANCED', 3, 'MCQ', 1),
(5339, 293, 'Why should a production WebSocket service be tested under network interruption?', 'To validate reconnection, resync and ordering behaviour under real failures', 'To make tests slower', 'To consume bandwidth', 'To check the logo', 'A', 'Chaos-style tests confirm clients recover cleanly when networks drop.', 'ADVANCED', 3, 'MCQ', 1),
(5340, 293, 'Which pattern best separates real-time infrastructure from business logic?', 'Gateway connections handling transport while an event-driven core processes messages', 'Putting all logic in the socket handler', 'Hard-coding chat rules', 'Skipping validation', 'A', 'Separating transport from business logic keeps the system maintainable and testable.', 'ADVANCED', 3, 'MCQ', 1),
(5341, 294, 'What is a Progressive Web App (PWA)?', 'A web app that uses modern capabilities to feel like a native app', 'A native iOS app', 'A desktop program', 'A PDF file', 'A', 'PWAs combine web reach with native-like features such as offline support and installability.', 'BEGINNER', 1, 'MCQ', 1),
(5342, 294, 'Which technology gives a PWA offline capability?', 'Service workers', 'CSS grids', 'Cookies', 'Server-side includes', 'A', 'Service workers intercept requests and serve cached content when offline.', 'BEGINNER', 1, 'MCQ', 1),
(5343, 294, 'What is a web app manifest?', 'A JSON file describing the app''s name, icons and display mode', 'A database dump', 'A CSS file', 'A server config', 'A', 'The manifest lets the browser present the PWA as an installable app.', 'BEGINNER', 1, 'MCQ', 1),
(5344, 294, 'Which property of a PWA makes it installable on a device home screen?', 'A valid manifest and service worker with an HTTPS context', 'A long URL', 'A large logo', 'Many pages', 'A', 'Installability requires a manifest, a service worker and a secure context.', 'BEGINNER', 1, 'MCQ', 1),
(5345, 294, 'Which protocol is required to register a service worker?', 'HTTPS', 'HTTP', 'FTP', 'SMTP', 'A', 'Service workers require a secure HTTPS context to work.', 'BEGINNER', 1, 'MCQ', 1),
(5346, 294, 'Which component caches assets for offline use in a PWA?', 'The service worker''s cache API', 'The HTML parser', 'The DNS resolver', 'The compiler', 'A', 'The Cache API inside the service worker stores responses for offline reuse.', 'BEGINNER', 1, 'MCQ', 1),
(5347, 294, 'What is the main benefit of a PWA over a native app for many businesses?', 'A single codebase that works across platforms and stores', 'Guaranteed higher performance', 'Automatic revenue', 'No internet needed ever', 'A', 'PWAs reach every platform with one codebase, avoiding separate native builds.', 'BEGINNER', 1, 'MCQ', 1),
(5348, 294, 'Which feature does the Push API enable in a PWA?', 'Server-to-client notifications even when the app is closed', 'Sending emails', 'Database backups', 'File compression', 'A', 'The Push API delivers server messages that display as notifications.', 'BEGINNER', 1, 'MCQ', 1),
(5349, 294, 'Which lifecycle event fires when a service worker is first installed?', 'install', 'fetch', 'message', 'error', 'A', 'The install event lets the worker precache the app shell.', 'BEGINNER', 1, 'MCQ', 1),
(5350, 294, 'Which event lets a service worker intercept network requests?', 'fetch', 'click', 'scroll', 'resize', 'A', 'The fetch event handler can serve cached responses or modify requests.', 'BEGINNER', 1, 'MCQ', 1),
(5351, 294, 'Which caching strategy serves a cached copy immediately and updates it from the network in the background?', 'Stale-while-revalidate', 'Network only', 'Cache only', 'No caching', 'A', 'Stale-while-revalidate returns the cache instantly and refreshes it quietly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5352, 294, 'Which strategy is best for API data that must always be fresh, such as a user''s balance?', 'Network-first with a cache fallback', 'Cache-first always', 'Never cache', 'Store everything in HTML', 'A', 'Network-first gives fresh data when online while still working offline via the cache.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5353, 294, 'A PWA update ships but users still see the old version. What is the most likely cause?', 'The old service worker controls the page until the new one activates', 'The browser is broken', 'The server is down', 'The cache is empty', 'A', 'New service workers only take control after install and activation, so the old one keeps serving first.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5354, 294, 'Which practice best refreshes a cached PWA after a new release?', 'Versioning the cache and calling skipWaiting and clients.claim on activation', 'Clearing cookies', 'Renaming files randomly', 'Rebooting the phone', 'A', 'Versioned caches and immediate activation ensure users get the new release promptly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5355, 294, 'Which concern must a PWA handle for a good offline experience?', 'Gracefully showing offline state and queuing user actions', 'Showing a blank screen', 'Displaying errors', 'Disabling the UI', 'A', 'Good PWAs communicate offline state and buffer user actions for later sync.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5356, 294, 'Which technique keeps a PWA fast by splitting code into chunks loaded on demand?', 'Code splitting and lazy loading', 'Loading everything at once', 'Using larger images', 'Disabling caching', 'A', 'Code splitting loads only what each screen needs, shrinking initial download.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5357, 294, 'Which best practice ensures the app shell loads quickly on repeat visits?', 'Precaching the app shell HTML, CSS and JS in the service worker', 'Precaching nothing', 'Reloading everything from the network', 'Using only inline styles', 'A', 'Precaching the app shell gives near-instant repeat loads even offline.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5358, 294, 'Which API lets a PWA store structured data offline beyond simple cache?', 'IndexedDB', 'Cookies', 'localStorage only', 'URL fragments', 'A', 'IndexedDB stores large structured data for offline, queryable access.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5359, 294, 'Which audit tool helps developers verify a PWA meets installability and performance criteria?', 'Lighthouse', 'A text counter', 'A spell checker', 'A screensaver', 'A', 'Lighthouse audits PWA, performance and accessibility criteria.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5360, 294, 'Which design most effectively handles offline writes that must sync later?', 'Queueing mutations in IndexedDB and replaying them when connectivity returns', 'Dropping the writes', 'Showing an error', 'Storing writes in memory', 'A', 'Offline write queues with replay preserve user actions until sync.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5361, 294, 'Which trade-off must be managed when using cache-first strategies for dynamic content?', 'Speed versus freshness, so content can go stale', 'Speed versus security', 'Freshness versus code size', 'No trade-off exists', 'A', 'Cache-first responses are fast but can serve outdated dynamic content.', 'ADVANCED', 3, 'MCQ', 1),
(5362, 294, 'Which approach best ensures a PWA receives push notifications on reconnection?', 'Handling push events in the service worker even when the app tab is closed', 'Ignoring the push', 'Only checking in-app', 'Requiring the user to open the app', 'A', 'Service worker push handlers display notifications without a foreground tab.', 'ADVANCED', 3, 'MCQ', 1),
(5363, 294, 'Which security control is essential for serving a PWA over production?', 'HTTPS with a valid certificate and no mixed content', 'HTTP everywhere', 'Trusting all certs', 'No encryption', 'A', 'A secure context is required for service workers, push and other PWA features.', 'ADVANCED', 3, 'MCQ', 1),
(5364, 294, 'Which strategy best minimises data usage for PWAs on mobile networks?', 'Compressing assets, cache-first policies and image optimisation', 'Sending full-size videos', 'Disabling compression', 'Loading all images eagerly', 'A', 'Compression and caching cut bandwidth, crucial on metered mobile connections.', 'ADVANCED', 3, 'MCQ', 1),
(5365, 294, 'Which measure best prevents stale caches from consuming unlimited storage?', 'Cache versioning and pruning old caches on activation', 'Never deleting caches', 'Storing everything forever', 'Disabling the cache', 'A', 'Versioned caches with cleanup keep storage bounded.', 'ADVANCED', 3, 'MCQ', 1),
(5366, 294, 'Which pattern best delivers an instant first paint for a PWA?', 'Precaching the app shell and serving it from the service worker immediately', 'Waiting for the full bundle', 'Showing a blank screen', 'Loading fonts last', 'A', 'An immediate shell render from the cache creates the illusion of native launch speed.', 'ADVANCED', 3, 'MCQ', 1),
(5367, 294, 'Which testing approach is essential for a PWA''s offline claims?', 'Testing the app with the network disabled across flows', 'Testing only online', 'Screenshots only', 'Never testing', 'A', 'Offline-mode testing verifies the claimed offline behaviour actually works.', 'ADVANCED', 3, 'MCQ', 1),
(5368, 294, 'Which design consideration most affects a PWA''s cross-device consistency?', 'Responsive layouts and touch-friendly interactions across screen sizes', 'Fixing one layout', 'Using only desktop', 'Ignoring small screens', 'A', 'Responsive, touch-friendly design keeps the PWA usable on every device.', 'ADVANCED', 3, 'MCQ', 1),
(5369, 294, 'Which practice best keeps a PWA''s notifications relevant and non-abusive?', 'Asking for permission in context and respecting user opt-out', 'Sending constant alerts', 'Forcing notifications', 'Hiding the unsubscribe', 'A', 'Respectful permission and opt-out handling protect the user experience.', 'ADVANCED', 3, 'MCQ', 1),
(5370, 294, 'Which metric best reflects the real-world performance of a PWA for returning users?', 'Repeat-visit load time served from the service worker cache', 'First-visit download only', 'The number of screens', 'The logo size', 'A', 'Repeat-visit shell loads measure the cached, offline-capable experience users get most.', 'ADVANCED', 3, 'MCQ', 1),
(5371, 295, 'How is edge computing best described?', 'Processing data closer to the user or device rather than in a central cloud', 'Storing data on the moon', 'Using only mainframes', 'Removing all servers', 'A', 'Edge computing moves computation near the data source to cut latency and bandwidth.', 'BEGINNER', 1, 'MCQ', 1),
(5372, 295, 'Which technology caches static content at servers near users?', 'CDN', 'A database', 'A compiler', 'An email server', 'A', 'Content Delivery Networks replicate content to edge servers close to users.', 'BEGINNER', 1, 'MCQ', 1),
(5373, 295, 'Which of the following is a benefit of serving content from the edge?', 'Lower latency for users', 'Higher electricity bills', 'More server downtime', 'Slower page loads', 'A', 'Edge servers reduce the physical distance data travels, lowering latency.', 'BEGINNER', 1, 'MCQ', 1),
(5374, 295, 'What is a CDN edge node?', 'A server placed near users to serve cached content', 'A central mainframe', 'A local printer', 'A network cable', 'A', 'Edge nodes are distributed servers that cache and serve content close to users.', 'BEGINNER', 1, 'MCQ', 1),
(5375, 295, 'Which static site pattern deploys the built site to edge CDN servers?', 'JAMstack-style static deployment', 'A giant dynamic app', 'A database cluster', 'An email blast', 'A', 'Static site generation plus a CDN is a classic edge deployment pattern.', 'BEGINNER', 1, 'MCQ', 1),
(5376, 295, 'Which problem does edge caching help solve?', 'Slow response times for geographically distant users', 'Too much RAM', 'Broken keyboards', 'Small screens', 'A', 'Caching at the edge brings content physically closer to users, speeding delivery.', 'BEGINNER', 1, 'MCQ', 1),
(5377, 295, 'What does ''origin server'' mean in a CDN setup?', 'The source server that holds the canonical content', 'A backup tape', 'The user''s browser', 'The DNS server', 'A', 'The origin is the authoritative source from which edge nodes fetch content.', 'BEGINNER', 1, 'MCQ', 1),
(5378, 295, 'Which response header helps a CDN cache a resource?', 'Cache-Control', 'Content-Length', 'Host', 'User-Agent', 'A', 'Cache-Control instructs CDNs and browsers how long a resource may be cached.', 'BEGINNER', 1, 'MCQ', 1),
(5379, 295, 'Which type of workload is least suitable for edge execution?', 'Huge batch analytics over petabytes in one place', 'Low-latency feature flags', 'Localised content delivery', 'Fast API responses', 'A', 'Massive centralised data processing is better suited to large cloud data centres than the edge.', 'BEGINNER', 1, 'MCQ', 1),
(5380, 295, 'Which deployment benefit does edge computing bring to IoT devices?', 'Reduced need to send all raw data to a central cloud', 'Larger screens', 'More batteries', 'Longer cables', 'A', 'Processing at the edge filters and reduces what must travel to the cloud.', 'BEGINNER', 1, 'MCQ', 1),
(5381, 295, 'A CDN serves stale content after a deploy. Which practice forces immediate refresh?', 'Busting cache by purging or versioning the resource URL', 'Waiting for expiry', 'Disabling the CDN', 'Renaming the domain', 'A', 'Cache purging or versioned URLs ensures the new content reaches users immediately.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5382, 295, 'Which edge function pattern lets developers run small bits of code near users?', 'Edge functions or serverless at the edge', 'A single VM', 'An FTP server', 'A cron job on a laptop', 'A', 'Edge functions execute small, event-driven logic at edge locations.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5383, 295, 'Which technique adapts content to each user''s device and network at the edge?', 'Device detection and dynamic delivery at the edge', 'Sending the same giant file', 'Ignoring device type', 'Using only desktop layouts', 'A', 'Edge delivery can tailor images and responses to each client''s capabilities.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5384, 295, 'Which trade-off must be considered when moving compute to the edge?', 'Limited resources on edge devices versus lower latency', 'Unlimited resources', 'Higher latency always', 'No security concerns', 'A', 'Edge devices have constrained CPU and memory compared with cloud data centres.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5385, 295, 'Which concern is critical for a globally distributed edge deployment?', 'State consistency and where user state is stored across regions', 'The logo colour', 'The font size', 'The email signature', 'A', 'Distributed state must be reconciled so users see consistent data across edge regions.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5386, 295, 'Which strategy most reduces bandwidth when many clients request the same popular video?', 'Edge caching the video at regional CDN nodes', 'Streaming from one origin every time', 'Emailing the video', 'Disabling caching', 'A', 'Edge caches serve popular content locally, dramatically cutting origin bandwidth.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5387, 295, 'Which deployment approach lets a team change routing rules without redeploying applications?', 'Edge-configurable routing and feature flags', 'Rewriting the whole app', 'Rebooting servers', 'Changing hardware', 'A', 'Edge-level configuration provides instant, low-risk traffic and behaviour changes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5388, 295, 'Which benefit does edge rendering provide for dynamically personalised pages?', 'Generating personalised HTML near the user for fast delivery', 'Storing one generic page', 'Delaying rendering', 'Disabling personalisation', 'A', 'Edge rendering personalises pages close to the user, keeping them fast and unique.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5389, 295, 'Which measure protects the origin server from being overwhelmed by traffic?', 'Edge caching and rate limiting at the CDN layer', 'Sending all traffic to origin', 'Removing rate limits', 'Disabling caching', 'A', 'Edge caching absorbs repeat requests and rate limiting protects the origin.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5390, 295, 'Which architecture best serves a global audience with sub-second page loads?', 'A static or SSR site fronted by a CDN with edge caching', 'One server in one region', 'An FTP server', 'A peer-to-peer email system', 'A', 'A CDN-fronted site puts content near every user, delivering consistent low latency.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5391, 295, 'Which strategy keeps an edge deployment consistent during a live deploy?', 'Rolling updates across edge regions with health checks', 'Switching all regions at once', 'Deploying to one node only', 'Skipping health checks', 'A', 'Progressive region-by-region rollouts with health verification limit blast radius.', 'ADVANCED', 3, 'MCQ', 1),
(5392, 295, 'Which consideration most affects the choice between edge and cloud compute for a function?', 'The function''s latency budget and the data it needs access to', 'The function''s colour', 'The developer''s location', 'The repository name', 'A', 'Latency requirements and data locality determine whether edge or cloud fits better.', 'ADVANCED', 3, 'MCQ', 1),
(5393, 295, 'Which pattern handles personalisation while still leveraging edge caching?', 'Caching the shell and personalising via client-side or edge logic', 'Caching personalised pages for everyone', 'No caching', 'Serving everyone identical pages', 'A', 'Splitting cached shells from personalised data preserves both speed and uniqueness.', 'ADVANCED', 3, 'MCQ', 1),
(5394, 295, 'Which measure most effectively mitigates a DDoS against a CDN-fronted site?', 'Edge-level traffic filtering and absorption by the CDN', 'Letting traffic reach the origin', 'Closing the website', 'Disabling security', 'A', 'CDNs absorb and filter large attack volumes before they reach the origin.', 'ADVANCED', 3, 'MCQ', 1),
(5395, 295, 'Which deployment principle most improves resilience across edge regions?', 'Designing regions to fail independently with automatic failover', 'Tying everything to one region', 'Using no failover', 'Deploying once', 'A', 'Independent, redundant regions let the system survive regional failures.', 'ADVANCED', 3, 'MCQ', 1),
(5396, 295, 'Which metric best captures the benefit of edge deployment?', 'Time to first byte and end-user latency measured worldwide', 'The number of servers', 'The code size', 'The domain length', 'A', 'Global latency metrics directly show the edge''s impact on real users.', 'ADVANCED', 3, 'MCQ', 1),
(5397, 295, 'Which strategy keeps stale data from being served at the edge after a data change?', 'Cache invalidation triggered by origin updates', 'Never invalidating', 'Restarting the CDN', 'Ignoring updates', 'A', 'Origin-triggered invalidation clears stale edge copies when data changes.', 'ADVANCED', 3, 'MCQ', 1),
(5398, 295, 'Which trade-off arises when edge functions use short CPU and memory limits?', 'Heavy processing must be moved back to the cloud', 'Processing becomes unlimited', 'Latency increases everywhere', 'Security improves automatically', 'A', 'Edge functions are limited, so compute-heavy work still belongs in the cloud.', 'ADVANCED', 3, 'MCQ', 1),
(5399, 295, 'Which approach best secures edge function code and secrets?', 'Keeping secrets in edge-provider secret stores and validating all inputs', 'Hard-coding secrets', 'Shipping secrets publicly', 'No validation', 'A', 'Secret stores and input validation protect edge code from exposure and injection.', 'ADVANCED', 3, 'MCQ', 1),
(5400, 295, 'Which testing strategy best validates a global edge deployment?', 'Synthetic tests from multiple geographic locations measuring performance', 'Testing from one office', 'Screenshots only', 'No monitoring', 'A', 'Multi-region synthetic monitoring verifies real-world edge performance everywhere.', 'ADVANCED', 3, 'MCQ', 1);
